INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397054154', 'Capa Proteção Correia Dentada Fiat Siena 2006 a 2009 - 184606 - 6101/3217', 'Capa Proteção Correia Dentada Fiat Siena 2006 a 2009 184606 6101/3217 1.0 8V FIRE FLEX (EXTERNA - SUPERIOR) O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 25.89, 25.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822zc-mo9suc3asw750e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23397054154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
