INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198705157', 'Jogo de Chave Torx Curta com Guia TX T10 à T50 MTX 09 Peças', 'Jogo de Chave Hexalobular Torx Curta com Guia FuroTX T10 a T50 9 pecas MTX 123059 O Jogo de Chave Torx Tipo L 9Peças T10a T50 Profissional da marca MTXé a ferramenta perfeita para quem precisa lidar com parafusos com formato Torx. Com o modelo 123059, você terá um conjunto completo de chaves que vão desde a T10até a T50, todas em formato L, o que proporciona um excelente encaixe e torque na hora de apertar ou soltar os parafusos. Além disso, as chaves deste jogo contam com um furo na extremidade oposta à cabeça, o que permite usá-las em parafusos com pino central. Isso torna o conjunto ainda mais versátil, possibilitando o uso em diferentes tipos de equipamentos. O Jogo de Chave Torx Tipo L 9Peças T10a T50 Profissional MTXvem acompanhado de um suporte plástico para organização e armazenamento das ferramentas. Assim, você pode mantê-las sempre à mão e de maneira segura, evitando perda ou danos às chaves. Jogo de Chaves Torx curta, produzidas em aço cromo vanádio e acabamento acetinado, projetadas para trabalhar com peças que tem cavidade interna hexalobular. A extremidade longa pode ser usada no trabalho para alcançar lugares difíceis. Composto por 9 peças: T10, T15, T20, T25, T27, T30, T40, T45 e T50 Imagens Meramente Ilustrativas', 31.67, 31.67, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvr-mbo5u55dta3aac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F22198705157', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17458103982', 'Grip Silicone PS5 GXT 266 4 peças 2 cores 24170 Trust', 'Grip Silicone PS5 GXT 266 Botão Analógico - 4 peças 2 cores - 24170 Trust &nbsp; - Tenha um maior controle sobre os jogos com as capas aderentes para os botões analógicos do teu comando - Conjunto de 4 capas aderentes no total, dois dos quais brilham no escuro - Cada capa aderente para contém texturas com pontos para maior aderência e controle - Impede o desgaste por utilização do comando - De fácil aplicação, remoção e limpeza &nbsp; Controle Preciso Você tem um PlayStation 5 novinho em folha? Bem-vindo aos jogos de última geração! Para ajudá-lo a obter um bom controle de seu novo controlador DualSense PS5, esses thumbs grips da Trust estão lá para salvar o dia. Este conjunto possui um total de 4 alças de polegar, duas das quais brilham no escuro, para ajudá-lo a manter seus polegares nos manípulos analógicos. &nbsp; Menos Desgaste Além da empunhadura aprimorada, essas alças de polegar reduzirão o desgaste que seu controlador enfrenta durante o uso diário. E se ficarem sujos, essas alças de polegar são facilmente removíveis e limpáveis. Então, comece o jogo e mantenha-o limpo. &nbsp;SKU:&nbsp;T24170 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;', 19.9, 19.9, NULL, 'Gaming & Consoles > Console Accessories', 'https://cf.shopee.com.br/file/3e656076a677fa0aabeb8ecbead28ed1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705938272%2F17458103982', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593104855', 'Creme Cicatricure Contorno dos Olhos 15g - Diminui Rugas com tecnologia BioRegenext', 'O peso líquido do conteúdo é de 15g. O Creme Cicatricure Contorno dos olhos reduz o volume das bolsas com o uso regular do produto em 28% aos 15 dias e em 40% aos 30 dias. Proporciona a diminuição da temperatura da região aplicada, após 2 minutos da aplicação, produzindo um efeito refrescante que relaxa a pele, reduzindo o volume das bolsas. Cicatricure Contorno de Olhos foi especialmente formulado com tecnologia BioRegenext e Soft Focus que, em cada aplicação, disfarça sinais da idade e alisa o contorno dos olhos. O Creme Contorno dos Olhos diminui rugas e linhas de expressão, proporcionando olheiras menos visíveis e uma sensação de relaxamento. Modo de Uso: Aplique diariamente no período da manhã e no período da tarde sobre a região, massageando até a completa absorção.', 68.28, 52.9, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/br-11134207-820l4-mmkgfosivm6eab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1284050214%2F22593104855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
