INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41511198144', 'Tênis Feminino Básico Casual Confortável Via Marte Original', 'Tênis Feminino Casual Via Marte Modelo: 064-001-01 É a escolha certa para quem busca um visual moderno com o conforto que o dia a dia exige. Com design clean e detalhes sutis, ele combina perfeitamente com produções casuais e despojadas. Sua palmilha macia oferece conforto a cada passo, enquanto o solado emborrachado garante segurança e estabilidade. O fechamento em cadarço permite um ajuste ideal aos pés, tornando este modelo uma ótima opção para acompanhar você em todas as ocasiões. Diferenciais do Produto: - Design casual com visual moderno e feminino; - Palmilha acolchoada para maior conforto; - Solado emborrachado: aderência e estabilidade; - Fechamento em cadarço para ajuste perfeito; - Versátil: combina com diversos estilos e looks. O Tênis Feminino Casual Via Marte pode ser encontrado aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 299.99, 299.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820l8-mnzp0ncn67sy8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F41511198144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
