INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254660613', 'Polisten Transparente Stain Impregnante Premium 900ml Acabamento Acetinado', 'Distribuído Por Edu Tintas! POLISTEN TRANSPARENTE 900ML – Stain Impregnante Premium Indicado para portas, portões, janelas, esquadrias, cercas, lambris, casas pré-fabricadas de madeira, móveis de madeira para jardins e madeiras decorativas em geral. Fácil de aplicar, com ação fungicida e inseticida, hidrorrepelente, realça os veios da madeira, fácil manutenção, não forma filme, com filtro solar. Para um acabamento com mais brilho, é recomendável a aplicação de uma demão do Verniz Marítimo Poliulack. Cor: Transparente Observação: Pode alterar a tonalidade da cor da madeira quando aplicado em madeiras claras. Acabamento: Acetinado Viscosidade: 12 2s CF4 a 25CDensidade: 0,861 0,020 g/cmSólidos: 33,03 2%Armazenagem. Manter o produto com a embalagem fechada, em local coberto, à sombra, seco e ventilado. Recomendações: Para preservar a saúde, aconselha-se o uso de equipamentos de segurança adequados, como óculos, máscaras e luvas para a aplicação deste produto. Rendimento: 17m² por 900ml/demão, podendo variar de acordo com a preparação da superfície, método e técnicas de aplicação, diluição e absorção da madeira. Conservação e limpeza: Limpar a superfície pintada com um pano levemente umedecido com água. Para limpeza dos utensílios de pintura, utilizar Sayerraz DS 451.Distribuído Por Edu Tintas!', 57.46, 57.46, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkbe1toqsetd24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1462074750%2F58254660613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893299075', 'Paralama Preto Cg Titan Fan 125/150/2000 a 2013', 'Atenção! ** PRODUTO A PRONTA ENTREGA, COM ENVIO IMEDIATO ** ** VOCÊ ESTÁ PROTEGIDO PELO PROGRAMA COMPRA GARANTIDA DA SHOPEE ** O Para-lama Para CG 125 é compatível com os modelos do ano de 2000 até 2013 e o Para-lama Para CG150/160 é compatível com os modelos do ano de 2009 até 2013. Características: - Paralama de plástico - Injetado na cor preta - De alta qualidade e resistente - Paralama Dianteiro Dimensões: - Comprimento: 60cm - Largura: 12cm - Altura: 10cm Compatibilidade: - Modelo CG 125cc: Projetado para ser fixado nos garfos dianteiros da CG 125, possuindo furos para os parafusos de fixação. - Modelo CG 150cc: Projetado para ser fixado nos garfos dianteiros da CG 150, possuindo furos para os parafusos de fixação.', 24.9, 18.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rd3s-m7384amxsvsr4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306031322%2F23893299075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
