INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594353911', 'Caixa 1x8 + 2x6x/9 dutada', 'DESCRIÇÃO DO PRODUTO: A caixa automotiva boombastic 1x8 + 2 6x9 dutada é uma caixa feita para você! Além do design e acabamento impecável a qualidade do material é destaque. Uma caixa clean e moderna, sem ocupar muito espaço, mas com um ótimo desempenho. TECNOLOGIA A tecnologia usada para a confecção da caixa automotiva boombastic 1x8 + 2 6x9 dutada de alta performance! A caixa é usinada utilizando nossa CNC (Centro Automatizado de Usinagem), o que lhes proporcionam serem únicos no mercado por conta da precisão milimétrica e com uma qualidade jamais vista. CARACTERÍSTICAS O acabamento é outro ponto forte! * Revestimento externo em courvin e carpet * Aberto para um par de 6x9" * Aberto para um falante de 8" * Feita em MDF de 15 mm * Duto retangular - Altura 1,6 cm x Largura 26 cm (Não acompanha equipamentos – trata somente da caixa vazia) Compatível com todos modelos de falantes 6x9 CORES Courvin: preto carpet: grafite ESPECIFICAÇÕES Largura 68 cm Altura 31 cm Comprimento em cima 20 cm Comprimento em baixo 31 cm Profundidade para instalação do falante de 8’’ 18,5 cm Profundidade para instalação dos 6x9 22 cm Litragem câmara de 8” 17 litros Litragem câmara 6x9 18 litros (9 em cada) Dimensões do duto: Altura 1,6 cm x Largura 26 cm Peso 7 kg', 162.0, 162.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mdyq9yvslaf51e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1598756230%2F23594353911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799093609', 'Painel Ripado para TV Até 75 Polegadas Intense com Nicho Slim', 'Buscando renovar a sua sala de estar? O sofisticado Painel Intense, é uma escolha perfeita para isso. Sua estrutura em MDP confere durabilidade e estabilidade, garantindo que seu televisor esteja seguro e bem acomodado. Projetado para TV de até 55 Polegadas, este painel combina funcionalidade e estilo de forma única com seu design premium. Além disso, conta com prateleiras espaçosa, perfeita para acomodar seus dispositivos eletrônicos, acessórios e itens decorativos. Suas bordas laqueadas traz um acabamento sofisticado, realçando ainda mais o charme deste painel. O nicho é um componente extremamente versátil que vem para agregar a composição junto com o painel. O painel Intense irá adicionar um toque especial ao seu espaço. Seu acabamento ripado proporciona um visual moderno e contemporâneo, trazendo uma textura única e refinada para a sua sala. ESPECIFICAÇÕES TÉCNICAS: - Material da Estrutura: MDP; - Acabamento: Ripado; - Número de Porta: Não Possui; - Possui Prateleiras? Sim; - Possui Nichos? Sim; - Ideal para Tvs até ( Polegadas): 55 Polegadas; - Produto Precisa de Montagem? Sim; - Necessita de Fixação na Parede? Sim; - Garantia: 3 Meses; - Instruções de Cuidado: Limpar com pano macio umedecido em solução de água e sabão neutro e secar em seguida.; - Medidas (LarguraXProfundidadeXAltura): 139x18x240cm; - Conteúdo da Embalagem: (1 Painel - Entregue: 03 Volumes).', 1169.9, 1129.0, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxu0vxr6h21e8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373150829%2F18799093609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
