INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898052871', 'Barbie Fashion & Beauty Boneca Praia com Maiô 1 Unidade Sortida DWJ99 Mattel - 103801', 'Esse produto é sortido! 1 unidade enviada conforme a disponibilidade no estoque. (não é possível escolher modelo/personagem) As bonecas Barbie® inspiram as crianças a mergulharem na narrativa! Cada boneca usa um traje de banho que celebra as tendências atuais, com cores brilhantes e um design arrojado. O visual único incentiva histórias reais de diversão ao sol, aventuras com tema aquático e muito mais! Inclui boneca com roupa de banho. Características: - Marca: Mattel - Modelo: 103801 - Idade mínima: 3 anos *AVISO: CONTÉM OU PODE GERAR PEÇAS PEQUENAS QUE PODEM CAUSAR ASFIXIA Conteúdo na Embalagem: Inclui 1 boneca com roupa de banho. As bonecas Barbie® não ficam em pé sozinhas. As cores e as decorações podem variar.', 62.34, 53.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rfgc-m36q3l9li9u678', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22898052871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397925155', 'Came Disco Contato Buzina Vw Gol Saveiro Parati G1 G2 G3 G4', 'Este anúncio contém: 01 (um) Disco came de contato da buzina. Aplicável nos seguintes veículos: Gol G1 G2 G3 G4; Saveiro G1 G2 G3 G4; Voyage G1; Parati G1 G2 G3 G4. Características do Produto: Produto novo, de ótima qualidade, com alta durabilidade e garantia; Ideal para reposição; Substitui o código original: 377419660A. O came é parte essencial do conjunto de elementos que compõe o sistema de acionamento de buzina em um veículo sem airbag. Sua principal função é proporcionar o contato elétrico do sistema de buzina com o volante, através da pista de contato. Ademais, o came é responsável pelo destravamento automático da seta de acordo com a rotação do volante. Importante: Preço unitário; Garantia 3 Meses; Alta Durabilidade; Qualidade Original; Produto Com Nota Fiscal.', 23.75, 23.52, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwk-m0xzs5x9yyx3b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1037769766%2F20397925155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
