INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694326838', 'Conjunto Infantil Blusão e Calça Guloseima', 'Cheio de charme e conforto, este conjunto para menina é feito em moletinho sem felpa, ideal para os dias mais leves. O blusão tem mangas longas, capuz, punhos e uma estampa fofa com detalhes em puff e glitter. A calça, com elástico na cintura e nos punhos, oferece liberdade de movimento e ajuste perfeito para todas as brincadeiras.Tecido: Blusão: Moletinho Sem Felpa (Algodão e Poliéster) | Calça: Moletinho Sem Felpa (Algodão e Poliéster)Composição: Blusão: 74%algodão 26%poliester | Calça: 74%algodão 26%poliesterModelagem: JustaComprimento Mangas: LongaComprimento: LongoForro: NãoCintura: MédiaDecote/Gola: Redondo', 189.9, 75.96, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-mdlusicv9gpw24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F23694326838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
