INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24094537146', 'Cúrcuma Longa pote 60 Cápsulas - FTW', 'Cúrcuma FTW é um suplemento alimentar em cápsulas desenvolvido com extrato de rizomas de cúrcuma longa. Reconhecida por suas propriedades antioxidantes e anti-inflamatórias, a fórmula é indicada para quem busca promover o bem-estar, fortalecer o sistema imunológico e contribuir para a saúde geral do organismo. Ingredientes Extrato de rizomas de cúrcuma longa, estabilizantes celulose microcristalina e amido, antiumectante dióxido de silício Cápsula composta por gelatina, corantes FD&C vermelho 40 e FD&C amarelo 6, opacificante dióxido de titânio, umectante água purificada filtrada Contém derivados de soja Não contém glúten Sugestão de Uso Ingerir duas cápsulas duas vezes ao dia ou conforme orientação de profissional da saúde Apresentação Frasco contendo 60 cápsulas Porção de quatro cápsulas fornece 2,4 gramas de extrato Informações Adicionais Produto indicado para adultos com 19 anos ou mais Este produto não é um medicamento Não exceder a recomendação diária de consumo indicada na embalagem Não deve ser consumido por gestantes, lactantes e crianças Manter fora do alcance de crianças Após aberto, consumir em até 60 dias Armazenar em local seco, ao abrigo da luz e calor Certificação Suplemento alimentar dispensado de registro conforme Resolução RDC nº 240/2018. Alegações baseadas no Anexo V da IN 28 Anvisa.', 69.52, 39.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf8fqm0criti08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397772996%2F24094537146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
