INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697602051', 'Pote Redondo Plástico Plasvale 600ml, com Tampa Rosca, Branco - 623', 'O Pote Redondo Plástico Plasvale 600ml é um ótimo aliado para o dia a dia. Livre de BPA, possui o tamanho perfeito para organizar suas refeições diárias, facilitando o seu dia a dia. Importante: Este produto é vendido em cores sortidas. Não é possível escolher a cor no ato da compra. O produto será entregue conforme disponibilidade no estoque. As imagens correspondem aos produtos apresentados, porém, são ilustrativas e podem sofrer variações de acordo com a resolução de seu monitor, iluminação ou ainda, percepção visual. Os objetos decorativos das imagens não acompanham os produtos.', 19.87, 15.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rd6l-lwzv6pxlj3vqec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F23697602051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257715412', 'Pijama Feminino Manga Longa Dreams Marialícia Cinza', 'Sinônimo de aconchego, o Pijama Marialícia é composto por blusa e calça em meia malha estampada. A blusa possui comprimento regular e mangas longas com punhos, além da frase "Shining Dreams" em glitter, trazendo um brilho especial para o momento do descanso. Já a calça conta com elástico no cós e punho nas barras. Para um charme extra, a estampa em ambas as peças garante harmonia e delicadeza. Aposte nesse pijama para aproveitar o seu momento de descanso com conforto e estilo!Detalhes da peça: • Pijama composto por blusa e calça • Feito em meia malha estampada • Comprimento regular • Possui mangas longas • Detalhe em glitter • Elástico no cós • Estampa em ambas as peças Modelo veste tamanho G1. Medidas da modelo: 105cm de busto; 125cm de quadril; e 90cm de cintura.', 179.9, 107.94, NULL, 'Women Clothes > Sleepwear & Pajamas > Pajamas', 'https://cf.shopee.com.br/file/sg-11134201-825ab-mr1tur71t4ao95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58257715412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493401426', 'Cappuccino em Pó Linea 150g', 'Linea Cappuccino não possui glúten e é uma excelente fonte de cálcio, contribuindo para a ingestão diária deste mineral. Sem adição de açúcares, é adoçado com sucralose, o adoçante derivado da cana de açúcar que contribui para a redução de sódio e calorias. Não possui canela em sua composição, o que permite ao consumidor adicioná-la se for do seu paladar. Proporciona um sabor envolvente, sendo uma escolha perfeita para aqueles que buscam uma opção deliciosa. INGREDIENTES: Maltodextrina, leite em pó desnatado, café solúvel, cacau em pó, regulador de acidez: bicarbonato de sódio e fosfato tricálcico, espessante goma xantana, aromatizantes e edulcorantes: sucralose e acesulfame de potássio. ALÉRGICOS: CONTÉM DERIVADO DE LEITE. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN.', 25.19, 23.93, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcwj3c9ep81td7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23493401426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492528699', 'Coxim Motor Vw Crossfox 2005 a 2020 - 514828 - ACX01011', 'Coxim Motor Vw Crossfox 2005 a 2020 514828 ACX01011 (Traseiro) (Motor/Câmbio) (Sem Suporte) São divididos em 3 grupos: coxins do motor, coxins do câmbio e coxins do amortecedor. A função do coxim de motor/câmbio é ser o ponto de apoio do motor no chassi, fazendo a absorção da vibração do motor e evitando que seja transmitido para o veículo. O uso de coxins danificados diminuirá significativamente a vida útil do motor/câmbio do veículo.', 127.58, 127.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbkd-lmqk9ryvf603cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23492528699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297470524', 'FIltro Ar Condicionado PALIO 2006/2017 - 37261 - AKX35321', 'FIltro Ar Condicionado PALIO 2006/2017 (Weekend) - (Attractive/Trakking/ELX) - Motor 1.4 8v Flex Evo / (Trekking) - Motor 1.6 16v Flex - (Mecânico) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 23.65, 23.65, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7raur-maovb5qgfrz68b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23297470524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
