INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599214907', 'Sandália Feminina Preto Elegante Salto Alto Ramarim 2541210-3', 'ATENÇÃO!!! POR FAVOR CONFERIR A TABELA DE MEDIDAS NO FINAL DA DESCRIÇÃO E NAS FOTOS DO ANÚNCIO! Sandália Feminina Ramarim Salto Alto 9 cm – Tiras Finas e Esferas Decorativas Elegante, moderna e marcante, esta sandália Ramarim foi criada para quem busca estilo com conforto. O design com tiras finas, aplicação de esferas glam e salto bloco alto de 9 cm entrega um visual sofisticado para compor looks de festa, trabalho ou eventos especiais. Confeccionada em material sintético de alta qualidade, oferece firmeza, estabilidade e um acabamento impecável. Características do produto • Confeccionada em material sintético macio e resistente • Design com tiras finas que valorizam o peito do pé • Esferas decorativas que trazem charme e sofisticação • Salto bloco alto de 9 cm com base larga para mais estabilidade • Palmilha suave que garante mais conforto ao caminhar • Solado aderente, pensado para oferecer segurança • Fechamento lateral com fivela ajustável • Ideal para looks elegantes e modernos Dica de moda Combine com vestidos midi, saias fluidas ou alfaiataria para um visual refinado. Para a noite, funciona perfeitamente com looks monocromáticos e acessórios metalizados. Dica de limpeza Passe um pano levemente umedecido com água e sabão neutro. Evite produtos abrasivos e deixe secar à sombra. Guarde sempre em local arejado. Sugestões de uso Perfeita para festas, casamentos, formaturas, trabalho, jantares, eventos formais ou para elevar o visual do dia a dia. MEDIDAS: 33 - 22,1 CM 34 - 22,8 CM 35 - 23,5 CM 36 - 24,1 CM 37 - 24,8 CM 38 - 25,4 CM 39 - 26,1 CM', 239.9, 215.91, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-8225o-mhvp3jju8i697a', 'https://sh