INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197994015', 'Tonalizante Marrom Avelã 7.7 Sem Amônia 90g Retoque Raiz bn.Cachos', 'O Tonalizante Marrom Avelã foi feito para quem sonha com uma solução prática e rápida, que ainda trate os fios enquanto colore, chegou o bn.RETOQUE, o tonalizante sem amônia do bn.Cachos para usar em casa! Sua fórmula exclusiva com a tecnologia COLOR CACHOS, especialmente desenvolvida para cabelos cacheados, crespos e ondulados, preserva a fibra capilar enquanto colore. Além disso é totalmente compatível com cabelos quimicamente tratados. Com certeza vocês estão tão animadas quanto a gente. Ingredientes: ÁGUA, ÁLCOOL CETIL E ESTEARÍLICO, ETANOLAMINA, LAURETH-3, SULFATO DE TOLUENO-2,5-DIAMINA, PROPILENO GLICOL, ESTEARATO DE GLICERILA SE, ÓLEO DE RICINO HIDROGENADO PEG-40, COCAMIDOPROPIL BETAÍNA, FOSFATO DE OLEÍNA, FOSFATO DE OLETH-4, RESORCINOL, m-AMINOFENOL, PERFUME (FRAGRÂNCIA), FOSFATO DE ETILHEXILA/POTASSIUM ISOTRIDECETH-8, SULFITO DE SÓDIO, 2,4-DIAMINOFENOXIETANOL HCl, EDTA, POLIQUATERNÁRIO-22, ÁCIDO ERITÓRBICO, EXTRATO DE KAPPAPHYCUS ALVAREZII, EXTRATO DE LAMINARIA SACCHARINA, EXTRATO DE SEMENTE DE CHENOPODIUM QUINOA, FOSFATO DIPOTÁSSICO, SORBITOL, EXTRATO DE EUCHEUMA SPINOSUM, GOMA DE ACÁCIA DO SENEGAL, GLICERINA, FENOXIETANOL, SORBATO DE POTÁSSIO, BENZOATO DE SÓDIO, GLICERINA ETILHEXYL, ÁCIDO LÁTICO, TETRASSÓDIO EDTA.', 29.99, 25.99, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rfib-m40nzrwzgyzff7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F19197994015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9044452091', 'Borracha Porta Malas Tipo Original Fiat Bravo Todos', 'Detalhes do Produto: Borracha Porta Malas Tipo Original Fiat Bravo Todos Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Fiat Bravo Todos Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Tamanho: 4,20m Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor unitário Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 01 Borracha para o porta malas (02 anos de garantia)', 92.36, 92.36, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/fda2b4fc357f5bf30286ea6fd3fde082', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F9044452091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
