INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293747122', 'Oleo Motor 5W40 sn Sintetico BMW 325I 2.8 24v E36 - 80631 - MO1012', 'Oleo Motor 5W40 sn Sintetico BMW 325I 2.8 24v E36 Oleo 100% sintético multiviscoso de alta performance, desenvolvido para motores 4 tempos movidos a gasolina, etanol, flex e GNV, são formulados para atender e melhorar o desempenho dos veículos e na economia de combustívelLubrificante sintético, produzido em um processo químico mais caro, possibilita um melhor desempenho se comparado ao óleo mineral. Estes óleos, que passam por um processo de reações químicas, são mais resistentes ao calor e menos voláteis do que os lubrificantes minerais. O óleo sintético flui com mais facilidade a temperaturas de partida, momento em que o desgaste é maior.', 59.27, 59.27, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd3o-m6u5t7bzv9cx96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23293747122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22095793122', 'WHISKY JACK DANIELS HONEY 1000ML', '*ATENÇÃO: PRODUTO NÃO ACOMPANHA CAIXA* Jack Daniel''s Tennessee Honey foi criado especialmente para o público jovem, que está começando a apreciar whiskey, mas ainda não gosta do sabor forte e seco do whiskey tradicional. O licor apresenta um suave sabor de whiskey e mel, sendo ideal para todos que procuram um equilibrio entre sabor e refrescância. Pode ser apreciado em ocasiões mais informais, como festas e baladas, até em clima de praia. A sugestão é consumir puro e bem gelado, direto do congelador, mas também vai muito bem em drinks! De acordo com as leis que regulamentam a produção de whisky nos Estados Unidos, Jack Honey não pode ser considerado um tennessee whiskey e nem mesmo um whiskey, é apresentado no rótulo da garrafa como um Honey Liqueur Blended with Jack Daniel?s Tennessee Whiskey (Licor de Mel misturado com Jack Daniel''s Tennessee Whiskey). Na legislação brasileira se enquadra na categoria das bebidas compostas.', 169.9, 149.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-7qvfu-lh59l34846h751', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F22095793122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20807184873', 'VINHO GALO LUSITANO BRANCO 750ML', 'O vinho Galo Lusitano é produzido na região norte de Portugal, próximo à Barcelos. Os vinhedos estão instalados em solo granítico, numa zona de terreno irregular. A proximidade com o Atlântico proporciona um clima mais ameno e com pouca chuva. A soma dessas características se traduz num terroir de excelência para elaboração de vinhos. Elaborado a partir de castas selecionadas, colhidas manualmente, bem maduras, e vinificadas usando a mais moderna tecnologia. Com um desengace total, prensagem suave e fermentação com temperatura controlada, os vinhos preservam todas as características aromáticas das castas que lhes deram origem. Elaborado a partir das uvas Arinto e Loureiro, possui aromas tropicais e toques cítricos, no paladar é elegante e fresco.', 35.88, 35.88, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/49e0ca1f1a89f9de2fe71acba4075bba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F20807184873', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093534650', 'Boneco Funko Pop! Star Wars Mandalorian Grogu de Natal', 'Adicione um toque festivo à sua coleção com o Boneco Funko Pop! Grogu com Biscoito de Natal. Este encantador Boneco Funko Pop! captura Grogu celebrando o feriado com um delicioso biscoito, pronto para ser o próximo item da sua coleção. A figura de vinil com cabeça oscilante tem aproximadamente 10 centímetros de altura, é uma peça indispensável para fãs de Star Wars: The Mandalorian. Reúna Grogu com seu companheiro Mandaloriano e celebre o espírito natalino na galáxia!', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rfgt-m3jkz8z0mzfr3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F22093534650', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
