INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492528586', 'Capa Proteção Correia Dentada Gm Corsa 1996 a 2003 - 516492 - 6170', 'Capa Proteção Correia Dentada Gm Corsa 1996 a 2003 516492 6170 Motor 1.0/1.6 16v - (Interna) O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 121.18, 121.18, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rblr-lmqjg5sdkhbd2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492528586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19457310703', 'Coloração Keune So Pure Color 9 Louro Muito Claro', 'A Coloração Keune So Pure Color Foi desenvolvida com a tecnologia mais avançada para evitar danos a saúde dos cabelos, sua fórmula não contém amônia e é enriquecida com Fitoqueratina e óleo de Argan. A Coloração Keune So Pure Color possibilita 100% de cobertura dos fios brancos, E livre de PPD Parafenilenodiamina (grande causador de alergias), além de possui extratos 100% naturais, que hidrata seus cabelos enquanto colore. Ativos: - Fitoqueratina: Extraída de plantas que proporciona fortalecimento e brilho aos cabelos; - Extrato de Coco: evita que a coloração manche a pele e o couro cabeludo e condiciona os cabelos; - Óleo de Argan: Proporciona fortalecimento dos fios e proteção contra agentes externos; - Jasmin: Hidrata os cabelos, e evita oxidação e o desbotamento da cor; - Sândalo: Auxilia no equilíbrio de couro cabeludo seco e oleoso. Sobre a marca: Produzimos produtos para o cabelo para profissionais desde 1922, mas somos mais que um fornecedor. Seja nosso parceiro e você se juntará automaticamente à nossa família global. E não estamos dizendo isso apenas porque somos uma empresa familiar. Nós realmente nos preocupamos com você, seu salão e a pessoa em sua cadeira. É por isso que fazemos negócios com um toque pessoal.', 128.12, 128.12, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-82595-mqduzknu4tfv11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F19457310703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597751387', 'Purificador de Água Natural Purificador de Água Elimina Odores e Gosto da Água - Easy Acquabios', 'Purificador de água Easy Água pura, facilidade para o seu dia e design moderno! É o que a linha de purificadores Easy oferece! Compactos e práticos, são 3 cores disponíveis para combinar com a sua casa! Inspiração e design completos para você! Cores: Preto Vermelho Branco Indicações de uso: Purificador de água natural. Acionamento de água com um clique. Compacto e prático. Refil Girou, Trocou. Elimina sabores e odores: água livre de cheiro e gosto. Água livre de impurezas: retém micropartículas presentes na água, como barro, areia, ferrugem e sedimentos. Saída de água articulável para recipientes maiores. Bandeja removível (pingadeira): para esvaziar ou higienizar. Pés antiderrapantes: melhora a aderência do purificador na bancada. Características: Vazão máxima recomendada - 40 L/h Pressão - 50 kPa a 400 kPa Temperatura - 10°C a 40°C Eficiência na retenção de partículas Vida útil - 1.500 L Com redução de cloro livre', 433.8, 303.66, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/br-11134207-820mb-mptnz8q8z85c3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F22597751387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258025023', 'INOVA Fone de ouvido bluetooth 5.4 sem fio Pro4 Premium HiFi 9D Estéreo Alta Fidelidade Fone Microfone', '📦 Conteúdo da Embalagem 🎧 1x Par de Fones de Ouvido Inova 🔌 1x Cabo de Carregamento USB 📖 1x Manual de Instruções 🎧 4x Protetores auriculares **Cancelamento de Ruído com AI** A tecnologia de Cancelamento de Ruídos com Inteligência Artificial reduz em 90% os ruídos ambientais, melhorando significativamente a nitidez das suas chamadas. Converse em qualquer lugar com total clareza, sem se preocupar com o barulho à sua volta. **Conforto e Ajuste Perfeito** Confeccionados com materiais de alta qualidade, proporcionam um ajuste ergonómico que se adapta a diferentes formatos de ouvido. Este design inteligente garante 300% mais estabilidade e 200% mais conforto, permitindo que utilize os fones por horas sem incómodo. **Resistente e Durável para o Dia a Dia** Com certificação IPX5, os fones são totalmente resistentes à água, protegendo contra suor, humidade e respingos. São o companheiro ideal para os seus treinos, momentos de lazer ou para o uso diário, sem preocupações. **Bateria de Longa Duração** A bateria de alta performance oferece até 3 horas de música contínua com uma única carga, perfeito para acompanhar a sua rotina e momentos de descontração. **Tecnologia e Conectividade Avançada** Equipados com o moderno chip Bluetooth Dual-Core V5.4, garantem uma conexão estável, de alto desempenho e com latência ultrabaixa. A experiência é perfeita para jogos, filmes e chamadas de vídeo, onde cada milissegundo faz a diferença. A compatibilidade é total com dispositivos iOS e Android, permitindo uma conexão fácil e rápida. **Qualidade Sonora Imersiva** Mergulhe num som de alta qualidade com um detalhamento e nitidez superiores (92% de melhoria na clareza). A tecnologia proporciona 3 vezes mais qualidade sonora, resultando em graves potentes, médios equilibrados e agudos cristalinos para uma experiência auditiva verdadeiramente imersiva.', 139.0, 69.9, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/br-11134207-820ll-mmijntdayvwg7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1573953914%2F58258025023', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
