INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43511053977', 'Brinco Feminino de Prata 925 Coração Duplo Detalhado e Vazado', 'Brinco Feminino de Prata 925 Coração Duplo Detalhado e Vazado: Elegância e Charme O Brinco Feminino de Prata 925 Coração Duplo Detalhado e Vazado é perfeito para quem busca um acessório delicado e cheio de estilo. Com um design de dois corações entrelaçados, sendo um detalhado e o outro vazado, este brinco traz uma combinação de sofisticação e romantismo. Feito com Prata 925 de alta qualidade, oferece resistência, brilho e durabilidade. Especificações do Brinco Tamanho: 8mm Tamanho dos Corações: 3mm e 5mm Peso: 0,48g Material: Prata 925 Destaques do Brinco Design elegante de dois corações entrelaçados, um detalhado e o outro vazado, perfeito para adicionar um toque de sofisticação ao seu look. Feito com Prata 925 de alta qualidade, garantindo brilho, resistência e durabilidade. Leve e confortável, ideal para o uso diário ou para ocasiões especiais. Romantismo e Elegância em um Só Acessório O Brinco Feminino de Prata 925 Coração Duplo Detalhado e Vazado é ideal para quem busca um toque de romantismo e sofisticação. Seu design único e detalhado vai complementar seu look com muito estilo e elegância. Cuidados com o Brinco Evite o contato com produtos químicos para preservar o brilho da prata. Guarde em local seco e seguro para evitar arranhões e oxidação. Limpe regularmente com uma flanela macia para manter o brilho e a beleza do brinco. Adicione Sofisticação e Charme ao Seu Estilo Adicione o Brinco Feminino de Prata 925 Coração Duplo Detalhado e Vazado à sua coleção e experimente um acessório que combina elegância, sofisticação e romantismo, perfeito para qualquer ocasião.', 36.6, 32.94, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcup1m6wvif533', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F43511053977', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255985872', 'Coenzima Q10 Maxinutri 60 Cápsulas', 'Uma nutrição equilibrada tem um papel muito importante na qualidade de vida. Com o ritmo acelerado de muitas pessoas, às vezes, é muito difícil prestar atenção a todos os requisitos que o corpo precisa para estar saudável e forte. Neste sentido, os suplementos cumprem a função de complementar a alimentação e ajudam a obter as vitaminas, minerais, proteínas e outros componentes indispensáveis para o correto funcionamento do organismo. *Este produto é um suplemento dietético, não é um medicamento. Suplementa Ante dietas insuficientes. Consulte seu médico e / ou farmacêutico. Aviso legal • Idade mínima recomendada: 19 anos. • Consumir junto com alimentos para facilitar sua assimilação. • Este produto é um suplemento dietético, não um medicamento. Suplementa dietas insuficientes. Consulte o seu médico e/ou farmacêutico.', 72.32, 64.0, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-8261i-ml8dkokzypdxa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58255985872', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205993997', 'Dimag MDK 400mg Suplemento Alimentar 60 Cápsulas Maxinutri', 'O Dimag MDK 400mg da Maxinutri é um suplemento alimentar de alta performance desenvolvido para fortalecer a saúde dos ossos, músculos e o sistema cardiovascular. Sua fórmula exclusiva combina uma alta concentração de Magnésio Dimalato (400mg) com as vitaminas essenciais D3 e K2, além de Minerais Quelatos, garantindo máxima absorção pelo organismo sem causar desconforto gástrico. Esta combinação sinérgica é ideal para quem busca mais disposição no dia a dia, prevenção de dores musculares e manutenção da densidade óssea ideal. 🛡️ Principais Benefícios Ossos Fortes: A vitamina K2 direciona o cálcio para os ossos e dentes. Artérias Livres: Evita o depósito de cálcio nas paredes das artérias. Adeus Cãibras: O magnésio dimalato reduz dores e espasmos musculares. Mais Energia: O ácido málico ajuda na produção de energia celular (ATP). Imunidade Alta: A vitamina D3 fortalece as defesas naturais do corpo. Absorção Máxima: Minerais quelatos possuem maior biodisponibilidade intestinal. Diferenciais do Magnésio Dimalato O Magnésio Dimalato une o magnésio ao ácido málico. Essa junção faz com que o mineral seja liberado de forma prolongada no organismo. O resultado é um aproveitamento muito maior pelo corpo, além de ser a forma de magnésio que menos causa desconforto ou efeito laxativo no estômago. Especificações Técnicas Marca: Maxinutri Produto: Dimag MDK 400mg Volume: 60 Cápsulas Rendimento: 30 dias de uso Glúten: Não contém glúten Lactose: Não contém lactose Como Usar Dose: Ingerir 2 cápsulas ao dia. Momento: De preferência junto com as principais refeições. Indicação: Adultos maiores de 19 anos. Informações Importantes Este produto é um suplemento alimentar, não um medicamento. Não exceder a recomendação diária de consumo indicada na embalagem. Mantenha fora do alcance de crianças. Gestantes, lactantes e crianças devem consumir apenas sob orientação médica. Conservar ao abrigo da luz, calor e umidade. Após aberto consumir em até 60 dias Advertência - Produto indicado para o Grupo Populacional ≥ 9 anos. - Este produto não é um medicamento. - Não exceder a recomendação diária de consumo indicada na embalagem. - Mantenha fora do alcance de crianças.', 61.02, 54.0, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-8261h-ml8ddurdog0284', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58205993997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799846634', 'Kit Papete Infantil Homem Aranha E Furgão Grendene Kids 23222', 'O kit Papete Infantil Homem Aranha e Furgão Grendene Kids 23222 é a escolha perfeita para os pequenos fãs do herói aracnídeo. Com um design moderno e divertido, o kit é composto por uma papete incrível e um furgão colecionável. Feito com materiais de alta qualidade e duráveis, proporciona conforto e segurança para os pés dos pequenos aventureiros. Além disso, é super fácil de calçar e ideal para todas as ocasiões. Adquira agora mesmo e torne o dia a dia do seu filho ainda mais divertido.. MODELO: 3293222 REFERENCIA: 23222 MARCA: Grendene Kids MATERIAL DA PALMILHA: PVC MATERIAL DA SOLA: PVC ACABAMENTO: Vulcanizado DETALHES: Fechamento por fita duplamente aderente.Contém 1 Forgão do Homem aranha com as seguintes medidas: Largura 18 cm, Comprimento 36 cm Altura 18 cm (medidas aproximadas). GÊNERO: Male GRUPO DE IDADE: Infant MATERIAL DO SAPATO: Borracha ESTILO: Rasteiras TIPO: SANDÁLIA', 143.99, 143.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7rdw1-mda9jl2g6i9sc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F21799846634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398982197', 'Pingente Espirito Santo Vazado Prata 925', 'Pingente Espírito Santo Vazado em Prata 925 Descubra a beleza e o significado do Pingente Espírito Santo Vazado em Prata 925. Este pingente delicadamente vazado é uma representação significativa da fé e espiritualidade, feito com a qualidade e o brilho da Prata 925. Especificações do Pingente: Tamanho: 14mm x 12mm Peso: 1.0g Material: Prata 925 Símbolo de Fé e Proteção O Pingente Espírito Santo é uma representação do Espírito Santo, simbolizando a fé, a proteção divina e a orientação espiritual. Seu design vazado acrescenta um toque de delicadeza e permite que a luz brilhe através dele, realçando ainda mais sua beleza e significado. Detalhes Exclusivos Cada pingente é cuidadosamente trabalhado em Prata 925 para garantir um brilho duradouro e uma representação fiel do símbolo. Seu tamanho compacto o torna versátil, adequado para uso diário ou para ocasiões especiais. Descubra Mais na Aqua Joias Explore nossa coleção de pingentes Espírito Santo Vazado em Prata 925 e encontre uma maneira única de expressar sua fé e espiritualidade. Na Aqua Joias, nossas peças são feitas com amor e dedicação para satisfazer nossos clientes.', 94.0, 59.0, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6cokzwzd37p8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F19398982197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
