INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13054360732', 'Hidrapet 100g - Hidratante para Cães e Gatos', 'A nossa loja está a mais de 10 anos no mercado, com produtos originais e com nota fiscal. ____________________________________________________________________________ CREME HIDRAPET 100G – AGENER UNIÃO O Creme Hidrapet 100g, da Agener União, é um hidratante sem enxágue desenvolvido para cães e gatos. Sua fórmula exclusiva combina óleo de macadâmia, ceramidas e silicones, promovendo hidratação profunda, brilho e maciez aos pelos, além de manter a pele saudável. BENEFÍCIOS - Hidrata profundamente, ajudando a restaurar a barreira cutânea - Proporciona brilho e maciez aos pelos - Facilita o desembaraço e reduz a formação de nós - Auxilia na manutenção da hidratação natural da pele - Não precisa de enxágue, prático para o uso após o banho MODO DE USO - Após o banho, retire o excesso de água com uma toalha - Aplique o creme uniformemente sobre o corpo do animal - Massageie suavemente para melhor absorção - Seque o pet como de costume - Não é necessário enxaguar COMPOSIÇÃO - Óleo de macadâmia - Ceramidas - Silicones - Água purificada - Veículo q.s.p. ESPECIFICAÇÕES - Indicação: cães e gatos de todas as raças e portes - Apresentação: frasco com 100g - Uso: tópico, sem enxágue - Fabricante: Agener União CONCLUSÃO O Creme Hidrapet é ideal para tutores que buscam um cuidado a mais com a pele e os pelos de seus animais. Com ação hidratante e formulação suave, é uma excelente opção para manter a pelagem saudável, macia e brilhante, com praticidade no dia a dia. ____________________________________________________________________________ Gostou? Não perca tempo, garanta já o seu!', 80.9, 74.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb2l9crm41yx75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F13054360732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18996981308', 'Película para Samsung Galaxy Note 20 - Traseira de Fibra de Carbono Preta - Gshield', 'Proteja a traseira com a película para Samsung Galaxy Note 20 A Película Traseira de Fibra de Carbono Preta para Samsung Galaxy Note 20, da Gshield, é projetada para proporcionar uma camada de proteção adicional, garantindo que seu aparelho fique livre de riscos e arranhões indesejados na parte de trás. Com seu acabamento em fibra de carbono preta, ela não apenas oferece segurança, mas também adiciona um toque estiloso ao seu smartphone.', 21.97, 21.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7qvej-lh932gcrb0a7fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F18996981308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
