INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099443147', 'Chave Seletora Ventilação Ducato Fiat Original 1305589080', 'GRUPO AMAZONAS - SUA CONCESSIONARIA VIRTUAL Fiat Ford Jeep GM Chevrolet Renault Citroen Peugeot CONSULTE NOSSOS ESPECIALISTAS Para evitarmos erros e possiveis devolucoes, em caso de duvidas, informe sempre o CHASSIS Completo ou a PLACA do seu veiculo. Assim nossos especialistas poderao verificar diretamente na fabrica a correta aplicacao para o seu veiculo. CHAVE SELETORA VENTILAÇÃO INTERNA - ORIGINAL CÓDIGOS REFERÊNCIA: / 647534 APLICAÇÃO: FIAT DUCATO - 1998 ATÉ 2017 Aplicacao universal ou nao informada, se tiver duvida, nos faca uma pergunta. O MAIOR ESTOQUE So no Grupo Amazonas voce encontra todas pecas e conta com estoque de fabrica com mais de 50.000 itens, Precisou de pecas Fiat, Ford, Chevrolet GM, Renault, Jeep, Citroen e Peugeot, aqui voce acha. SEGURANCA As Pecas Originais e Genuinas sao projetadas sob medida para cada modelo de automovel, elas sao a garantia de seguranca para voce. - Temos Equipe de Atendimento e Suporte Tecnico Especializado a sua disposicao. - Atendimento de Seg. a Sex. das 8h00 18h00. - Fechamos para almoco das 12h00 13h15.', 160.89, 160.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7ratc-ma2ym4mfukpl1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356916980%2F19099443147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
