INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997988081', 'Pneu 205/60R15 91H All Terrain Sunset (Letras Brancas)', 'Pneu All-Terrain Sunset 205/60R15 – Alta Performance para Qualquer Terreno! Está procurando um pneu versátil, resistente e com excelente custo-benefício? O Sunset All Terrain 205/60R15 foi desenvolvido para enfrentar os desafios tanto da estrada quanto de terrenos mais difíceis, proporcionando segurança e durabilidade em qualquer condição! Características Principais: Tração e Estabilidade: O desenho inovador da banda de rodagem garante excelente aderência e estabilidade, seja em pistas asfaltadas ou em terrenos off-road. Conforto e Segurança: Seu design reduz a emissão de ruído, proporcionando viagens mais tranquilas e confortáveis para toda a família. Desempenho em Piso Molhado: Ótima aderência em condições de pista molhada, assegurando maior controle e segurança. Durabilidade: Construção radial de alta resistência, projetada para garantir longa vida útil ao pneu. Especificações Técnicas: Pneu 205/60R15 91H All Terrain Sunset (Letras Brancas) Marca: Sunset Modelo: All Terrain Aro: 15 Índice de peso (por pneu): 91 - 615kg Índice de velocidade: H - 210km/h Construção: Radial Tipo: Uso sem câmara Aplicação: Todo terreno Tipo de desenho: Simétrico Lateral: Letras Brancas Garanta já o seu Pneu Sunset All-Terrain 205/60R15 e esteja pronto para enfrentar qualquer desafio na estrada ou no off-road com segurança e conforto! Este pneu possui letras brancas. Para protegê-las durante o armazenamento e o transporte, o fabricante aplica uma película protetora na cor azul sobre as inscrições. Por isso, o produto poderá ser recebido com as letras aparentando ser azuis. Basta remover a película protetora para revelar as letras brancas originais do pneu.', 462.09, 462.09, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqngwr12n20z0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1173721007%2F23997988081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
