INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598894973', 'Kit 2 Esmalte Colorama Nude Da Sua Cor 7.0 com 8ml', 'Apresentamos a coleção "Nude da Sua Cor" da Colorama, uma linha de esmaltes que celebra a diversidade e a beleza natural de todas as peles. Com nove tons incríveis que variam do mais claro ao mais intenso, essa coleção é pensada para você encontrar o nude perfeito que combina com seu tom de pele e com seu mood do dia. É o nude que reflete a sua personalidade e se adapta ao seu estilo, trazendo elegância e sofisticação para as suas unhas.', 15.98, 15.98, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-825b9-mr1ec8oq6pdyfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23598894973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498891066', 'Kit 2 Sabonete Líquido Dove Baby Hipoalergênico Hora de Dormir Hidratação Relaxante Refil 400ml', 'Sabonete Líquido Dove Hora de Dormir 400 ml Refil • O Sabonete Líquido Relaxante de Glicerina Baby Dove Hora de Dormir é um sabonete líquido suave, formulado com uma fragrância calmante para ajudar o bebê a relaxar antes de dormir • O Sabonete Líquido Relaxante de Glicerina Baby Dove Hora de Dormir cuida da pele do seu bebê enquanto ele dorme, deixando-a limpa, macia e hidratada, e ajuda a facilitar um sono mais tranquilo • Sabonete líquido com fórmula hipoalergênica sem lágrimas, corantes, parabenos, sulfatos ou ftalatos e testado por oftalmologista, dermatologista e pediatra • Sabonete líquido hidratante da cabeça aos pés feito com nutrientes naturalmente encontrados na pele sensível do bebê, para ajudar a mantê-la saudável desde o primeiro banho • O Sabonete Líquido Relaxante de Glicerina Baby Dove tem o pH neutro para a pele do bebê, sendo suave até para recém-nascidos • Comprando o formato refil, você contribui para um consumo de plástico 76% menor. Basta cortar a embalagem na linha pontilhada e colocar o conteúdo no frasco regular de sabonete líquido Baby Dove O Sabonete Líquido Relaxante de Glicerina da Cabeça aos Pés Baby Dove Hora de Dormir foi especialmente formulado com uma fragrância calmante para ajudar o bebê a relaxar antes de dormir. Nossa fórmula é hipoalergênica e ajuda a manter a pele sensível do bebê saudável desde o primeiro banho. A hora do banho com seu bebê é especial, por isso, sabemos que você quer o melhor sabonete líquido para esse momento. Como a pele do bebê é mais fina e sensível do que a de um adulto, ela precisa de um cuidado mais delicado. Além de uma limpeza suave, esse produto ajuda a repor os nutrientes essenciais e a hidratação que a pele pode perder durante o banho. Com pH neutro para a pele do bebê e sem lágrimas, corantes, parabenos, sulfatos ou ftalatos, esse sabonete líquido ajudará o seu bebê ter um banho relaxante, contribuindo para que sua hora do sono seja mais tranquila. Uma rotina noturna, com um banho seguido de uma massagem suave, pode ajudar o bebê a ter um sono mais tranquilo. Após o banho, use a Loção Baby Dove Hora de Dormir para cuidar da pele do bebê enquanto ele dorme. Testado por dermatologista, oftalmologista e pediatra. Modo de uso: Aplique uma pequena quantidade nas mãos, ensaboe delicadamente a pele e o cabelo do seu bebê e enxágue em seguida.', 39.98, 39.98, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-823on-mokd35zlob9o3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23498891066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21564855967', 'Kit 6 Ração Úmida para Gato Friskies Adulto Sabor Frango ao Molho em Sachê 85g', 'Ração Úmida para Gatos Friskies Adulto Sabor Frango ao Molho em Sachê 85g FRISKIES® Frango ao molho é um alimento úmido completo e balanceado destinado a gatos adultos de atividade normal. Pele e pelos saudáveis graças aos níveis adequados de zinco e ácidos graxos essenciais. Visão clara e saudável devido à adição de vitamina A e taurina. Formulado com vitaminas e minerais que auxiliam nas defesas naturais. Músculos fortes e saudáveis devido à presença de fontes de proteínas de alta qualidade.', 27.54, 27.54, NULL, 'Pets > Pet Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-8257x-mqm8vjej5tl942', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21564855967', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
