INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497294338', 'Miçangas Fashion Teens Caixa Média - Brinkzania', 'Miçangas Fashion Teens Caixa Média - Brinkzania A linha Fashion Style é linda! Brinque de criar suas próprias bijuterias! Desenvolva a criatividades e imaginação das crianças com a brincadeira de montar seus próprios Kits de Miçangas. Selo Inmetro: CE-BRI/INNAC-02478-04A Mais sobre o produto: A Miçangas Fashion Teens Caixa Média – Brinkzania faz parte da encantadora linha Fashion Style e convida as meninas a soltarem a criatividade enquanto montam suas próprias bijuterias, explorando cores, combinações e estilos de forma divertida. Perfeita para desenvolver imaginação, coordenação e habilidades manuais, a brincadeira permite criar peças únicas e personalizadas, tornando cada momento ainda mais especial. Indicada para meninas de 3 a 14 anos, é ideal para o estilo de brincar Imaginar e Construir.', 25.99, 25.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-8260w-ml5j2avj5pmy1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F18497294338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699240444', 'Retentor Comando Válvulas Renault Clio 1999 a 2000 - 146484 - R570913V', 'Retentor Comando Válvulas Renault Clio 1999 a 2000 146484 R570913V Motor 1.6 16v K4M - (Altura - 5 mm) (Diâmetro do Alojamento - 42 mm) (Diâmetro do Eixo - 28 mm) São pequenas peças de borracha e metal, que tem como principal função vedar e reter óleos, graxas e qualquer outro tipo de fluído. Além disso, o retentor não permite que impurezas, como terra ou poeira, entrem no motor. A manutenção destas peças não tem um tempo certo estabelecido ou que possa ser programado, devendo ser feita a partir observação visual e tátil. Assim que você perceber algum vazamento de óleo no veículo, é a hora certa de trocar o retentor.', 29.53, 29.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd6p-lufaw87cg4g329', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21699240444', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23035653560', 'Livro Patrulha Canina Aquarela - Ciranda Cultural', 'Livro Patrulha Canina Aquarela - Ciranda Cultural . Ryder e a Patrulha Canina estão prontos para fazer resgates e ajudar os cidadãos da Baía da Aventura. Conheça a habilidade de cada um dos filhotes pintando com a aquarela! Idade Recomendada: 4 - 8 anos. INMETRO: Isento.', 15.99, 15.99, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7qvg4-lezr302wtabj10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F23035653560', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693677648', 'Filtro Combustível Vw Spacefox 2006 a 2018 - 1353649 - FCI1620', 'Filtro Combustível Vw Spacefox 2006 a 2018 1353649 FCI1620 (Highline / Sportline / Trend / Comfortline / Route) – 1.6 8/16V Total Flex - (Mecânico) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 27.91, 27.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmw-m5l4zh795ox7fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23693677648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
