INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698048929', 'Filtro de Combustível Honda City 1.5 Flex de 2009 a 2025 Original Mahle Metal leve', 'FILTRO DE COMBUSTIVE L MAHLE METAL LEVE KL582 APLICAÇÃO : HONDA CITY 1.5 FLEX TODOS OS MODELOS DE 2009 A 2025 A função do filtro de combustíve l é reter as impurezas existentes no combustíve l acumulado no tanque do veículo, evitando que cheguem à bomba injetora, bicos injetores e unidades injetoras (veículos eletrônicos). A não substiuição no periodo correto pode provocar: - Aumento de consumo; - Perda de potência; - Dano na bomba de combustíve l, bicos, unidades injetoras e até causar parada total do veículo. PRODUTO NOVO ORIGINAL COM NOTA FISCAL , ENVIO RAPIDO !', 34.99, 28.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m32ctj4cbw9fb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318894435%2F23698048929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294511447', 'Pó Facial Pérola SACE LADY FPS 30PA+++ Controlo de Óleo', '* Descrição: Este pó facial proporciona um acabamento duradouro e impecável. Controla eficazmente o excesso de secreção oleosa, mantendo a pele mate e fresca ao longo do dia. O poderoso efeito corretivo esconde imperfeições, poros e manchas, proporcionando uma tez suave e uniforme. * Características: Mate impecável Controle de oleosidade À prova d''água FPS 30 pa+++ * COMO USAR: Após a aplicação da base, mergulhe suavemente a esponja de pó e aplique com movimentos circulares do centro para fora. Concentre-se na zona T e nas áreas que precisam de retoques. Repita para obter uma aparência perfeita durante o dia. * Ingredientes: TALCO, MICA, SÍLICA, POLIMETIL METACRILATO, CAULINA, DIMETICONA, PALMITATO DE ETILHEXILO, ESTEARATO DE MAGNÉSIO, ÓXIDOS DE FERRO, CERA MICROCRISTALINA, TRIETOXICAPRILIL SILANO, CI 77891, ETILHEXIL METOXICINAMATO, DIÓXIDO DE TITÂNIO, METICONA, PROPILPARABENO, METILPARABENO, HIDRÓXIDO DE ALUMÍNIO, ACETATO DE TOCOFERILO, HIALURONATO DE SÓDIO, ÁGUA, BUTILENOGLICOL, BHT, EXTRATO DE RAÍZ DE CENTELLA ASIATICA, HIDROXIAZETOPHENONA * Peso líquido: 9,5g/0,34Oz * Vida útil da Prateleira: 3 anos * Serviço pós-venda: Se você receber um item danificado, incorreto ou incompleto, entre em contato conosco. Faremos o possível para ajudar. Sua satisfação é nossa motivação! * Observação: Devido aos efeitos de iluminação e configurações do monitor, as cores reais podem variar ligeiramente da imagem. Se o item não atender às suas expectativas, entre em contato conosco antes de avaliar.', 159.0, 86.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/br-11134207-820l6-motgmgev1h4z5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1616052629%2F23294511447', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
