INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392976505', 'Pré Filtro Combustível Citroen Aircross 2010 a 2015 - 516231 - 1345', 'Pré Filtro Combustível Citroen Aircross 2010 a 2015 516231 1345 Motor 1.6 16v O pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada._x000D_ Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento._x000D_ Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 27.68, 27.68, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd6i-lufhhi5cch7y13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22392976505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697458689', 'Capa Proteção Correia Dentada Vw Santana 1994 a 1999 - 184376 - 1741', 'Capa Proteção Correia Dentada Vw Santana 1994 a 1999 184376 1741 MOTOR 1.6/1.8/2.0 8V AP (EXTERNA - INFERIOR) O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 29.45, 29.45, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8258i-mq1ytwox29z6d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20697458689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
