INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21664207032', 'Suporte de Lixa Velcro 100mm 4" Rosca M14 - Tubarão', 'DESCRIÇÃO: Suporte de Disco de Lixa com Velcro M14 (100mm) 4" tem encaixe para Rosca M14, usada em lixadeiras e politrizes. ESPECIFICAÇÕES TÉCNICAS: :: Marca: TUBARÃO :: Modelo: SUPORTE VELCRO :: Material: Pvc :: Rotação máxima: 12.000rpm :: Indicado para: Discos de lixa 100mm / 4" PESO E DIMENSÕES: :: Peso: 0,112 g :: Altura: 3,0 cm :: Largura: 10,0 cm :: Comprimento: 10,0 cm INCLUI: :: 1 (UN) Suporte Lixa Velcro 100mm INFORMAÇÕES DE ENTREGA: :: Todos os produtos serão enviados de acordo com a forma escolhida pelo cliente, depois da confirmação do pagamento. Produtos comprados de segunda à sexta-feira até 12h serão postados no mesmo dia. O prazo para a entrega varia de acordo com a forma de envio escolhida, pode ser frete expresso, Pac, Sedex, então fique atento as condições de entrega da sua compra. Logo após a confirmação de postagem, você receberá todas as atualizações do status do seu pedido quanto o código de rastreio, direto pela plataforma. E atenção, lembre-se sempre de ter alguém para receber a sua compra, no endereço informado, para evitar que essa mercadoria seja devolvida.', 15.0, 15.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6pmjve9c8knbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341202873%2F21664207032', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098091104', 'Organizador de Lavanderia 1,5L + 2,3 Litros Porta Amaciante Sabonete Sabão em Pó Liquido Alvejante', 'O Kit Dispenser 2,3 e 1,5 L Preto Organizador de Lavanderia é a solução ideal para manter sua lavanderia organizada e prática. Composto por três dispensers de tamanhos variados COM Capacidade de até 1,3L, 1,5L, 2,3L e 2,6L ideal para diferentes tipos de produtos de limpeza. o kit foi projetado para armazenar líquidos e produtos de uso comum na lavanderia, como amaciante, sabão em pó e sabonete líquido. Características principais: - Material: Plástico resistente e de fácil limpeza. - Cor: Preto, que traz sofisticação e combina com diferentes ambientes de lavanderia. - Design funcional: Com um formato que facilita o uso diário, permitindo um armazenamento eficiente e o acesso rápido aos produtos. - Capacidade: Dispensers com capacidades de 2 L, 3 L e 1,5 L, adequados para diferentes necessidades de armazenamento e dosagem. - Uso versátil: Ideal para armazenar amaciante, detergente, sabão em pó, sabonete líquido e outros produtos de limpeza, proporcionando mais organização e praticidade no seu dia a dia. Este kit é a escolha perfeita para quem busca otimizar o espaço e manter os produtos de lavanderia sempre à mão e bem organizados.', 99.9, 76.9, NULL, 'Home & Living > Bathrooms > Soap Dispensers, Holders & Boxes', 'https://cf.shopee.com.br/file/br-11134207-820mb-mlgf969r2b5y9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316557325%2F23098091104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21998007247', 'Bola Manchester City Estádios 24 Campo Azul', 'Composição: Policloreto de Vinila (PVC)Câmara interna: 100% borracha butílicaCircunferência aproximada: 68 - 70 cmPeso aproximado: 410 - 440 gCor predominante: AzulClube: Manchester CityIndicado para: CampoOrigem: ImportadaMiolo: RemovívelGênero: UnissexCostura: SimTamanho único', 109.9, 109.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7ra2i-m59xzh04ou3v61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F21998007247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15115919788', 'Disco Corrente Motosserra para Esmerilhadeira Cortar Esculpir Madeira 4.1/2"', 'DESCRIÇÃO: O Disco de Madeira 4.1/2" Corrente Motosserra – é o acessório ideal para profissionais de marcenaria, carpintaria, artesanato e jardinagem que buscam máxima agilidade e eficiência em cortes rápidos e entalhes em madeira. Equipado com uma corrente de motosserra acoplada ao redor do disco, este equipamento foi desenvolvido para cortar, esculpir e remover grandes volumes de madeira macia ou dura com facilidade, superando o desempenho de discos abrasivos convencionais. Compatível com esmerilhadeiras angulares de 4.1/2", ele é excelente para trabalhos que exigem modelagem, confecção de esculturas, cortes de fôrmas, paletes, troncos pequenos e podas rápidas, oferecendo um avanço de corte macio e contínuo. Sua estrutura robusta garante durabilidade e resistência contra o desgaste prematuro, tornando-se uma ferramenta indispensável para quem trabalha com transformação de madeira e exige alta produtividade no dia a dia. ESPECIFICAÇÕES TÉCNICAS: :: Diâmetro do disco: 4.1/2" (aproximadamente 115mm) :: Aplicação principal: Cortes, entalhes e modelagem em madeira :: Tipo de lâmina: Disco com borda de corrente de motosserra INCLUI: :: 1 (UN) Disco de Madeira 4.1/2" Corrente Motosserra GARANTIA: :: Garantia do fabricante de 3 meses contra defeitos de fabricação provenientes de falhas de material ou processo de produção. :: Não cobre o desgaste natural dos dentes da corrente, danos decorrentes do uso em rotações acima do limite da esmerilhadeira, contato acidental com pregos/metais ou instalação incorreta do acessório. INFORMAÇÕES DE ENTREGA: :: Produtos comprados até às 14h (de segunda a sexta-feira) são postados no mesmo dia. :: O prazo de entrega varia conforme modalidade de envio escolhida (PAC, Sedex, transportadora ou expresso). :: Após a postagem, o cliente recebe todas as atualizações e código de rastreio. :: É necessário que haja alguém disponível no endereço informado para receber o pedido.', 48.0, 48.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820l4-mpcjlx0o52itb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341202873%2F15115919788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49857410605', 'Frigideira Grill Quadrado 26cm de Alumínio Bifeteira Antiaderente com Cabo Térmico MTA Branco Pérola', 'Descrição do Produto A Frigideira Grill MTA 1280 na cor Branco Pérola perfeita para quem busca praticidade, eficiência e um toque moderno na cozinha. Ideal para o preparo de carnes, legumes, aves, hambúrgueres e sanduíches, ela conta com superfície grill que ajuda a criar o efeito grelhado nos alimentos, deixando as receitas ainda mais apetitosas. Produzida em alumínio leve e resistente, proporciona distribuição uniforme do calor, contribuindo para um cozimento mais rápido e eficiente. Seu revestimento antiaderente evita que os alimentos grudem, facilita a limpeza e permite um preparo mais prático no dia a dia. Além disso, possui cabo ergonômico, que oferece mais conforto e segurança durante o uso. Destaques do Produto Ideal para grelhar carnes, legumes, aves e sanduíches Superfície grill que deixa marcas grelhadas nos alimentos Corpo em alumínio leve e resistente Revestimento antiaderente Distribuição uniforme de calor Cabo ergonômico para maior segurança no manuseio Cor Branco perola, moderna e elegante Ficha Técnica Marca: MTA Modelo: 1280 Capacidade: 1,1 Litros Cor: Branco pérola Material do corpo: Alumínio', 119.9, 79.9, NULL, 'Home Appliances > Kitchen Appliances > Multi-function Cookers', 'https://cf.shopee.com.br/file/br-11134207-820lq-mlz9x3kvo9a827', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316557325%2F49857410605', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
