INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193196165', 'Quebra Cabeça Therizinosaurus Jurassic World 100 Peças Mimo Toys Brinquedo Jogo Infantil Presente', 'Mergulhe no emocionante mundo de Jurassic World com o Quebra-Cabeça Therizinosaurus 100 Peças da Mimo Toys! Este incrível quebra-cabeça apresenta uma imagem vibrante e detalhada do Therizinosaurus, um dinossauro herbívoro com garras gigantescas. Com 100 peças coloridas e de alta qualidade, este quebra-cabeça é perfeito para desenvolver a coordenação motora, a percepção visual, a concentração e a memória de crianças e adultos. Especificações: - Idade recomendada: + 4 anos - Composição/material: cartonado - Detalhes: tamanho 32x26,4cm Características: - Marca: Mimo Toys - Modelo:2084 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Quebra-Cabeça Therizinosaurus Jurassic World 2084 Palavras-chave: quebra-cabeça, 100 peças, Therizinosaurus, Jurassic World, Mimo Toys, 2084, dinossauro, brinquedo educativo, percepção visual, coordenação motora, concentração, memória, papel cartonado, 32x26,4 cm, certificado Inmetro 007662/2020, idade recomendada a partir de 4 anos, presente para fãs de dinossauros, brinquedo para meninos, brinquedo para meninas, diversão, aprendizado, montagem, desafio, encaixe, exploração, mundo jurássico, brinquedo interativo, entretenimento', 41.29, 35.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdx1-lyb4qiq3i1eyd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22193196165', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
