INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18297630187', 'Protetor Solar FPS 99 120ML Facial NUTRIEX', 'Protetor Solar FPS 99 120ML Facial NUTRIEX Minimiza os danos na pele causados pelos raios infravermelhos devido à ação antioxidante do produto. Com substâncias reguladoras de oleosidade que promovem o efeito “mate”. RÁPIDA ABSORÇÃO, TEXTURA LEVE, LIVRE DE CORANTES, AÇÃO HIDRATANTE. Uso profissional. O Protetor Solar FPS 99 Facial Nutriex Profissional oferece muito alta proteção à pele contra os efeitos nocivos da radiação solar, prevenindo as queimaduras solares. Com toque seco e fácil espalhabilidade, não deixa a pele esbranquiçada e possui aplicação rápida e prática. Contém Bioactive E®, poderoso antioxidante que previne o envelhecimento precoce. DADOS TÉCNICOS: Phenylbenzimidazole sulfonic acid: 8% Homosalate: 15% Ethylhexyl methoxycinnamate: 10% Diethylamino hydroxybenzoyl hexyl benzoate: 10% Bis-ethylhexyloxyphenol methoxyphenyl triazine: 10% Methylene bis-benzotriazolyl tetramethylbutylphenol: 10% Peso: 120g FPS: 99 COMPOSIÇÃO: Água, dióxido de silício, edetato dissódico, pentilene glicol, hidroxiacetofenona, aminometil propanol, ensulizol, álcool cetoestearílico, oleato de sorbitana, monoestearato de glicerila, sebacato diisopropílico, dióxido de titânio/ dióxido de silício/ dimeticona, octinoxato, homossalato, dietilamino hidroxibenzoíla hexil benzoato, bis-etilhilhiloxifenol metoxifenil triazina, poliéster-7/ diheptanoato de neopentilglicol, potássio cetil fosfato, dimeticona, goma xantana, crosspolímero acrilatos/C10-30 alquil acrilato, caprilil glicol, acetato de dextroalfatocoferol, metileno bis-benzotriazolil tetrametilbutilfenol/ decil glicosídeo/ propilenoglicol/ goma xantana/ água, polímero cruzado de metacrilato de metila, dióxido de silício, água/ pentilene glicol/ glicerol/ frutose/ ureia/ ácido cítrico/ hidróxido de sódio/ maltose/ pidolato de sódio/ cloreto de sódio/ lactato de sódio/ trealose/ alantoína/ hialuronato de sódio/ glicose, perfume (salicilato de benzila, citronelol, linalol). Marca: NUTRIEX Garantia: 3 Meses Referência: 9230293 *Imagens Meramente Ilustrativas.', 84.9, 84.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-7rcd0-ls724cgo430n51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F18297630187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
