INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191414078', 'Eico Pro Liso Mágico Pós Progressiva Shampoo Condicionador 300ml + Máscara Capilar Tratamento 300g', 'Kit Contém: 1 Shampoo Eico Professional Liso Mágico 300ml 1 Máscara Eico Professional Tratamento Liso Mágico 300ml 1 Condicionador Eico Professional Liso Mágico 300ml Eico Professional une tecnologia e excelência em fórmulas de alto desempenho para um cuidado capilar avançado. A linha Liso Mágico foi desenvolvida com o exclusivo Pro Liss Complex para fios impecavelmente lisos, disciplinados e radiantes. Indicação para cabelos lisos, alisados e com frizz. PROLISS COMPLEX Tecnologia enriquecida com Vinagre de Maçã e Phyto Keratin para alinhamento e selagem de cutículas, reconstrução da fibra danificada e fortalecimento de fios que passaram por processos químicos. Os cabelos ficam disciplinados, leves, hidratados e com brilho radiante. RESULTADOS COMPROVADOS EM LABORATÓRIO Sem Sal, Sem Parabenos, Sem Petrolato, Sem Corante - Liberada SHAMPOO Shampoo para cabelos lisos naturais ou com química. Eico Liso Mágico Shampoo reduz o volume, frizz e mantém os fios alinhados. Limpa suavemente enquanto atribui brilho extremo e maciez. Eico Liso Mágico Shampoo prolonga o efeito de processos químicos como a progressiva, mas também trata, para tornar os fios gradativamente mais lisos. Proporciona disciplina e caimento sedoso. Modo de usar: No cabelo molhado, aplique o shampoo e massageie o couro cabeludo. Mantenha o movimento até que surja a espuma e enxágue em seguida. Repita o processo se necessário. MÁSCARA DE TRATAMENTO Máscara capilar para cabelos lisos naturais ou quimicamente tratados. Eico Life Liso Mágico Tratamento disciplina e mantém o efeito liso. Reduz o volume e o frizz para proporcionar caimento muito sedoso. Modo de usar: Depois de lavar, aplique a máscara sobre os fios ainda úmidos. Espalhe pelo comprimento e pontas, e deixe agir por 5 a 15 minutos. Quanto mais poroso estiver o fio, maior o tempo de ação. Em seguida, enxágue completamente. CONDICIONADOR Modo de usar: Após lavar, aplique o condicionador nos fios molhados. Espalhe homogeneamente pelo comprimento e pontas, e deixe agir por alguns minutos e enxágue completamente. Para usar como leave-in, aplique sobre os fios úmidos do comprimento às pontas, modele e finalize como desejar. Não enxágue.', 214.9, 139.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7qve8-lhmn5pzg3t9wfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385344228%2F23191414078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299592856', 'Jogo Perfil Express - Personalidades', 'Perfil Express Personalidades é uma nova forma de jogar o clássico da Grow. A temática desta versão engloba exclusivamente personalidades nacionais e mundiais. O jogo traz seis divertidas categorias que vão testar o conhecimento do pessoal: cinema e TV, música, influenciadores, esportistas, personalidades históricas e outras. Cada cartela tem 10 dicas que valem até 10 pontos. A primeira dica é menos reveladora, e as seguintes, de maneira progressiva, aumentam mais as chances de acerto. Quem nunca quis desafiar seu conhecimento com os amigos de uma maneira rápida e emocionante? Reúna o pessoal para aproveitar ao máximo este rico conteúdo!', 49.99, 49.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rbmk-m5efh0rxdo7e9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F19299592856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52305408628', 'Colar Prata 925 com Estrela do Mar em Madrepérola Joia Feminina Charmosa', 'O Colar Estrela do Mar Pingente Madrepérola em Prata 925 é uma joia delicada e cheia de encanto. O pingente em formato de estrela do mar simboliza leveza e conexão com o oceano, enquanto a madrepérola traz brilho suave e elegante, criando um visual sofisticado e atemporal. - Material: Prata 925 - Pedra: Madrepérola - Detalhe: Pingente estrela do mar - Estilo: Delicado e elegante - Tamanho: 45 cm - Fecho: Argola tradicional - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Uma peça charmosa e versátil, perfeita para quem ama joias com inspiração no mar e brilho natural.', 253.0, 253.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkdriiyknx8g2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F52305408628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
