INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52903952237', 'Espelho Orgânico E25 Retrô Lapídado linha FIt Sem moldura Sala Hall Quarto Banheiro', 'Transforme seus ambientes com o Espelho Orgânico da Home Estilo Casa e Decoração, um elemento decorativo que traz charme e sofisticação à sua casa. Com um tamanhos de 70, 80, 90, 100 e 110 cm de altura, esses espelhos é ideal para ser instalado em diversas áreas, como banheiros, quartos e salas. Seu design orgânico e moderno se adapta perfeitamente a estilos contemporâneos, garantindo uma harmonia visual impressionante. Espelho Vidro polido e lapidado Segue dimensões Altura: 70cm Largura: 30cm Espessura: 3mm Sem Moldura Altura: 80cm Largura: 35cm Espessura: 3mm Peso Médio: 2kg Sem Moldura Altura: 90cm Largura: 40cm Espessura: 3mm Sem Moldura Altura: 100cm Largura: 35cm Espessura: 3mm Sem Moldura Altura:110cm Largura: 50cm Espessura: 3mm Sem Moldura Feito para ser fixado na parede, o Espelho já vai com suporte fixado na parte de trás, facilitando a sua instalação. A forma fluida do espelho não apenas reflete a luz, mas também amplia visualmente os ambientes, criando uma sensação de maior amplitude e luminosidade. Perfeito para quem busca uma decoração que alie estética e funcionalidade, este espelho é uma escolha excelente para quem deseja criar um espaço luxuoso e acolhedor. Adicione um toque de elegância ao seu lar com o Espelho Orgânico e faça de cada cômodo um local especial e convidativo.', 99.99, 69.0, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mivs49jwlaf5da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1146529360%2F52903952237', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50505789942', 'MODUS Garrafa Térmica 2,4L Aco Lnox Acampamento E Trilhas', 'Marca：MODUS Material: 304 no interior e no exterior Capacidade: 2400ml Color: verde exército, preto Mantém-se quente durante 12-36 horas Processo de pulverização de plástico na superfície da garrafa Com pega retrátil na parte lateral, design portátil, perfeito para utilização no exterior. design à prova de vazamentos, pode ser carregado na bolsa. Materiais saudáveis, livre de BPA. Processo de revestimento de cobre: consiste em aplicar uma fina camada de cobre na parte interna ou em determinados componentes do copo térmico, por meio de uma técnica específica. O principal objetivo é melhorar a capacidade de conservação da temperatura.', 359.98, 149.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjqos0wh9l3579', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F534109767%2F50505789942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199560571', 'Jogo 4 Pneus Continental Aro 13 PowerContact 2 175/70R13 82T', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.Desenvolvido para equipar carros compactos e médios, o pneu Continental PowerContact oferece qualidade de sobra para o uso diário, seja urbano ou rodoviário, com muita segurança e conforto. Possui banda de rodagem assimétrica e composto da 4ª geração de sílica, que em conjunto fazem com que o pneu tenha ampla área de contato com a pista, porém com desgaste reduzido, devido à baixa resistência ao rolamento, o que também ajuda no consumo de combustível, resultando em menor emissão de CO2 e aumento da vida útil do pneu. Sobre a marca Continental A marca Continental foi fundada em Hanover, na Alemanha em 1871. Os pneus Continental são referência mundial em desempenho e qualidade, equipando os mais modernos e sofisticados carros. São usados como pneu original de fábrica em marcas como BMW, Mercedes e Porsche, tanto com pneus comuns quanto em pneus RunFlat. Seja em pneus para carros de passeio, carros esportivos, utilitários, a Continental oferece inovações e a garantia de segurança total nos trajetos realizados.', 1815.91, 1670.64, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfi6-m32at6e3su3r7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F21199560571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
