INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29730200298', 'Filto Ar Condicionado CB1155 Para Hyundai Elantra I30 Cerato 1.6 1.8 2.0', 'Filto Ar Condicionado CB1155 Hyundai Elantra I30 Cerato Protege sua saúde, detém até 99,5% das bactérias, fungos, pólen e impurezas. Filtro anti-pólen. Hyundai Elantra Automático 1.6: 2011 > 2012 Hyundai Elantra 2.0 16V: 2013> Hyundai I30 Automático 1.6 16V 128 cv: 2013 Hyundai I30 1.8 16V 148cv (2014>) ***Características*** -Código Original: 971332H001 -Local: Atrás do Porta-luvas -Modelo: FB1155 -Conversões: MP382 | ACP982 | LA955 | CF11434 | AKX2014 | E3902LI | KF10251 | FAAHY28 | CU24013 | TAC9082 | FAC982 - Material: Construído com materiais de alta qualidade para máxima durabilidade ( Estrutura de TNT ) - Instalação Fácil: Substituição rápida, sem necessidade de ferramentas especiais - Eficiência Garantida: Filtra eficazmente poeira, pólen e outros alérgenos - Longa Durabilidade: Resistente para uso prolongado, ideal para condições diversas - Preço Acessível: Ótimo custo-benefício para sua manutenção automotiva ***Por que escolher o Filtro Ar Condicionado da FILTROS BRASIL?*** Filtros Brasil é projetado com precisão para proporcionar um ambiente interno mais limpo e saudável para você e seus passageiros. Aproveite a qualidade reconhecida da marca e a eficiência deste filtro para garantir um ar condicionado sempre eficaz no seu Volkswagen.', 28.6, 28.6, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd4g-m7jotizzfqpca2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F29730200298', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297839987', 'Bomba do Esguicho Limpador do Parabrisa Original Volkswagen', '======================================================================= DESCRIÇÃO DO PRODUTO Bomba esguicho limpador para brisa. APLICAÇÃO: CONSULTAR COMPATIBILIDADE TODOS OS ITENS SÃO ORIGINAIS VOLKSWAGEN ======================================================================= [[ ATENÇÃO]] • Preços validos somente para compras de pessoas físicas (CPF). • Pessoas Jurídicas devem consultar preço no campo de perguntas devido a possibilidade de retenção do ICMS. • Antes de realizar a compra informe o CHASSI do veículo no campo de perguntas, para que possamos confirmar a compatibilidade da peça com o veículo, evitando desta forma receber uma peça incorreta. • Todas as compras realizadas até as 16:00 hrs serão postadas no mesmo dia, após este horário a compra poderá ser postada nos correios no próximo dia útil. • Nosso horário de atendimento é de segunda a sexta feira das 07:45 as 18:00hrs • Perguntas realizadas em finais de semana e feriados podem possuir um tempo de resposta maior. ======================================================================= TODOS OS NOSSO PRODUTOS SÃO PEÇAS ORIGINAIS VOLKSWAGEN. A Liane Automóveis é uma concessionaria Volkswagen localizada no interior de São Paulo, prezamos pela qualidade e agilidade no atendimento, com a satisfação do cliente sempre em primeiro lugar. Todos os produtos acompanham nota fiscal eletrônica e possuem garantia de 90 dias contra defeito de fabricação. =======================================================================', 62.9, 62.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0lnizv2ikpp2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2