INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42677325543', 'A Festa Incrível e Super Fantástica que Nunca Acaba | Joni Eareckson Tada', '“Você já recebeu um convite para uma festa, um jogo de futebol ou um casamento? Os melhores convites são aqueles para momentos inesquecíveis com pessoas incríveis. E este é o melhor convite de todos…” Como será o céu? O que as pessoas farão lá para sempre? Junte-se à Joni Eareckson Tada e vislumbre a vida incrível, brilhante e esplendorosa que os amigos de Jesus desfrutarão quando ele voltar para este mundo... e trouxer com ele o céu! “Um dos melhores livros infantis que já li sobre a melhor promessa já feita.” NANCY GUTHRIE - Autora e professora da Bíblia “Leia este livro para seus filhos (e netos) a fim de que eles também anseiem pela vinda do Senhor Jesus.” JOHN PIPER - Pastor e teólogo “Um livro curto, mas profundo, que ensina sobre a beleza e alegria da era vindoura para crianças e adultos.” CAROL BAZZO - Esposa, mãe e autora 27X23 CM 32 Páginas', 38.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-81zvu-midu9lh7a2vbc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F42677325543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
