INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397759488', 'Slide Mississipi Flatform MB511', 'Produto marca Mississipi. O Slide Mississipi Flatform da coleção Primavera/Verão 2024 é um calçado versátil e leve e está disponível na cor . Seu design único, formado por tiras finas com detalhes sofisticados. Além disso, sua sola flatform de 3 cm proporciona um leve aumento na altura, leveza e garante um visual moderno e atual. Seu destaque fica por conta das tiras metalizadas e com detalhes de brilhos e nós, que adicionam elegância e sofisticação ao modelo. o material sintético garante durabilidade, tornando-o ideal para o uso diário. Sua versatilidade permite que você crie diversas combinações e adapte o look à sua personalidade. Seja para um passeio na praia ou um dia de compras, esse calçado é a escolha certa para quem busca conforto e estilo. Peso: 0,597 kg Altura da sola: 3,00 cm', 129.9, 119.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-8260m-ml5kmb4e93i8d1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23397759488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394444693', 'Sandália Mississipi Rasteira Feminina MF972', 'Produto marca Mississipi. Eleve seu estilo com a Sandália Mississipi Rasteira, o calçado perfeito para a mulher moderna que busca sofisticação e conforto. Com um design minimalista e elegante, este modelo se destaca pela tira frontal com vazados a laser que adicionam um toque refinado a qualquer look. o fechamento de fivela no tornozelo garante o ajuste perfeito, proporcionando segurança e estabilidade em cada passo. Sua versatilidade a torna a escolha ideal para diversas ocasiões, do dia a dia no escritório a um happy hour descontraído ou um passeio no final de semana. Feita com material sintético de alta qualidade e com um peso leve de 0,479 kg, ela se adapta perfeitamente aos seus pés, proporcionando uma experiência de uso agradável e duradoura. Não perca a oportunidade de transformar seus looks e dar um up na sua confiança. a Sandália Mississipi Rasteira é a peça-chave que faltava no seu guarda-roupa para criar combinações incríveis e se sentir ainda mais pode. Peso: 0,479 kg Altura da sola: 1,00 cm', 149.9, 129.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-821fe-mgw9dfpbuqdr71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F22394444693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
