INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898223442', 'Kit 4 Talabarte Correia Caixa Tarol 2 Ganchos Liverpool', 'ACOMPANHA O KIT: - 4x TALABARTES COM 2 GANCHOS A Liverpool é a maior fabricante de baquetas no Brasil e começou sua história há mais de 28 anos, se especializou na criação de uma linha profissional, adequada às necessidades dos bateristas brasileiros que, até então, tinham apenas opções de baquetas importadas. Oferece uma gama de mais de 400 produtos entre baquetas e acessórios para bateria, percussão e instrumentos para musicalização infantil. Características: Marca: Liverpool Cor: PRETO, BRANCO Material: Nylon Quantidade de Ganchos: 2 Correia Ajustável: Sim Largura: 5 cm Instrumento Recomendado: Surdo, Repinique, Alfaia, etc… Garantia: 3 Meses', 72.52, 72.52, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rd3n-m6nza4pmd7a91a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F23898223442', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
