INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099442955', 'Caneleira Penalty Matís Com Tornozeleira VIII', 'Garanta o máximo de proteção durante as partidas de futebol com a caneleira com tornozeleira da linha Matis VIII, produzida pela Penalty. A peça possui placa em polipropileno com revestimento interno de EVA. Seu ajuste é feito por meio de uma tira elástica com fecho fixado, que se encarrega de manter a caneleira no lugar, além de proporcionar a regulagem desejada. Além disso, a tornozeleira traz em sua composição poliéster e elastodieno, garantindo uma peça mais justa, que age como isolante térmico, excelente para a prática esportiva em climas frios ou quentes. Por fim, o design do produto é inteiramente preto com detalhes texturizados, além da logo da marca fornecedora. Indicada para futebol em campo, society e futsal, a caneleira com tornozeleira evita lesões, oferecendo todo conforto e proteção necessária para o craque executar seus dribles.Contém: 01 ParComposição Placa: 100% PolipropilenoComposição Enchimento: 100% EVAAjuste: Tira elástica com fecho fixadoComposição Tornozeleira: 70% Poliéster e 30% ElastodienoDimensões aproximadas da placa (A x L): 17 x 12 cmTamanho Único.', 73.9, 73.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7rdxw-m0k5aj1thgw960', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F21099442955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
