INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44319088697', 'Legging Feminina Infantil Estrelas', 'Legging Feminina Infantil Estrelas Legging em cotton (96% algodão e 4% poliéster), possui estampa rotativa de estrelas super fofa! Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado.', 29.9, 19.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7rdwc-mdd57ailqlfd31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F44319088697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40223016295', 'Vestido Feminino Infantil Olhe Para O Céu', 'Descrição: Vestido Feminino Infantil Olhe Para O Céu Vestido em meia malha 50% algodão e 50% poliéster. Possui cor laranja com estampa frontal em glitter, alcinha, recorte na cintura e leves babados super delicados para a sua menina! Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Estação: Verão - Gênero: Feminino - Tecido Peça: Meia Malha - Composição: 50% Algodão e 50% Poliéster - Faixa Etária: 1 à 12 anos - Garantia: 1 Mês - Tipo de Roupa: Vestido - Tabela de Medidas: Tabela de Medidas Vestido: Tamanho | Busto | Comprimento 2 | 22CM | 52CM 3 | 24CM | 55CM 4 | 27CM | 58CM 6 | 28CM | 63CM 8 | 30CM | 68CM 10 | 33CM | 72CM 12 | 36CM | 78CM', 39.9, 32.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-824i9-mfic7ugh91cbd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F40223016295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
