INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993168749', 'Jogo de Cartas Urbs Copag - 34852', 'URBS é um jogo rápido e estratégico de “draft” (pegar e passar cartas),em que os jogadores desenvolvem suas cidades ao longo de 3 Épocas(fases). Ao fim das 3 Épocas, todos devem verificar a quantidade de pontos de vitória gerados por suas respectivas Cidades. Vence quem tiver mais pontos! Características: - Marca: Copag - Modelo: 34852 *Imagens meramente ilustrativas Conteúdo da Embalagem: - 75 Cartas de Construção - 6 cartas pontuação - 1 Manual Cartas - Draft - Urbs - Copag - Jogo de Cartas - Jogos Desafiadores', 94.61, 74.9, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdyn-ly5diwxbrbmydd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22993168749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993480050', 'Tênis Infantil Bibi Energy Baby 2.0 Preto', 'O tênis infantil masculino da linha Bibi Energy Baby 2.0 é o calçado ideal para acompanhar o dia a dia dos meninos! É perfeito para garantir a diversão com muito estilo. Confeccionado em tecido, este tênis oferece um material superconfortável, de fácil limpeza e secagem rápida. Sua modelagem casual deixa o pé à mostra, proporcionando muito frescor. Esse modelo é muito confortável para o uso diário e para ir à escola, seu solado de EVA incorpora a tecnologia **BPlus**, que garante maior tração e aderência ao piso, além de proporcionar um toque macio e emborrachado para mais conforto. A palmilha **Fisioflex** é extremamente macia, simulando a sensação de andar descalço, oferecendo um bem-estar incomparável para os pequenos. Combinando funcionalidade e conforto, este tênis é a escolha ideal para crianças que precisam de um calçado resistente e confortável para o dia a dia. Escolha o melhor tênis infantil, que une estilo, praticidade e conforto, perfeito para todas as aventuras diárias.', 199.9, 199.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdx4-m0ngppedtkeca3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1325759944%2F22993480050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261277870', 'Kit 2 Enxaguante Bucal Super 12h Frutas Vermelhas e Menta 500ml', 'Enxaguante Bucal Cimed Super Frutas Vermelhas e Menta 500ml – 12h de Proteção Proteção Completa com um Sabor Surpreendente Garanta uma higiene oral completa e refrescante com o Enxaguante Bucal Super sabor Frutas Vermelhas e Menta. Desenvolvido pela Cimed, este enxaguante foge do óbvio ao combinar a refrescância clássica da menta com o toque adocicado das frutas vermelhas, proporcionando uma experiência de limpeza agradável e duradoura. Sua fórmula poderosa oferece uma tripla ação defensiva para o seu sorriso: previne a gengivite, combate a formação de tártaro e protege contra as cáries. Além de manter a saúde da boca em dia, ele garante 12 horas de hálito fresco, deixando você confiante ao longo de todo o dia. O frasco de 500ml é ideal para o uso diário de toda a família. Principais Benefícios: Ação Prolongada: Garante até 12 horas de hálito fresco e protegido. Tripla Proteção: Previne a gengivite, o tártaro e as cáries. Sabor Inovador: Mix delicioso de Frutas Vermelhas e Menta. Confiança Cimed: Qualidade garantida para sua saúde bucal. Especificações Técnicas: Marca: Cimed Linha: Super Sabor: Frutas Vermelhas e Menta Volume: 500ml Indicação: Uso diário, pós-escovação. Complete sua rotina de escovação com a proteção e o sabor único do Enxaguante Super.', 37.98, 37.98, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-823r4-moltk26fhqmk8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F58261277870', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
