INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398686224', 'Máquina de Pintura Airless 1010W 110V 1,3HP FAK1010A Carbon Fak', 'MÁQUINA DE PINTURA AIRLESS 1010W 1,3HP 127V FAK1010A – CARBON FAK - Proporciona um acabamento mais uniforme, evitando imperfeições - Pode ser até 5x mais rápida e eficiente do que métodos convencionais, como rolos e pincéis - Evita desperdício, reduzindo a necessidade de retoque - Preenche facilmente locais de difícil acesso, como quinas, valetas e trincas - Impede que a tinta forme névoas e respingue - Ideal para aplicação em superfícies grandes - Pode ser utilizada em alvenaria, portas, janelas, portões, grades, madeiras e metais. A Máquina de Pintura Airless FAK1010A é indicada para aplicação com os bicos 515 e 517 as seguintes tintas: - Tintas à base de água - Conservantes de maderia - Primers - Primer de Lavagem Importante fazer a diluição correta conforme cada fabricante de tinta recomenda em suas embalagens. Existe uma diluição diferente da normal para este tipo de aplicação, que deve ser seguida para obter excelentes resultados FICHA TÉCNICA Marca – Carbon Fak Modelo – FAK1010A Voltagem – 127V Potência – 1010w – 1,3HP Frequência – 60Hz Pressão Máxima de Saída – 3000 PSI (lbf / pol2) Vazão da Pistola – 1,51 litros/min Comprimento do cordão elétrico – 2,15 m / 10A Material do tubo – Alumínio Peso – 9,300KG ITENS INCLUSOS: Mangueira com 6 metros; Pistola de Pintura; Bico 517 - Leque: Abertura de 25 a 30cm / espessura: 0,43mm / Ângulo de Pintura: 60°; Bico 515 – Leque: Abertura de 25 a 30cm / espessura: 0,38mm / Ângulo de Pintura: 50°; Tubo extensor para pintura com 50cm; Manômetro; Jogo de chaves; Manual de Instruções. **LUBRIFICAR A MÁQUINA A CADA USO Garantia 6 meses', 1828.75, 1306.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbiisv0d2ormff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389803646%2F22398686224', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
