INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599723544', 'Kit 6 und Creme De Arnica 60g Arte Nativa', 'Kit 6 und Creme De Arnica Arte Nativa 60GFINALIDADE DE USO: Produto para o corpo. Creme massageador de arnica, pode ser utilizado em locais doloridos ou com hematomas, possui ótima textura e espalha facilmente, sendo rapidamente absorvido pela pele, hidratando-a e proporcionando uma sensação confortável e refrescante. Pode ser removido com água e não é gorduroso. Não aplicar em local com ferimento. APRESENTAÇÃO: Cartucho contendo bisnaga de alumínio de 60g', 50.99, 45.12, NULL, 'Beauty > Bath & Body Care > Massage Oil', 'https://cf.shopee.com.br/file/sg-11134201-7rasf-matv1f4ekcb550', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F19599723544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260051963', 'Liquidificador Philco PH900 Preto 1200W', 'Se tem algo que vai te surpreender é o Liquidificador Preto 1200W! Ao primeiro giro do seu botão, você irá se apaixonar! São 1200W de potência e 12 velocidades, além de função pulsar, para você ir muito além do esperado. Com capacidade máxima de 3 litros, não haverá limites para sua imaginação e criatividade. Conta com faca de 6 lâminas, que são ultra afiadas e resistentes,permitindo que você triture até gelo. A palavra coar não existirá mais no seu vocabulário, pois este maravilhoso liquidificador conta com filtro que separa o suco das sementes e bagaço. Se quiser adicionar mais algum ingrediente, enquanto está preparando sua receita, não tem problema, pois sua tampa com orifício lhe dá esse benefício. E para que sua única preocupação seja cozinhar suas deliciosas receitas, conta com base antiderrapante, trazendo muito mais segurança! • Chave eletrônica 12 velocidades + pulsar/autolimpeza • Copo com facas integrado de 6 lâminas • Alça do copo anatômica • Tampa que permite servir sem retirá-la (posições fechada e servir) • Tampinha dosadora graduada (centro da tampa).', 159.9, 159.9, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/br-11134207-820l7-mnu1qlx23xtta1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F58260051963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799497302', 'Caixa de Som Philco Extreme Flash Light 650W PCX6701', 'A Caixa de Som Philco Extreme 650W Bluetooth 5.3 PCX6701 permite desfrutar de um som de alta qualidade e potente com nossos 650W de potência, sentindo cada nota e cada batida. Com dois woofers de 6,5” e um tweeter, você experimenta sons agudos harmonizados para uma reprodução de áudio impecável. A bateria interna recarregável oferece até 12 horas de uso contínuo. Conecte-se via Bluetooth V5.3 com alcance de mais de 10 metros, garantindo segurança e eficiência energética. Ilumine sua festa com os diferentes modos de Flash Light! As entradas USB, P10 (para microfone e guitarra) e P2 (auxiliar) facilitam a conexão de seus dispositivos para tocar suas músicas favoritas. Transforme qualquer ocasião em um evento memorável com a Caixa de Som Philco Extreme 650W Bluetooth 5.3 PCX6701! Entrada USB para Pendrives Entrada Auxiliar (P2) Entrada para Microfone P10 Entrada para Guitarra P10 Entrada cartão de memória para reprodução de música 2 woofers de 6,5"" e 1 Tweeter Bluetooth 5.3 Flash Light Função Philco connection (conectividade entre duas PCX6701) TWS Função Repetir Bateria de 12V/4Ah Controle Remoto.', 799.9, 799.9, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-822wl-mofq2stuws212e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F19799497302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993215029', 'Balcão de Cozinha Botanic M624 c/ 2 Portas e 3 Gavetas s/Tampo 120cm Nogueira/Fendi - Kappesberg', 'Otimize a funcionalidade da sua cozinha com o Balcão de Cozinha Botanic M624 da Kappesberg. Projetado para ser instalado com uma pia de 120cm, este balcão da linha Botanic oferece um amplo espaço para armazenamento, ideal para organizar utensílios, louças e objetos. Sua estrutura é robusta, feita em MDP, garantindo durabilidade e resistência. BALCÃO COZINHA KAPPESBERG BOTANIC M624 C/2 PORTAS 3GAVS S/TAMPO 120CM NOGUEIRA/FENDI Marca: Kappesberg Linha/Modelo: Cozinha Botanic Dimensões(Cm): Balcão Cozinha Botanic M624 c/2 Portas 3Gavs s/Tampo 120cm Comprimento(Profundidade): 52 cm Largura: 120 cm Altura: 88 cm Tipo de Estrutura do Móvel: - MDP Tipo de Pintura: - Pintura em UV (Ultravioleta), Texturizada Tipo de Acabamento da Pintura: - Fosca Tipo dos Pés: - Pés em MDP Tipo de Dobradiças: - Slow Motion Tipo de puxador: - Alumínio Escovado Quant. de Portas: - 2 Portas de Abrir Quant. de Gavetas: - 3 Gavetas Tipo de Corrediça: - Telescópicas Quant. de Prateleiras: - 1 Garantia: - 3 meses Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 640.91, 608.87, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-821dq-mh28wl9w8558fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F23993215029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22191572539', 'Kit Philco Prancha + Secador Travel Shine Rosa', 'Secador de Cabelos Travel Shine Rosa Philco: Para cabelos lindos em qualquer lugar você pode contar com o Secador de Cabelos Travel Shine Rosa Philco! Ele possui 2 velocidades e cordão elétrico com 1,9m, proporcionando maior eficiência e praticidade para atender a todas as suas necessidades. O Secador também conta com bocal concentrador que direcionará o fluxo de ar facilitando a secagem e modelagem dos seus cabelos, e anel para pendurar, facilitando no acondicionamento do produto. Prancha Travel Shine Rosa Philco: Com a Prancha Travel Shine Rosa Philco você terá cabelos muito mais lindos e ainda pode levá-la para qualquer lugar sem preocupação. Ela possui cordão giratório com 1,8m que facilitará na hora de manusear e placas de aquecimento com revestimento que facilita o uso. Sem falar na trava de fechamento que garante maior segurança! Potência do Secador: 1000W (127V) /2750W (220V) Potência da Prancha: 25W (Bivolt)', 159.9, 144.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-81ztm-mmw2n769ocua1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F22191572539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
