INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598436300', 'ESPATULA PLÁSTICA 13,1CM 152/2 ATLAS', 'Espátula plástica ideal para aplicação de massas sobre parede, tetos, portas, etc. Também pode ser utilizada para a retirada de bolhas em adesivos de parede.*Imagens meramente ilustrativas*Todas as informações divulgadas são de responsabilidade do Fabricante/FornecedorConstrução civil', 10.57, 10.57, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfg7-m96cmj5hg1zp76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1425275679%2F23598436300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201484184', 'Lixadeira Roto Orbital Roto GEX 125 280W 127V Bosch', 'A GEX 125 Bosch Professional é a lixadeira excêntrica ideal para um lixamento altamente eficiente com mais conforto. Esta lixadeira compacta com fio tem um design bem equilibrado, o que facilita o controle e manuseio ao longo de superfícies de madeira e outros materiais. As baixas vibrações da ferramenta, de 3.8 m/s2, permitem o acabamento de mais lixamentos, pois a fadiga e a dormência das mãos são reduzidas. Para uma eficiência de lixamento ainda maior, o motor mais rápido e potente de 290 W remove o material com grande agilidade. Modelo: GEX 125 Potência nominal: 280W Velocidade variável? Sim Número de velocidades: 6 Velocidade sem carga: 7500 - 12000 r.p.m Diâmetro do disco de lixa: 125mm Fixação da lixa: Velcro Diâmetro da órbita: 2,6mm Órbitas por minuto: 15.000 – 24.000 o.p.m. Incerteza (K): 3 dB Nível de pressão sonora: 81 dB(A) Nível de vibração ao polir: 1,500 m/s² Nível de vibração ao lixar: 3,800 m/s² Excentricidade: 1,3mm Cor: Azul Lixar superfícies de madeira, tinta, gesso e metal 01 Lixadeira Roto Orbital Roto GEX 125 280W Bosch, 01 Coletor de pó, 01 Manual de instruções', 591.45, 591.45, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8224o-mhus5s9kvv9f79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1425275679%2F58201484184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56107032696', 'Creme Para Pentear Definição Duradoura Cachos à Prova 1kg', 'O Creme Para Pentear Definição Duradoura Cachos à Prova Salon Line foi desenvolvido para quem busca aliar cuidado intenso e finalização potente, garantindo definição de cacho que resiste mesmo. Com ação condicionante, proporciona cachos definidos, brilho, controle do frizz e volume controlado. <>INDICAÇÕES$& Para quais tipos de cabelo? Para cabelos ondulados, cacheados e crespos. Qual a indicação? Para cabelos sem definição, com frizz, encolhido e opaco. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Com Extrato de Cereja, D-pantenol e proteína do arroz hidrolisada, ativos hidratantes e nutritivos, que ajudam a reter a umidade dos fios, combatendo o ressecamento e o frizz, mantendo a aparência dos cachos perfeita, com cachos firmes. <>MODO DE USO$& Qual a melhor forma de usar? Com os cabelos limpos e úmidos, aplique o creme para pentear uniformemente no comprimento e nas pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os, iniciando o movimento das pontas até a raiz. Não enxágue. <>CARACTERÍSTICAS$& É produto vegano? O Creme Para Pentear Definição Duradoura Cachos à Prova é vegano. É liberado? O Creme Para Pentear Definição Duradoura Cachos à Prova é liberado.', 42.0, 36.93, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-8260j-mlo15cxpxwjkde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F56107032696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093427136', 'Kit Definição e Fixação Ultra Extraordinária com GelaCreme', 'O Kit conta com as Gelacremes #Todecacho. Aqui você encontra a Gelacreme Fixação Ultra Extraordinária e a Definição Ultra Extraordinária. <>INDICAÇÕES$& Para quais tipos de cabelo? Para cabelos ondulados, cacheados e crespos. Qual a indicação? Cabelo opacos, desidratados e sem definição. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Conta com a eficaz tecnologia PROFIX que garante 72h de formatação, fixação e duração dos cachos e crespos! <>MODO DE USO$& Qual a melhor forma de usar? Gelacreme Fixação e Gelacreme Definição Antes da primeira aplicação, misture todo o produto até que fique homogêneo. Com os cabelos limpos e úmidos, aplique a GelaCreme mecha a mecha, uniformemente, no comprimento e pontas. Desembarace com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. É indicado o uso de até 30g para finalização e penteados. <>CARACTERÍSTICAS$& É produto vegano? Todos os produtos são veganos. É liberado? Nenhum produto é liberado.', 60.0, 54.75, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-m1cw63uuil0x96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F23093427136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23991934410', 'Cadeado para bicicleta 60 cm com chave - CD-35 - Western', 'Produto: Cadeado para bicicleta 60 cm com chave - CD-35 Marca: Western Descrição: Mantenha sua bicicleta segura com o Cadeado para bicicleta 60 cm com chave - CD-35 da Western, feito com aço carbono e pvc, espessura 12 milimetros, acompanhado de 2 chaves. Indicado para trancar ou prender bicicletas. O CD-35 é encapado e não risca, possui 60 cm de comprimento e acompanha 2 chaves. Com espessura de 12mm, o CD-35 é flexível e resistente. Não deixa sua bicicleta estacionada sem o uso do cadeado. Mas, se previna de vândalos e adquira o Cadeado para bicicleta 60 cm com chave - CD-35 da Western e faça suas rotas tranquilamente! Este item é comercializado em cores sortidas. Oferecemos as ferramentas de qualidade que não podem faltar para você! Características: • Acompanha chave reserva • Flexível • Encapado evitando riscos e avarias • 60 cm de comprimento • Fácil e rápido de instalar. Especificações: Material: aço carbono e PVC (policloreto de vinil) Tipo de embalagem: suporte Comprimento: 60 cm Espessura: 12 mm Este item é comercializado em cores sortidas. Itens Inclusos: 2 chaves. Dimensões (C x L x A): 63.50 x 2.30 x 2.30 centímetros Peso: 0.42 Kg', 30.81, 30.81, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8258g-mqwz554larrac3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F23991934410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793229362', 'Conjunto Infantil Menino Blusa e Shorts Moletinho Leve', 'Seja Bem vindo a Loja Oficial da DAZE MODAS na SHOPEE. Feito em 100% poliéster, este conjunto de camiseta e bermuda é ideal para os dias de sol e aventura. Seja no parque, na praia ou naquele passeio em família no shopping, seu pequeno estará sempre estiloso e à vontade. E mais: é super prático! Fácil de lavar, seca rápido e está pronto para a próxima brincadeira sem atrasos. Perfeito para papais que valorizam praticidade e conforto no dia a dia dos seus filhos. Especificações do Produto: > Marca: Daze Modas > Tecido: Poliéster > Material: Moletinho > Composição: 100% Poliéster > Modelagem: Padrão > Blusa: Gola redonda/Manga Curta > Bermuda: Cós elástico/Cordão Ajustável > Tamanhos: 4 ao 14 > Tabela de medidas na última foto Especificações do Modelo: Modelo Veste: 10 Tamanho do produto que o modelo usou na foto: 10 Altura: 1.40 Tórax: 68cm Cintura: 59cm Quadril: 74cm HORÁRIO DE ATENDIMENTO: De Segunda à Quinta das 08h00 às 18h00 De Sexta das 08h00 às 17h00', 109.99, 67.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Sets', 'https://cf.shopee.com.br/file/br-11134207-820l6-mozwcn76mxabdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287750271%2F22793229362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44061884331', 'Lavadora de Alta Pressão 1800W 2000PSI Com Rodas E Aplicador de Detergente WL 2660 TURBO Wap', 'Você estará comprando: 01 Lavadora de Alta Pressão WL 2660 Turbo WAP 01 Bico Ajustável 01 Mangueira de Alta Pressão 5 Metros 01 Aplicador de Detergente 01 Bico Turbo Com potência de 1800W, a Lavadora de Alta Pressão WAP WL 2660 Turbo é a sua aliada para enfrentar as tarefas mais desafiadoras de limpeza. Combinando força e eficiência, é projetada para proporcionar resultados satisfatórios em diferentes superfícies. A pressão máxima de 2000 PSI e vazão de 420 L/h permite a remoção fácil até das sujeiras mais incrustadas e resistentes. Transforme tarefas cansativas em trabalhos mais rápidos e eficazes através da alta pressão. Com pacote completo de acessórios, você receberá uma pistola de alta pressão, baioneta, bico regulável para ajustar a intensidade da limpeza, bico turbo para as tarefas mais desafiadoras, uma mangueira de alta pressão de 3 metros que oferece maior alcance, engate rápido e até mesmo uma shampoozera, permitindo que você aplique detergente de maneira uniforme para limpezas mais profundas e eficazes. Seu design inclui um porta acessórios para todos os componentes, mantendo tudo organizado e ao alcance das mãos durante o uso. Isso significa que você pode focar na limpeza sem se preocupar com fios emaranhados ou acessórios perdidos. Além dos benefícios de limpeza e praticidade, a Lavadora de Alta Pressão WAP WL 2660 Turbo também possui eficiência de uso de água. Com até 80% de economia de água em comparação com métodos tradicionais, você estará contribuindo para a conservação dos recursos naturais enquanto mantém seus espaços impecavelmente limpos. Conquiste a limpeza completa e eficiente que você deseja com a Lavadora de Alta Pressão WAP WL 2660 Turbo. Seja em sua casa, jardim, veículo ou local de trabalho, descubra como é fácil e eficaz manter seu espaço impecável! Informações Técnicas: Modelo: WL 2660 Turbo Marca: Wap Tipo do Motor: Universal Potência Elétrica: 1800W Tensão: 127v ou 220v (Escolher, conforme disponibilidade) Frequência: 60hz Pressão Máxima: 2000 PSI Vazão Máxima Aproximada: 420 L/h Nível de Ruído: 90 dB(A) Bico Turbo: Sim Aplicador de Detergente: Sim Bico com Jato Ajustável: Sim Comprimento da Mangueira: 3 Metros Tipo de Mangueira: Nylon Tipo de Conexão: Engate Rápido Tipo de Bomba: Axial Classificação Inmetro: Sim Comprimento do Cabo Elétrico: 5 Metros Classe de Isolação: II Índice de Proteção: IPX5 Aplicação: Ocasional Cor: Cinza com Amarelo Material: Polímeros e Metais Dimensões da Embalagem CxLxA: 42 x 32,5 x 49,5 cm Dimensões do Produto Montado CxLxA: 32,9 x 26,2 x 70,0 cm Peso Aproximado: 8,2kg Garantia: 1 Ano Código WAP: FW009595 (127V) | FW009596 (220V) SKU DA LOJA: CONFI10125', 1299.0, 1129.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824ga-mpjfd026dnv204', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F334741920%2F44061884331', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199187795', 'Lavadora e Desobstruidora de Alta Pressão WAP 1400W Mangueira Desentupidora Atacama Smart Ultra 2200 127V', '*NÃO POSSUÍMOS DISPONIBILIDADE NA VOLTAGEM 220V* Importante: Após a confirmação do pagamento, não realizamos cancelamento de pedidos. Em caso de dúvidas, recomendamos entrar em contato antes de finalizar a compra. A WAP Atacama Smart Ultra 2200 é uma desobstruidora e lavadora de alta pressão 2 em 1, projetada para limpeza eficiente de superfícies variadas e desentupimento de tubulações com jato de água. Ideal para uso residencial ou leve em áreas externas, oferecendo praticidade e economia de água em comparação com lavagens tradicionais. 🧰 Principais Características Função 2 em 1: atua como lavadora e desobstruidora de alta pressão. Economia de água: proporciona limpeza eficaz utilizando até 80 % menos água que mangueiras comuns. Aplicações: limpeza de carros, motos, bicicletas, calçadas, paredes e desentupimento de canos, ralos e calhas. Porta-acessórios integrado: facilita a organização da lança, pistola e mangueiras. Compacta e portátil: alça para transporte e montagem prática com sistema de engate rápido. Sistema Stop Total: corta automaticamente o fluxo de água e energia quando o gatilho é liberado, protegendo o motor e economizando energia. 🔧 Especificações Técnicas Voltagem: 127 V Potência elétrica: 1400 W Pressão máxima: 1500 PSI Vazão de água: 330 L/h Motor: Universal Frequência: 60 Hz Tipo de sujeira: Moderada Mangueira de alta pressão: 3 m Mangueira desentupidora: 2 m Comprimento cabo elétrico: 5 m Tipo de plugue: 2 pinos, 10 A 📦 Conteúdo da Embalagem Pistola de alta pressão com trava de segurança Baioneta com conexão rápida Lança com bico regulável (leque e concentrado) Mangueira de alta pressão (3 m) Mangueira desentupidora (2 m) Engate rápido Agulha de limpeza de bico 📏 Dimensões & Peso Produto (C × L × A): 22 × 25 × 45 cm Caixa (C × L × A): 24 × 27 × 46,5 cm Peso líquido: 4 kg Peso bruto: 6 kg Garantia: 12 meses oferecida pelo fabricante.', 779.88, 559.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mka1kv20qeip3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101261117%2F22199187795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
