INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898668325', 'Climatizador 100 Litros Ventisol Cinza CLI100PRO-01 NAC 127V 210W', 'Descubra o Climatizador Ventisol CLI100PRO-01, a solução ideal para quem busca conforto e qualidade. Com design moderno e funcional, este climatizador é perfeito para ambientes residenciais e comerciais. Com tecnologia avançada, ele oferece 5 funções em um único aparelho, garantindo um clima agradável e saudável. Com diferenciais que o tornam um produto de alta qualidade: 5 em 1: ele ventila, climatiza, umidifica, filtra e circula o ar. Filtro colmeia: Proporciona resfriamento e umidificação do ar, além de ser lavável, facilitando a manutenção. Reservatório de 100L: Com triplo sistema de abastecimento (laterais e tampa superior), garante maior praticidade no uso. Compartimento para gelo: Aumenta a eficiência do resfriamento, ideal para os dias mais quentes. Abastecimento contínuo: Pode ser conectado à rede hidráulica, eliminando a necessidade de reabastecimento manual. 3 velocidades e oscilações ajustáveis: Oferece conforto personalizado com vertical automática e horizontal manual. Bomba de segurança: Desliga automaticamente na falta de água, garantindo segurança e durabilidade ao aparelho. Fácil transporte: Equipado com 4 rodas, facilita a movimentação entre os ambientes. Baixo consumo de energia: Uma opção econômica e sustentável, produzida com material reciclado. Especificações Técnicas CLI100 PRO-01: Cor: Cinza Voltagem: 127V', 1571.0, 1571.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7ra1e-mbfpc6u3ddlmaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207374375%2F23898668325', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
