INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40553475198', 'Kir 2 Mini Câmera de Segurança A9 HD Wi-fi Preto com Sensor de Movimento 110V e Suporte para Encaixe', 'Mini Câmera de Segurança A9 HD Wi-fi com Sensor de Movimento 110V e Suporte para Encaixe JORTAN Especificações do produto: Material: Liga de alumínio. Resolução de vídeo: 1980 x 1080p. Formato de vídeo: AVI. Tipo de cartão de memória: Suporta cartões micro SD de até 128GB (TF não incluso). Suporte ao aplicativo: iOS / Android. Itens unitários inclusos (x2): - 1 Câmera A9 Mini. - 1 Mini suporte de metal com encaixe para a câmera. - 1 Cabo USB. - 1 Manual de instruções. Especificações Técnicas Visão Noturna: 6 LEDs infravermelhos 940nm / F3 | Distância de iluminação: 5 metros. Formato de Vídeo: ASF. Ângulo de Visão: 90° a 150°. Suporte de Rede: Wi-Fi 2.4 GHz (Não Suporta Redes 5GHz). Áudio (Captação): Até 5m. Corrente de Carga: 240 mA. Taxa de Quadros: 16 FPS. Alimentação: 3.7 V. Codificação de Vídeo: H.264. Armazenamento: Suporta cartão TF (Micro SD) de até 128 GB. Temperatura de Operação: -10°C a 50°C.', 99.99, 49.99, NULL, 'Cameras & Drones > Security Cameras & Systems > CCTV Security Cameras', 'https://cf.shopee.com.br/file/sg-11134201-825b1-meutjijchfd345', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363055219%2F40553475198', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498323714', 'Camisa Umbro Santos I 2025', 'O lugar dos Santos é o topo! A Umbro apresenta a camisa titular do Alvinegro Praiano para 2025. Símbolo de identidade com a cidade, valorizando a ligação do clube com a Baixada Santista, fortalecendo uma história que já soma diversas conquistas. O novo uniforme representa a escadaria de Mont Serrat, ponto turístico da cidade, simbolizando o esforço para subir à Série A. A peça traz design na cor branca com grafismos em zigue-zague na gola, que remetem à escadaria, já na parte inferior direita, um selo especial traz a frase “Glorioso Alvinegro Praiano”, além de exibir o escudo do clube na região do tórax. Composição: PoliésterCor predominante: BrancaModelo: TorcedorGênero: MasculinoOrigem: NacionalEscudo: BordadoClube: SantosManga: CurtaGola: VDimensões aproximadas (A x L):P: 71 x 48 cmM: 73 x 55 cmG: 74 x 58 cmGG (2G): 76 x 60 cmEG (3G/2GG): 80 x 65 cm', 184.9, 184.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/sg-11134201-7rd5k-m7c70bz2gd0v8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F23498323714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
