INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593484469', 'Kit 10 Caixinha De Jogo Memoria Selva Lembracinha Safari Infantil Jogo infantil Festa Prenda Criança', 'PRODUTO ANUNCIADO: 10 JOGOS DA MEMORIA COM 18 CARTAS EM CADA CAIXA O Jogo da Memoria trabalha a memória visual, a atenção e a concentração, onde as crianças podem encontrar e associar seus pares para maior desenvolvimento cognitivo. Com tudo isso a criança aprende de maneira lúdica. Beneficios do Jogo da Memoria: desenvolvimento do raciocínio rápido, da noção espacial, da percepção tátil, ajuda a construir a ideia de competição e a importância de saber ganhar ou perder, e incentiva a socialização, já que o jogo permite que mais de uma pessoa participe. MEDIDAS: Cada caixa mede aproximadamente 9cm x 6 cm x 1 cm Ideal para Kit Festa, Lembrancinha Faixa etária: + 4 anos QUALQUER DUVIDA ESTAMOS A DISPOSIÇÃO BOLINHA MAGICA.', 21.66, 17.33, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1h9s3wt04js78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F22593484469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792113335', 'Kit Cortador de Massinha Neon Forminha Modelar Dinossauro Safari Kit Lembrancinha Aniversario Prenda', '***ATENÇAO, NAO PERSONALIZAMOS OS PRODUTOS. TODOS VAO SORTIDOS NOS MODELOS DAS FOTOS. ESCOLHA A COR DESEJADA OU A OPÇÃO SORTIDO PARA IR CORES SORTIDAS. ***** (ATENÇÃO: ANÚNCIO POSSUI VARIAÇÃO, ESCOLHA A QUANTIA DESEJADA DE CORTADORES NO ANÚNCIO, ANTES DE CONCLUIR A COMPRA) ITEM ANUNCIADO CORTADOR DE MASSINHA - FORMINHAS COLORIDOS E SORTIDOS A coleção possui mais de 32 Modelos diferentes ( ANIMAIS SAFARI, DINOSSAUROS ) COLECIONE!!! (há Repetiçoes) Material de plástico Comprimento de 4 a 6 cm Altura 1,5 cm QUALQUER DUVIDA ESTAMOS A DISPOSIÇÃO PARA ESCLARECER. ATENCIOSAMENTE, BOLINHA MÁGICA; PEQUENO PRESENTE, GRANDE ALEGRIA!! BOLINHA MAGICA', 11.23, 10.11, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzexv9ykr6tdaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F23792113335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392470777', '20 Bolha de Sabao + 20 Bolinha 27mm Para Kit Festa Lembrancinha Aniversario Prenda Quermesse novo', '***ATENÇAO, NAO PERSONALIZAMOS E NEM FABRICAMOS NENHUM PRODUTO. TODOS VAO SORTIDOS NOS MODELOS DAS FOTOS. SEM POSSIBILIDADE DE ESCOLHA DE COR. ITEM ANUNCIADO 20 BOLHA DE SABAO 50ml SORTIDAS. (10cm ALTURA e 3 de Diametro) **NAO PERSONALIZAMOS. **JA VAI COM O LIQUIDO. COMPOSIÇÃO: AMINOÁCIDO, CORANTE E ÁGUA 20 BOLINHA PULA PULA 27 MM SORTIDAS IDEAL PARA USAR EM MAQUINAS DE BOLINHAS, FESTA, REVENDAS E MUITO MAIS QUALQUER DUVIDA ESTAMOS A DISPOSIÇAO BOLINHA MAGICA', 67.89, 54.31, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98r-lm5z1ubsseuv5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F23392470777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17588440684', 'Cama Articulada Solteiro para Colchão 88 x 188 cm Multimóveis CR35035 Amendoa', 'A Cama Articulada Solteiro para Colchão 88 x 188 cm Multimóveis CR35035 foi produzida para agregar conforto e beleza em seu quarto! Possui estrutura em MDP, acabamento em pintura UV, sistema de articulação e trava, chave para segurança de uso fechada, e para completar, a cama suporta até 130kg. Além de ser um móvel prático e funcional, foi desenvolvida 100% de forma ecológica garantindo a vitalidade, resistência e durabilidade no ambiente. Conteúdo da Embalagem: Cama Articulada Solteiro Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 198,5cm | Largura: 97,2cm | Profundidade: 57,2cm (fechada) - 193cm (aberta) *Tamanho máximo do colchão (L x A x P): 90,5 x 18 x 190cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 1079.99, 979.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-22100-9yaotway34iv56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F17588440684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252423614', 'SANDALIA INFANTIL MENINO CARTAGO MINI III MARROM/CASTOR/AZUL 12461', 'Sandália Infantil Cartago Baby Mini III Cor: MARROM/CASTOR/AZUL BM853 Marca: GRENDENE / CARTAGO Ref. 12461 Cores divertidas, material confortável e tiras ajustáveis que facilitam a vida dos pais na hora de calçar os pequeninos. A Sandália Cartago Mini III Baby é ideal para você oferecer um calçado simples, prático e lindo para os seus clientes. Um produto com a nova tendência preppy, trazendo sofisticação e esportividade, e as cores seguem como de toda a família, com opções mais esportivas, modernas e elegantes. Com palmilha confeccionada em EVA macio, a Cartago Baby Mini III proporciona um toque suave e confortável aos pés, permitindo que as crianças se movam com liberdade e bem-estar. O solado antiderrapante em PVC garante segurança em cada passo, evitando escorregões e proporcionando uma maior aderência ao solo, essencial para os momentos de brincadeira e exploração. GUIA DE TAMANHOS: TAM. 17/18 = 11,6cm TAM. 19 = 12,6cm TAM. 20/21 = 13,6cm TAM. 22 = 14,6cm TAM. 23/24 = 15,6cm TAM. 25 = 16cm TAM. 26/27 = 17,6cm', 58.9, 58.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-81zu3-mipw6lke3lzabb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1402904120%2F58252423614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48764671930', 'Monja 100 Unidades Fita Dupla Face Adesiva para Suporte de Unhas Postiças, Exibição e Ferramenta', 'Especificação: Nome do Item: Fita Dupla Face para Suporte de Unhas Cor: Transparente Quantidade: 1 folha, 100 adesivos/folha (total de 100 peças). Tamanho da folha: Aprox. 16,9 * 10,9 cm Características: 1. Fita dupla face de alta transparência e forte aderência; sem necessidade de corte — basta descolar e colar para facilitar o uso. 2. Feita de acrílico durável; ambos os lados são altamente adesivos. 3. Cristalino — quase invisível em superfícies, perfeita para fixar objetos leves ao vidro. 4. Ideal como expositor de unhas em salões para exibir unhas postiças bonitas. 5. Usada principalmente para fixar pontas de unhas em suportes de exibição de nail art; também segura fotos, papéis, cartões, chips, glitters, miçangas e pequenas decorações leves. 6. 100 grãos por pacote — quantidade suficiente para uso frequente. 7. Perfeita para iniciantes em unhas, amantes de unhas e artistas de unhas profissionais. Incluído na embalagem: 1 folha de Fita Dupla Face para Suporte de Unhas', 9.0, 8.5, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134253-8257z-mqxtfku0hybm14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F48764671930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45764671910', 'Dragon Ranee Love Tint Mirror Batom Labial: À Prova D''Água, Hidratante e Brilhante, Ideal para a Primavera e Maquiagem', '✨ Batom Brilho Labial Dragon Ranee - 6 Cores Vibrantes | Textura Brilhante e Cor Duradoura 🎨 Fácil de colorir – 6 tons vibrantes. 💎 Textura brilhante – acabamento brilhante e cintilante. ⏳ Cor para o dia todo – mantém a vivacidade. 🚫 Sem manchas – permanece no lugar. 💧 Aplicação suave – alta pigmentação. ✨ Resistente à transferência – fixa a cor. 🖌️ Modo de uso: Aplicar diretamente; camadas para maior intensidade. 📦 Nota: Pode haver variações de lote; prevalecerá o produto real.', 11.7, 9.0, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134253-82582-mqxspkuyrzsx57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F45764671910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792439450', 'Fralda Pampers Pants Ajuste Total G com 144un', 'A fralda calça Pamper Pants Ajuste Total é fácil de trocar até quando o bebê está em movimento. Com cintura elástica 360° se adapta ao corpinho do bebê. A fralda pants ajuste total possui canais de ar que permitem que o ar circule livremente pela fralda, para que o bumbum fique menos abafado e a pele fique arejada e sequinha durante a noite. Pampers Pants Ajuste Total também possui gel mágico que absorve e retém a umidade no interior da fralda com uma camada ultra absorvente.A fralda calça Pampers Pants Ajuste Total é muito fácil de pôr e tirar basta seguir o modo de uso:1. Coloque a mão dentro da fralda;2. Suba a fralda como um shortinho através dos elásticos adaptáveis;3. Para retirar a fralda rasgue suas laterais e retire-a normalmente;4. Enrole e feche a fralda com a fita adesiva da parte de trás. • O jeito fácil de trocar • Fácil de pôr • Cintura elástica 360° que se adapta ao corpinho do seu bebê e agora com sistema de Ajuste Inteligente • Fácil de tirar rasgue suas laterais e retire-a normalmente • Canais de ar que evitam que a fralda fique caída • Até 12 horas* de proteção para noites inteiras de sono sequinho • *Pode variar de acordo com os hábitos e características do bebê', 283.69, 257.02, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rbng-llxt8u6erdcqbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F22792439450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898006772', 'Tomada Femea Reboque 6 Polos Engate Alumínio Cromado Carreta Carretinha Cavalo Mecânico Original', 'TOMADA ENGATE ALUMÍNIO CROMADA FEMEA 6 POLOS CARRO- BRATUS A tomada fêmea de engate é um componente essencial para quem precisa de uma conexão elétrica segura e eficiente entre o veículo e o reboque, carreta ou cavalo mecânico. Com um design robusto e de fácil instalação, nossa tomada engate de 6 polos é ideal para diversas aplicações automotivas, garantindo uma transmissão de energia confiável e duradoura. • Aplicação: Em todos os veículos leves com engates e reboques; • Função: Ligação Elétrica (iluminação) veículo rebocador; Características: • Conforme norma ISO 1724; • Corpo Injetado em Alumínio com alta resistência; • Polos de contato em liga metálica antioxidante; • Fácil montagem e desmontagem; • Número de Polos: 6 polos Esquema de Ligação: 🟡 Fio Amarelo: Luz Direção Esquerda; 🔵 Fio Azul: Luz Ré: ⚪️ Fio Branco: Terra; 🟢 Fio Verde: Luz Direção Direita; 🟤 Fio Marrom: Lanternas e Iluminação de Placa; 🔴 Fio Vermelho: Luz de Freio; Benefícios: ✅Durabilidade: Fabricada com materiais de alta qualidade, garantindo longa vida útil. ✅Segurança: Conexão elétrica segura e estável, evitando falhas durante o transporte. ✅Versatilidade: Compatível com uma ampla gama de veículos e reboques. ✅Fácil Instalação: Design de engate rápido que facilita a instalação sem necessidade de ferramentas especiais. Com nossa tomada de engate, você garante uma conexão elétrica confiável e segura entre seu veículo e reboque, proporcionando tranquilidade e eficiência em todas as suas viagens. Invista na qualidade e tenha a certeza de que sua carga estará sempre segura. ○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○ A Ninja Parts, fundada em 2016 em Curitiba-PR, é um e-commerce referência nacional em peças e acessórios automotivos. Oferecemos as melhores marcas com qualidade e envio rápido, priorizando a satisfação do cliente e um excelente atendimento. Garantia • 90 dias a partir da data da compra; • Garantia válida apenas para defeitos de fábrica- Não é coberto mau uso, má instalação, quebra ou adaptações que alterem características originais do produto; Trocas e Devoluções • Importante que todos os itens sejam enviados nas embalagens originais de forma segura; • Caso o produto retorne danificado, os custos ficarão sob responsabilidade do cliente; Recomendação • A instalação seve ser realizada por um profissional de sua confiança; Compra Garantida • Transação Segura; • Estorno automático em caso de imprevistos; • Acompanha nota fiscal; • Produtos a pronta entrega.', 44.89, 31.43, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-7ra0h-m54d123vjypg05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F454424487%2F20898006772', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200521968', 'BROCA CHATA PARA MADEIRA, 24 X 150 MM, HASTE SEXTAVADA, 1PC // MTX', 'A Broca Chata para Madeira MTX 704159, com um imponente diâmetro de 24 mm e uma robusta haste hexagonal de 6 lados, é uma ferramenta indispensável para profissionais e entusiastas que buscam eficiência e precisão em suas perfurações. Projetada com uma parte de trabalho em forma de pá e bordas cortantes nas laterais, esta broca é excepcionalmente eficaz para criar furos profundos e cegos, adaptando-se com facilidade a diferentes tipos de madeira. Sua versatilidade permite que seja instalada tanto em furadeiras manuais quanto elétricas, ou mesmo em máquinas de perfuração, tornando-a uma escolha versátil para uma ampla gama de projetos. Vantagens Detalhadas: Durabilidade e Resistência ao Desgaste: A broca é fabricada com aço 45, um material conhecido por sua resistência e durabilidade. As bordas cortantes são temperadas até atingirem uma dureza de 48-52 HRC, garantindo uma resistência ao desgaste superior. Esta característica assegura que a broca mantenha seu desempenho e precisão ao longo do tempo, mesmo sob condições de uso intensivo. Alta Qualidade de Trabalho: Equipada com cortadores na borda da parte cortante, esta broca proporciona furos uniformes e de alta qualidade. Essa precisão é essencial para alcançar acabamentos profissionais e de alto padrão em trabalhos de marcenaria e carpintaria, onde a qualidade do furo pode impactar significativamente o resultado final do projeto. Possibilidade de Aumentar a Profundidade de Perfuração: A compatibilidade com o extensor MTX 70495 oferece aos usuários a flexibilidade de ajustar a profundidade de perfuração conforme necessário, ampliando a versatilidade da broca. Esta funcionalidade é particularmente útil em projetos que exigem furos mais profundos, proporcionando uma solução eficaz sem a necessidade de trocar de ferramenta. Trabalho Confortável: A haste hexagonal de 6 lados previne a rotação indesejada no mandril da ferramenta, garantindo um manuseio seguro e estável. Essa estabilidade não apenas facilita a operação, mas também contribui para a segurança do usuário, minimizando o risco de deslizes ou acidentes durante a perfuração. Em resumo, a Broca Chata para Madeira MTX 704159 é a escolha perfeita para quem valoriza a eficiência, durabilidade e precisão em suas tarefas de perfuração. Seja para uso profissional em oficinas especializadas ou para projetos de bricolagem em casa, esta broca oferece uma combinação inigualável de desempenho confiável, resultados de alta qualidade e uso confortável, assegurando que cada projeto seja realizado com a máxima eficácia e satisfação.', 13.0, 13.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821f3-mgxoh41kfw226a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58200521968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200742242', 'BROCA PARA CONCRETO, 7 X 110MM, ENCAIXE SDS PLUS, 1PC // MTX', 'A Broca de Concreto MTX, SDS PLUS é uma ferramenta de alta performance, meticulosamente projetada para perfurar concreto, pedra e tijolo com eficácia inigualável. Equipada com uma placa de corte de liga de carboneto de tungstênio VK8, esta broca ostenta uma dureza impressionante de 80-90 HRC, garantindo uma capacidade de perfuração eficaz e duradoura para enfrentar as tarefas mais exigentes. A tecnologia SDS Plus, incorporada à broca, facilita uma instalação rápida e uma fixação segura no martelo perfurador, otimizando o processo de trabalho e assegurando resultados precisos e confiáveis. Vantagens: Encaixe SDS Plus: A integração do sistema de encaixe SDS Plus permite uma instalação rápida e uma fixação extremamente segura da broca no martelo perfurador, proporcionando um processo de trabalho mais ágil e eficiente. Esta característica é crucial para profissionais que valorizam o tempo e a precisão em seus projetos. Durabilidade Reforçada: A parte de trabalho da broca é fabricada em aço de liga, enriquecido com cromo, conferindo-lhe uma resistência superior às cargas elevadas típicas da perfuração com impacto. Essa composição robusta assegura que a broca possa suportar as condições mais adversas de trabalho sem comprometer seu desempenho. Cabeça Centralizadora: A presença de uma cabeça centralizadora na placa de corte é um diferencial estratégico que previne o desvio da broca durante a operação. Este recurso eleva significativamente a qualidade da perfuração, além de prolongar a vida útil da ferramenta, garantindo uma operação mais estável e controlada. Redução de Vibrações: A broca apresenta uma área de seção transversal do corpo aumentada, o que contribui para a minimização das vibrações durante a perfuração. Essa característica não só melhora a experiência de uso, mas também previne a quebra da broca, promovendo uma operação mais segura e eficaz. Remoção Eficiente de Resíduos: Com uma dupla espiral reforçada, a broca é capaz de remover uma grande quantidade de resíduos de perfuração, reduzindo a carga sobre a ferramenta e aumentando sua produtividade. Este design inteligente assegura uma evacuação rápida dos resíduos, mantendo a área de trabalho limpa e facilitando o processo de perfuração. A Broca de Concreto MTX, SDS PLUS se destaca como uma solução exemplar para profissionais e entusiastas que buscam máxima precisão, durabilidade e eficiência em suas ferramentas de perfuração. Ideal para uma ampla gama de aplicações, desde construção e renovação até tarefas de manutenção, esta broca oferece um desempenho confiável e de alto nível, superando as expectativas e lidando com os materiais mais resistentes com facilidade.', 11.19, 11.19, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821g8-mh91t8abdziif9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58200742242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394500614', 'BROCA ACO RAPIDO STANDARD, PARA METAL, POLIDA, HASTE CILINDRICA, 5MM, 10PCS // MTX', 'A Broca de Aço Rápido para Metal MTX 715509, fabricada em aço rápido HSS de alta qualidade, é uma ferramenta essencial para profissionais que necessitam de precisão e eficiência em suas operações de perfuração. Este conjunto, que inclui 10 peças, é ideal para a criação de furos com 5,0 mm de diâmetro, oferecendo desempenho superior em trabalhos com metais pretos, aço, ferro fundido e bronze duro. Com um ângulo de afiação de 118 graus, estas brocas são otimizadas para garantir o melhor em performance de corte e durabilidade. Vantagens Detalhadas: Durabilidade e Longevidade Ampliadas: As brocas são confeccionadas em aço rápido HSS, um material renomado por sua resistência e durabilidade. As bordas de corte são cuidadosamente temperadas até alcançarem uma dureza de 62-65 HRC, assegurando que a broca mantenha sua eficácia mesmo após uso intensivo. Perfuração Eficiente: A superfície das brocas é polida para minimizar o atrito com as paredes do furo, permitindo uma perfuração mais rápida e com menos esforço. As ranhuras presentes nas canaletas atuam como elementos de corte adicionais, melhorando significativamente a remoção de cavacos e a eficiência geral do processo de perfuração. Design Inteligente para Desempenho Superior: O diâmetro da parte de trabalho das brocas é projetado para diminuir em direção à haste, uma inovação que reduz o atrito durante a perfuração e previne que a broca se prenda no material. Esta característica assegura uma operação mais suave e eficiente, contribuindo para a precisão do furo. Versatilidade sem Comparação: Com hastes cilíndricas, estas brocas são compatíveis com mandris de qualquer tipo, oferecendo uma flexibilidade sem igual para uma variedade de máquinas de perfuração. Esta versatilidade as torna adequadas para uma vasta gama de aplicações, desde trabalhos em oficinas mecânicas até projetos de construção pesada. Embalagem Conveniente para Alta Demanda: A embalagem contém 10 brocas, fornecendo um estoque adequado para lidar com um grande volume de trabalho. Isso não apenas facilita o armazenamento e a organização das brocas, mas também garante que substituições estejam prontamente disponíveis quando necessário, mantendo a continuidade e a eficiência nos trabalhos. A Broca de Aço Rápido para Metal MTX 715509 é a escolha perfeita para profissionais que demandam o máximo de suas ferramentas de perfuração, oferecendo uma combinação inigualável de durabilidade, eficiência e versatilidade. Desenvolvida para satisfazer as necessidades dos ambientes mais desafiadores, esta broca garante resultados de alta qualidade em uma diversidade de materiais.', 20.56, 20.56, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824j1-mfl3k7eaha88a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F22394500614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200627797', 'MICROMETRO MECANICO, 0-25MM, 1PC // MTX', 'Micrômetro mecânico MTX 3172559 é a ferramenta perfeita para medir a espessura de chapas metálicas em espessuras finas, de 0 a 25 mm. O micrômetro fornece resultados de alta precisão, com um passo de medição de 0.01 mm e um erro permitido de ±0.004 mm. O micrômetro é feito de aço ferramenta, o que garante sua resistência e durabilidade. O design inclui uma rolha que fixa o microparafuso, facilitando a leitura dos resultados. O aparelho também é fornecido em caixa de plástico com almofada de espuma, o que garante armazenamento e transporte sem risco de danos. O micrômetro é ideal para uso em produção, oficina mecânica e centro de serviços automotivos. É fácil de usar e transportar, o que o torna uma ferramenta versátil e confiável para medir chapas metálicas de espessuras finas.', 132.65, 132.65, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821dh-mh20zpjzomq559', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58200627797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392650425', 'Saco para Lavar Roupa Delicada Médio Branco/Rosa Log Ordene', 'O Saco para Lavar Roupa Delicada Médio 40 x 50 cm Branco/Rosa Log Ordene possui zíper e permite que as roupas delicadas sejam lavadas sem danos. É perfeito para manter as peças protegidas da força da máquina, evita pelos e bolinhas indesejadas, além de garantir que elas fiquem sempre bonitas. É adaptável a qualquer máquina de lavar roupas.', 31.9, 31.9, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/sg-11134201-7reok-m8xjdcz1meo096', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F23392650425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293983090', 'Desumidificador para Armários com Gancho Lavanda 180g My Closet Ordene', 'O Desumidificador para Armários com Gancho Lavanda My Closet Ordene remove o excesso de umidade que pode causar odores desagradáveis, mofos e danos aos vestuários e artigos de couro armazenador em closet e armários. Seus cristais absorvem o excesso de umidade do ambiente, depositando-o em forma líquida em sua bolsa de armazenamento. Possui fragrância lavanda e absorve até 400ml de umidade, variando conforme a umidade do local. Durabilidade de até 30 dias. Medidas: 29,5 x 16 cm (A x L)', 29.9, 26.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rff0-m9hp7knmzqj96f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22293983090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594531011', 'Módulo De Vidro Eletrico Swift S-cross Vitara Tury Pro4.88fu', 'Há 50 anos atuando no mercado automotivo oferecendo qualidade, inovação e garantia da satisfação total dos nossos clientes. - Produtos novos e lacrados a pronta entrega; - Produtos originais e de qualidade com garantia de fábrica; - Atendimento personalizado. _______________________________________________________________________ MÓDULO DE AUTOMAÇÃO VIDRO ELETRICO SUZUKI SWIFT, SUZUKI S-CROSS, SUZUKI VITARA - TURY PRO 4.88 FU COMPATIBILIDADE: - Suzuki Swift - A partir de 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023 até 2024 Vidros elétricos nas 4 portas, com função de descida e subida com um toque no botão somente no vidro do motorista. Números de fios fora do conector original: 2 Suzuki S-Cross - A partir de 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023 até 2024 Vidros elétricos nas 4 portas, com função de descida e subida com um toque no botão somente no vidro do motorista. Números de fios fora do conector original: 2 - Suzuki Vitara - A partir de 2017, 2018, 2019, 2020, 2021, 2022, 2023 até 2024 Vidros elétricos nas 4 portas, com função de descida e subida com um toque no botão somente no vidro do motorista. Números de fios fora do conector original: 2 O Módulo de Vidro PRO 4.88 FU é a solução ideal para quem busca mais conforto, segurança e praticidade no dia a dia ao utilizar os vidros elétricos do veículo. Desenvolvido com tecnologia avançada e conectores originais, o módulo facilita a instalação e preserva a originalidade do sistema elétrico do carro. Com ele, é possível realizar o fechamento e abertura simultânea dos 4 vidros elétricos através do controle remoto original do veículo, oferecendo comodidade em cada uso. Pensando na segurança, o Módulo PRO 4.88FU conta com proteção antiesmagamento, atendendo à Resolução CONTRAN 468/13 e ao Código de Trânsito Brasileiro, PRINCIPAIS CARACTERÍSTICAS: - Possui conectores originais para facilitar a instalação e preservar a originalidade do veículo. - Fechamento e abertura dos 4 vidros elétricos simultaneamente através do controle remoto original do seu veículo. - Torna todos os botões de vidros no padrão one-touch para comandos de abertura e fechamento. - Garante funcionamento temporizado dos botões da porta do motorista por 1 minuto após desligar o automóvel. - Garante a proteção contra esmagamentos exigida pela Resolução CONTRAN 468/13 e pelo Código de Trânsito Brasileiro - Sistema auto-adaptativo que gerencia o envelhecimento e desgaste dos componentes originais dos vidros elétricos, sem afetar o desempenho do produto. - Não é necessário reprogramar o módulo em casos de pane elétrica ou troca de bateria do veículo. - Realiza o fechamento por controle remoto, mesmo com botão de bloqueio dos vidros dos passageiros ativado. - Proteção contra fechamentos indesejados dos vidros ao ativar o botão interno de trava das portas. - Proteção pelos botões: Durante a subida do vidro, se um obstáculo for encontrado o vidro irá retroceder aproximadamente 50% do tamanho total da janela. - Proteção por alarmes: Durante a subida dos vidros, se um dos vidros encontrar um obstáculo o vidro abrirá totalmente e iniciará uma nova tentativa de fechamento por 4 vezes. - Reposicionamento: Ao realizar 10 comandos de subida ou descida no mesmo vidro elétrico, sem atingir o fim de curso, a função de subida one-touch deste vidro será desativada. - Oferece Conforto, Praticidade e Segurança ao Acionar os Vidros Elétricos INFORMAÇÕES TÉCNICAS: - Tensão: 10V a 16V - Consumo Stand By: 1,3mA - Fusível de proteção: 30A. CONTEÚDO DA EMBALAGEM: - 1 Modulo De Vidro - 1 Chicote Principal - Manual de instruções - Certificado de garantia - Embalagem Individual ATENÇÃO: - Garantia de 2 anos. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. - Imagens meramente ilustrativas', 511.58, 511.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Glass', 'https://cf.shopee.com.br/file/sg-11134201-81ztl-miu5mntzydj619', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432778585%2F22594531011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499881700', 'Par 2 Borrachas Vidros Canaletas Dianteira Corolla Xei 2005', 'Modelos Compatíveis: TOYOTA COROLLA 2003 A 2008 / FIELDER 2004 A 2008 Conteúdo da embalagem: O VALOR É REFERENTE AO PAR. 2 BORRACHAS CANALETAS DIANTEIRAS LADO DIREITO E LADO ESQUERDO Informações Técnicas: BORRACHAS NA COR PRETA - PRODUTO NOVO - PEÇA DE REPOSIÇÃO - FIXADO POR ENCAIXE Tempo de Garantia: 3 Meses Observação: Para que não haja problemas, recomendamos que a instalação seja feita por um profissional.', 296.99, 296.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Glass', 'https://cf.shopee.com.br/file/br-11134275-81z1k-meg1v99hiltsd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177934907%2F21499881700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092948408', 'Bacia Plástica Transparente 15,7L Oba Sanremo', 'A Bacia Plástica Transparente 15,7L Oba Sanremo é uma das opções de bacias da Sanremo para complementar o seu conjunto de equipamentos de limpeza para casa. Com relevo no fundo em forma de ondas, que impede o acúmulo do sabão em pó, ela possui um design moderno e funcional. Medidas: 15,4 x 52,5 x 48 cm (A x L x C)', 39.9, 39.9, NULL, 'Home & Living > Home Care Supplies > Basins, Buckets & Water Dippers', 'https://cf.shopee.com.br/file/sg-11134201-7rfhb-m94wtykg5bxe83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22092948408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
