INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199155254', 'Luminária Lustre Pendente Led Água Viva Dourado Luz Quente 110V-220V Bivolt', '💡 Luminária Pendente LED Água Viva Dourado | Luz Quente | 17cm | Cabo 2m | Bivolt 110V-220V Transforme seu ambiente com um toque de luxo e modernidade! A Luminária Pendente LED Água Viva Dourado combina design artístico e iluminação aconchegante, criando um visual sofisticado e elegante para qualquer espaço. Seu formato inspirado em uma água-viva, com acabamento metálico dourado e luz quente suave, traz um charme único e acolhedor. ✨ Destaques do Produto 💎 Design Exclusivo: Inspirado na forma fluida da água-viva, ideal para ambientes modernos e refinados. 💡 Luz Quente (3000K): Iluminação suave e agradável, perfeita para criar uma atmosfera relaxante. ⚡ Bivolt Automático (110V - 220V): Compatível com qualquer instalação elétrica. 📏 Cabo Ajustável de 2 metros: Permite adaptar a altura conforme o local de instalação. 🪄 Fácil Instalação: Pode ser instalada em tetos de gesso, madeira ou laje. 🏠 Versátil: Ideal para salas, quartos, cozinhas, halls e ambientes comerciais. ⚙️ Especificações Técnicas Modelo: Água Viva Cor: Dourado Diâmetro do Corpo: 17 cm Altura do Pendente: 2 m (ajustável) Material: Metal de alta qualidade Cor da Luz: Branco Quente (3000K) Tensão: Bivolt Automático (110V - 220V) Tipo de Instalação: Pendente de teto Ambiente: Interno 🏡 Ambientes Indicados ✅ Sala de estar e jantar ✅ Quarto e cabeceira ✅ Cozinha e bancada ✅ Escritório e recepção ✅ Cafeterias, restaurantes e espaços decorativos 🌟 Estilo e iluminação em perfeita harmonia! A Luminária Água Viva Dourada é o detalhe que transforma seu ambiente em um espaço moderno, sofisticado e acolhedor.', 120.0, 89.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mgcewknr49hldb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F22199155254', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22895793333', 'KIT 02 ESPUMANTES CHANDON RICHE DEMI SEC 750ML', 'De Garibaldi, na tradicional região da Serra Gaúcha, em altitudes entre 300 a 400m, vêm as uvas que compõem a Chandon Réserve Brut.A região é de clima ameno, dias não muito quentes e noites frescas, solos bem drenados, capazes de eliminar rapidamente os excessos de águas da chuvas. Estas condições permitem obter uvas de alta qualidade, sãs, maduras, apresentando bons teores de acidez natural com aromas delicados.Características olfativas: frutas tropicais com um toque de manga, figo seco, mel e baunilha;Características visuais: Cor verde amarelo dourado, borbulhas finas e ativas com espuma abundante;Características gustativas: Paladar aveludado, com bom frescor, excelente cremosidade e ótima harmonia entre acidez e doçura;Uva: Riesling Itálico 70%, Chardonnay 15%, Pinot Noir 15%.', 239.8, 239.8, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7qvg8-lh59zgsoms8488', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F22895793333', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
