INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22321732422', 'Jogo Brocas Aço Rápido 10 Unidades 5,5mm Para Metal Plástico E Madeira', 'COMERCIAL VIPASA DISTRIBUIDORA Broca Aço Rápido =========================== Medida: 5,5mm =========================== Quantidade: 10 peças A broca de aço rápido de 10 unidades com diâmetro de 5,5mm da MTX é uma ferramenta projetada para perfurar materiais diversos com precisão e eficiência. Material de Construção: Fabricada em aço rápido de alta qualidade, essa broca é resistente e durável, permitindo perfurar uma variedade de materiais, incluindo metal, madeira, plástico e cerâmica. Diâmetro: Com um diâmetro de 5,5mm, essa broca é ideal para perfurações de tamanho médio a grande, oferecendo versatilidade para uma variedade de projetos que exigem furos de dimensões consideráveis. Versatilidade: A broca de aço rápido é uma escolha versátil para uma ampla gama de aplicações, desde trabalhos de precisão em modelagem e artesanato até tarefas de manutenção em eletrônicos, joalheria e outros projetos que requerem perfurações de tamanho médio a grande. Quantidade: A embalagem contém 10 unidades da broca de 5,5mm, o que oferece conveniência para substituição e uso contínuo em múltiplos projetos. Compatibilidade: Projetada para ser usada em brocas manuais ou elétricas, essa broca é compatível com a maioria dos mandris de broca padrão, garantindo facilidade de uso e compatibilidade com uma variedade de equipamentos. Precisão: Graças ao seu design e fabricação de alta qualidade, essa broca oferece precisão e controle durante o processo de perfuração, resultando em furos limpos e precisos. Aplicações Comuns: Pode ser usada em uma variedade de aplicações, como perfuração de orifícios para passagem de parafusos, criação de furos para fixações, preparação de superfícies para soldagem, entre outros. Durabilidade: O aço rápido é conhecido por sua resistência ao desgaste e capacidade de reter o fio de corte por mais tempo, garantindo uma vida útil prolongada da broca. A broca de aço rápido de 10 unidades com diâmetro de 5,5mm da MTX é uma ferramenta versátil, durável e precisa, adequada para uma ampla gama de aplicações que exigem perfurações precisas em materiais diversos de tamanho médio a grande. COMERCIAL VIPASA DISTRIBUIDORA', 36.99, 24.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-23020-nyury0i9x4mv84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F22321732422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23822720866', 'Spot Led Direcionável 5w Avant Preto E Branco 3000K E 6500K Decoração Casa Comércio Variação', 'COMERCIAL VIPASA DISTRIBUIDORA. Spot Led Direcionável 5w Avant Preto E Branco 3000K E 6500K Decoração Casa Comércio Variação Spot Direcionável 5w Avant Preto E Branco 3000K E 6500K O Spot Supimpa é indicada para destaque em paredes, focando objetos ou texturas. Nos formatos redondo ou quadrado possui sistema direcionável para melhor ajuste do seu projeto Características Gerais do Produto: Marca: Avant Linha: Supimpa Material: Policarbonato Watts: 5W Modelos: Quadrado e Redondo Dimensões: 9cm Dimensões do corte: 7,5cm Cores: Branco e preto Luz: 3000k (luz amarela) e 6500k (luz branca). COMERCIAL VIPASA DISTRIBUIDORA.', 14.99, 14.29, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-23020-9d3nxauwsanvea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F23822720866', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592796250', 'Kit Mochila Estojo Escolar Notebook Reforçada Grande', 'Características: • Alças ajustáveis para o conforto macio para uso diário • 2 compartimentos • Bolso principal com amplo espaço interno • Bolsos laterais com telados • Alças acolchoadas e ajustáveis • Logo da marca personalizados • Zíperes personalizados e ergonômicos • Alça de mão reforçada • Mochila estampada, personalizada e original • Tipo de fecho: Zíperes Especificações Técnicas da Mochila: • Material: Poliéster 600D com estampa • Medidas (Altura x Largura x Profundidade): 41 x 30 x 16cm • Capacidade: 19 L • Peso: 0,505 Kg • Capacidade para Notebook até 15,6” Especificações técnicas do Estojo: • Estojo com 1 compartimento para Caneta, Lápis etc • Com Fecho em zíper • Material: Poliéster 600D com estampa • Medidas: (AxLxP): 20x9x3cm • Peso: 0,010 Kg • Capacidade: 9 litros Cuidados de Conservação: • Evite carregar excesso de peso • Embalar objetos com cantos vivos cortantes • Para limpeza, utilize apenas pano úmido ou esponja macia e sabão neutro. • Não expor a luz do sol para secar • Não utilizar nenhum produto químico para limpeza • Conservar em local seco e arejado • contra defeito de fabricação. Somos a Style Brand uma loja com um formato dinâmico, diversificado e democrático, visando atender o segmento de mochilas com muita qualidade e diferenciação. Com um centro de distribuição em SP, atendemos os clientes com muita rapidez e qualidade nos serviços. Além de grandes marcas originais e exclusivas, operamos com estoque pronta entrega, através de desenvolvimento, importação e comercialização direta. Produzindo nossos produtos com matéria prima de alta qualidade e tecnologia para melhor atendê-los.', 149.9, 99.9, NULL, 'Women Bags > Laptop Bags > Laptop Backpacks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqm3fc5wqyav48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F441209003%2F23592796250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19468792384', 'Kit 12 Corante Líquido Xadrez Bisnaga Para Pigmentação 50ml Diversas Cores Tecidos Parede Construção', 'COMERCIAL VIPASA DISTRIBUIDORA. Para Tingimento , Pintura Construção Civil, Roupas E Muito Mais Kit 12 Corante Líquido Xadrez Bisnaga Para Pigmentação 50ml Diversas Cores Tecidos Parede Construção ANÚNCIO DE VARIAÇÃO DE CORES E MARCAS ANÚNCIO REFERENTE A UMA CAIXA FECHADA DE CADA COR NA VARIAÇÃO DESSE ANÚNCIO VOCÊ ESCOLHE UMA COR E LEVA A CAIXA FECHADA COM 12 UNIDADES DA MESMA COR ESCOLHIDA. Descrição Do Produto Corante Liquido Alto Poder De Tingimento Chemicolor - 50ml APLICAÇÃO Indicado para tingir tintas látex, acrílica e esmalte a base de água DESCRIÇÃO Corante Liquido chemicolor é um corante liquido á base de água de fácil de homogeneizar e com alto poder de tingimento. Disponível em 10 Cores: Azul Amarelo Branco Laranja Marrom Ocre Preto Verde Vermelho Violeta Dados Técnicos Aerossol - 50ml A base de água Chemicolor A cor da tampa apenas indica a tonalidade do produto, que pode sofrer alteração quando misturado com outras tonalidades Itens Inclusos 1 - Corante liquido Chemicolor - 50ml Corante líquido Corante tipo Xadrez Bisnaga de corante Corante para tintas Corante para pintura Corante para roupas Tingimento de tecidos Corante para construção civil Pigmento líquido Tinta concentrada Corante multiuso Tingimento profissional Mistura de cores Personalização de cores Corante para alvenaria Corante para artesanato Solução colorida Corante resistente Corante fácil de usar Aditivo para tintas COMERCIAL VIPASA DISTRIBUIDORA.', 79.99, 69.99, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134201-22120-93hkk18tm5kv11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F40