INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897891932', 'Quadro Florescer da Tranquilidade 3 Telas com Moldura Para Quarta Sala', 'Quadro Florescer da Tranquilidade 3 Telas Moldura Branca Preta Madeira e Tabaco Para Quarta Sala Neste triptíco, a natureza revela sua delicadeza através de flores que desabrocham em tons suaves de azul e branco. Cada pétala, meticulosamente desenhada, reflete a harmonia e a paz que só a natureza pode proporcionar. O centro dourado das flores simboliza a luz e a esperança, irradiando uma sensação de calma e renovação. Este conjunto de painéis não é apenas uma obra de arte, mas um convite para encontrar serenidade e beleza nos pequenos detalhes do dia a dia. Material da Imagem: Papel fotográfico premium. Material da Moldura: Madeira de reflorestamento revestida em preto. Dimensões: 50cm de largura e 75cm de comprimento. 60cm de largura e 90cm de comprimento Acompanha: Suporte de serrilha Acabamento: Fita kraft. Destaques: Design atemporal, alta qualidade de imagem e moldura, certificado FSC de manejo florestal,', 270.0, 260.0, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/br-11134201-820ll-mo8lxeadfvuo80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408999524%2F22897891932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
