INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12832691510', 'Jogo de Taça de Vidro Blumenau Happy Hour 6 Peças 310ml - Ruvolo', 'ENVIO DE LOGOS SORTIDAS!! O Jogo de Taça de Vidro Blumenau Happy Hour traz 6 peças de 310ml, modelo versátil ideal para degustação de diversos estilos aromáticos de cervejas. Seu design elegante preserva a espuma e realça o brilho e a transparência da bebida, proporcionando uma experiência de degustação sofisticada e agradável para apreciadores de cerveja. Perfeitas para uso em casa, encontros com amigos, churrascos, festas ou ocasiões especiais, as Taças Blumenau Happy Hour também são muito apreciadas em bares, restaurantes e eventos, pela praticidade e estilo. Além de funcionais, são uma excelente opção de presente para familiares e amigos, tornando cada brinde ainda mais memorável e elegante. Uso: Cerveja. Material: Vidro. Capacidade: 310ml. Diâmetro: 67mm. Altura: 172mm. Conteúdo da Embalagem: 6 Peças. - Peça medida com o volume máximo até a boca - Diâmetro é medido pela largura maior da peça. - Pode sofrer variação de até 10% de seu volume. Dica de uso e preservação: • Recomendamos que a limpeza da peça seja feita a mão para evitar quebras ou danos. • Limpe a sujeira utilizando uma esponja macia, tire o resíduo de sabão e seque bem. • Não utilize abrasivos ou utensílios pontiagudos. • Evite impactos e não exponha o vidro a mudanças bruscas de temperatura pois poderá causar choque térmico e danificar seu produto. • Para realçar ainda mais o brilho da peça, limpe-a com uma flanela que não solte fiapos, levemente umedecida com álcool.', 139.99, 109.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgdv350fx1c78c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373594761%2F12832691510', NULL, NULL, '2