INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393871898', 'KIT 5 PANELAS DE INDUÇÃO COM ANTIADERENTE CERÂMICO MOU DE PITAYA - OIKOS', '"Conheça o Jogo de 5 Panelas Antiaderentes Ultra Ceramic Indução Mou Pitaya da Oikos! resistentes e modernas, são perfeitas para fazer suas receitas favoritas! elas têm antiaderente cerâmico de alto desempenho: evitam que os alimentos grudem e são livre de toxinas! as panelas são forjadas: o processo confere maior durabilidade, distribuição de calor mais uniforme e melhora na retenção de calor, permitindo que a panela aqueça rapidamente e mantenha a temperatura. as panelas têm 4mm de espessura nas bordas e 2,8mm no corpo e a frigideira tem 3,7mm de espessura na borda e 2,3mm no corpo: distribuem melhor o calor e evitam que os alimentos queimem. possuem 5 camadas: antiaderente cerâmico, camada antidesgaste interna, alumínio, camada antidesgaste externa e pintura externa. também têm uma camada extra de aço inox na base de indução! os cabos e as alças são em baquelite: resistentes a altas temperaturas - não esquentam! a tampa é reta com borda de inox: vedação aprimorada e menos desgastes nas bordas das panelas. a tampa de vidro temperado tem saída de vapor que promove mais segurança e praticidade ao visualizar os alimentos. podem ser usadas em todos os tipos de fogão: indução, gás, elétrico e vitrocerâmico. não podem ir ao forno ou em microondas! processo de cura indicado: basta aplicar uma pequena quantidade de óleo vegetal com o auxílio do papel toalha, aquecer em fogo baixo por 1 a 2 minutos e, após esfriar, é só lavar e secar! as panelas são de alumínio, baquelite, vidro e têm revestimento cerâmico. cuidados: não use objetos pontiagudos ou de metal durante o cozimento; o utensílio mais indicado é o de silicone! leve qualidade e modernidade para sua casa! o jogo contém: • 2 caçarolas: 1: diâmetro: 25cm distância entre as alças: 38cm altura:13cm litragem: 4,37L 2: diâmetro: 21cm distância entre as alças: 33cm altura:11cm litragem: 2,66L • 2 panelas: 1: diâmetro: 21cm diâmetro + cabo: 38cm altura:11cm litragem: 2,66L 2: diâmetro: 18cm diâmetro + cabo: 34cm altura: 10cm litragem: 1,36L • 1 frigideira: diâmetro: 25cm diâmetro + cabo: 43cm altura: 6cm litragem: 1,65L"', 1028.9, 499.9, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-82619-mlgmmnogx88z0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F23393871898', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28231595506', '01/04 Lapiseiras Cute Candy Colors 0,7mm Coloridas Pingente na Ponta Lapis Escrever Lapiseiras', 'Kit com 4 Lapiseiras Cute Candy Colors 0,7mm – Com Pingente na Ponta Deixe sua escrita ainda mais fofa e estilosa com o kit de 4 lapiseiras Cute Candy Colors! 🩷💜💙💛 Com cores vibrantes e um design delicado, essas lapiseiras de 0,7mm proporcionam um traço preciso e confortável para escrever, desenhar ou anotar suas ideias. ✨ Destaques do produto: ✅ Cores Candy Colors para um toque meigo e moderno. ✅ Pingente na ponta, tornando sua escrita mais divertida. ✅ Ponta 0,7mm, ideal para escrita suave e fluida. ✅ Ergonômicas e leves, perfeitas para o dia a dia. Seja para estudar, trabalhar ou simplesmente deixar seu material mais fofo, essas lapiseiras são indispensáveis! 💕✏️ ESCOLHA A QUANTIDADE NAS VARIAÇÕES: DE 1 UNIDADE E 4 UNIDADES', 15.9, 9.41, NULL, 'Stationery > Writing & Correction > Pencils', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m81w69s0nwup5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F28231595506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398161221', 'Barcos Coloridos Encaixes Torre Divertida Brinquedo Banho Bebe Brinquedos de Agua Barquinhos Encaixe', 'O brinquedo "Barcos Coloridos Encaixes Torre Divertida" é a escolha perfeita para tornar o banho do bebê mais divertido e estimulante! Com cores vibrantes e formas atraentes, ele consiste em uma torre com encaixes, onde os barquinhos podem ser empilhados e organizados de diferentes maneiras. Ideal para brincar na água, esse brinquedo ajuda a desenvolver a coordenação motora, a percepção de formas e cores e a criatividade do bebê. Além de ser super divertido, é seguro, leve e fácil de manusear, proporcionando momentos de diversão durante o banho ou na piscina. Perfeito para tornar a hora do banho mais lúdica e envolvente!', 42.9, 21.76, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5brbybcg8057e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22398161221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
