INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22724664713', 'Bermuda Shapewear Liz 54590', 'Detalhes Liz Bermuda "Best Friend" da linha Shapewear Invisible Estética Modelagem com ajuste no abdômen e culotes e costura anatômica para modelar o bumbum Tecido em super microfibra exclusiva Estética, indesmalhável, super fina, leve compacta e respirável (corte à laser) Disfarça flacidez e celulite Desaparece totalmente sob a roupa Adere perfeitamente ao corpo sem enrolar Indispensável na gaveta de toda mulher Use com: Saias, vestidos e calças justas Características: Bermuda invisible estética. Disfarça imperfeições desaparece sob a roupa. Corte a laser. Roupas sem marcas e sem transparências. Disfarça celulite e flacidez. Ajuste abdome e culotes. Modela glúteos. Microfibra compacta e refresca. Zero marcas. Indispensável a toda mulher elegante. Outros Detalhes: Use com calças, saias e vestidos. Composição: Corpo: 73% Poliamida e 27% Elastano. Forro: 100% Algodão.', 135.9, 135.9, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-23020-j7kz2c7dqknv33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946236885%2F22724664713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098208203', 'Soprador De Ar Automotivo Detail Hurricane (220v) Sigma Sgt-5606', 'DESCRIÇÃO: O SOPRADOR DETAIL HURRICANE 220V (SGT-5606) SIGMA é uma ferramenta poderosa nas mãos dos profissionais e entusiastas automotivos, ou até mesmo em outras áreas. Permite a secagem rápida de áreas de difícil acesso de forma fácil. Uma ferramenta versátil, que permite diversos usos e aplicações, entre elas: Secagem em grades, emblemas, fendas de portas, retrovisores, frisos, rodas, entre outras pequenas frestas. ESPECIFICAÇÕES TÉCNICAS: :: Marca: Sigma Tools :: Modelo: Hurricane :: Velocidade do ar: 22000 FPM :: Fluxo de ar: 90 CFM :: 2 Níveis de Velocidade :: Fácil remoção do filtro :: 1350W de Potência :: 220 Volts / 60Hz :: Cabo com 8 Metros :: Acompanha: 1 - Bico Estreiro 1 - Bico Redondo 1 - Bico Largo PESO E DIMENSÕES DA EMBALAGEM: :: Peso: 2,180 Kg :: Altura: 14,0 cm :: Largura: 27,0 cm :: Comprimento: 32,5 cm INCLUI: :: 1 (UN) SOPRADOR DETAIL HURRICANE 220V (SGT-5606) SIGMA GARANTIA: :: Garantia dada pelo fabricante de 6 meses contra defeitos de fabricação provenientes de falhas de material ou falhas oriundas do processo de fabricação do produto. Esta garantia não inclui danos causados por acidentes, mau uso, utilização de acessórios indevidos para esta ferramenta, uso em condições ambientais severas, sobrecarga, produto que não tenha sido operado de acordo com o manual de instruções de uso que o acompanha ou reparos efetuados por postos não autorizados Sigma INFORMAÇÕES DE ENTREGA: :: Todos os produtos serão enviados de acordo com a forma escolhida pelo cliente, depois da confirmação do pagamento. Produtos comprados de segunda à sexta-feira até 14h serão postados no mesmo dia. :: O prazo para a entrega varia de acordo com a forma de envio escolhida, pode ser frete expresso, Pac, Sedex ou transportadora, então fique atento as condições de entrega da sua compra. Logo após a confirmação de postagem, você receberá todas as atualizações do status do seu pedido quanto o código de rastreio, direto pela plataforma. :: E atenção, lembre-se sempre de ter alguém para receber a sua compra, no endereço informado, para evitar que essa mercadoria seja devolvida.', 684.0, 648.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meeid7s4188y2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341202873%2F22098208203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22738116702', 'Acabamento Acrílico Evolution Premium 5L Agipro', 'Agipro Evolution Acabamento Acrílico premium 2 em 1, é um impermeabilizante com perfume. Uma perfeita sinergia entre as suas resinas, proporciona ao piso brilho duradouro, filme transparente resistente ao tráfego e a lavagem, poder antiderrapante. Produto indicado para pisos frios como: ardósia, granilite, paviflex, plurigoma, cerâmica não vitrificada, mantas e pisos vinílicos em geral etc. Fragrância: Lavanda Embalagem: 01 unidade com 5L', 231.92, 231.92, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/sg-11134201-7rd6c-m7s2lrmtgiw779', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F22738116702', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209044404', 'Biscoito Recheado de Morango Trakinas', 'Trakinas é o biscoito recheado com a carinha da diversão! Com delicioso sabor de morango no recheio e massa crocante, é o lanche perfeito para as crianças saborearem. Além de ser um excelente acompanhamento para um suco ou copo de leite, Trakinas tem diversas opções de carinhas para tornar o momento do lanche mais divertido!', 3.79, 3.79, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-8260j-mj72oh8lszk500', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58209044404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
