INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49402749355', 'Caixa De Isopor Laminada De 8l Para Churrasco Salgados Doces', 'Caixa de Isopor Laminada de 8L – Conservação Térmica por Horas (alimentos quentes) ou até Dias (alimentos frios) A caixa de isopor laminada foi desenvolvida para garantir máxima eficiência no armazenamento térmico, mantendo a temperatura dos alimentos por longos períodos – de horas até dias, dependendo das condições de uso. Seu revestimento laminado proporciona maior resistência, durabilidade e higiene, além de facilitar a limpeza. Ideal para armazenar e transportar diferentes tipos de alimentos, como: • Prontos para consumo: espetos de churrasco, salgados, frios e lanches; • Congelados e resfriados: peixes, camarão, lagosta, frutos do mar e outros alimentos que exigem conservação. Perfeita para uso em eventos, delivery, comércio de alimentos e transporte de produtos sensíveis à temperatura. Garantia do vendedor: 7 dias', 39.99, 39.99, NULL, 'Home & Living > Hand Warmers, Hot Water Bags & Ice Bags', 'https://cf.shopee.com.br/file/sg-11134201-820mo-mnu5yde3b1ms10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F374241455%2F49402749355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
