INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18774315139', 'Boia Inflável Pequeno Golfinho - Intex 58535', 'A criançada vai amar brincar na piscina com o Bote Golfinho Inflável Pequeno. Além de confortável, ele possui alças resistentes para segurar, oferendo mais segurança na hora da brincadeira. Especificações: Código: 58535 Dimensões: 1.75m x 66cm. Fabricado em vinil resistente com 0.25mm de espessura. Suporta até 40Kg. Possui 2 alças resistentes. Recomendado para crianças a partir dos 3 anos. Garantia de 90 dias.', 107.99, 107.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m40h4hjwx8w11f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F18774315139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259546177', 'Kit Creme para Pentear + Gelatina + Óleo de Tratamento Xêrosa Baunilha Doce', 'O Kit Xêrosa Baunilha Doce garante cachos definidos, macios e com brilho radiante. Com Creme para Pentear 800g, Gelatina 500g e Óleo de Tratamento 60ml, entrega nutrição, alinhamento e controle do frizz. Perfume oriental intenso. INDICAÇÕES Para quais tipos de cabelo? Para todos os tipos de cabelo. Qual a indicação? Para cabelos desnutridos, sem definição e com frizz. Pode usar a partir de quantos anos? A partir de 12 anos. ATIVOS Quais os principais ativos? Notas da Fragrância: Saída: limão siciliano, laranja e maçã Corpo: jasmim transparente e lírio do vale Fundo: baunilha, praliné, musk, sândalo e cedro <>MODO DE USO$& Qual a melhor forma de usar? Óleo de Tratamento Xêrosa Baunilha Doce Com o cabelo seco ou úmido, aplique algumas gotas do óleo de tratamento na palma das mãos e espalhe bem do comprimento às pontas. Finalize como preferir. Sem enxágue. Creme para Pentear Xêrosa Baunilha Doce 800g e Gelatina Xêrosa Baunilha Doce Com os cabelos limpos e úmidos, aplique o produto mecha a mecha, uniformemente, no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. É indicado o uso de até 30g para finalização, penteados e baby hair. A quantidade pode variar de acordo com o comprimento e o volume do cabelo. Não enxágue. CARACTERÍSTICAS É produto vegano? O Kit Xêrosa Baunilha Doce é vegano. É liberado? O Kit Xêrosa Baunilha Doce não é liberado.', 97.0, 87.81, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820lh-mng800d8t0jl81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F58259546177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
