INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18450065443', 'Tenis Infantil Menina Feminino De Menina Club Happy', 'Ficha técnica Material: sintético. Peso: 300 g (pode variar de acordo com o tamanho). Solado: emborrachado flexível. Palmilha: EVA macio. Embalagem: cada par apresenta uma caixa individual. Como tirar as medidas Identificar o tamanho ideal para um calçado é simples. Posicione o pé sobre um papel e passe o lápis ao redor dele, desenhando o contorno. Com uma régua, meça o tamanho do dedão até o calcanhar. Para garantir conforto, acrescente 0,5 cm no total. Tamanho da palmilha (em centímetros) 24 – 16,0 cm 25 – 16,5 cm 26 – 17,2 cm 27 – 17,8 cm 28 – 19,0 cm 29 – 19,6 cm 30 – 20,3 cm 31 – 21,0 cm 32 – 21,5 cm 33 – 22,3 cm 34 – 22,8 cm', 149.9, 72.2, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me4c3q7a2mf63e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F499950777%2F18450065443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997588105', 'Cama Box Casal Preto + Colchão Molas Ensacadas Zidi Alabama 138x188x61cm', 'A Cama Box + Colchão Molas Ensacadas Zidi Alabama oferece conforto, estabilidade e durabilidade em um conjunto completo. O colchão possui molas ensacadas que reduzem movimentos, Pillow Flat com maciez equilibrada, bordado matelassê e revestimento em poliéster resistente e fácil de higienizar, com tratamento antialérgico e sistema No Turn. A base em EPS garante suporte firme, enquanto o sistema Polyframe com espuma D26 reforça as bordas. A base box em madeira de eucalipto é resistente, com revestimento em poliéster, pés reforçados e superfície antiderrapante. Suporta até 120 kg por pessoa e oferece conforto intermediário, ideal para quem busca cama box com colchão de molas ensacadas confortável e durável. Características do Colchão: Polyframe: Sistema utilizado nos colchões de molas, composto por um quadro que envolve com borda de espuma de alto suporte (D26) em toda a lateral do colchão. Suporta até 120 kg por pessoa Conforto intermediário Produto aprovado pelo INMETRO, conforme padrões de qualidade para exportação Garantia de 1 ano pelo fabricante Características da Cama Box: Estrutura em madeira de eucalipto de reflorestamento Revestimento externo em tecido poliéster Pés em plástico com 12 cm de altura Tratamento antiácaro e antialérgico Tecido superior com superfície antiderrapante Suporta até 120 kg por pessoa Necessita montagem dos pés Garantia de 1 ano pelo fabricante Dimensões do Colchão: Altura: 24cm Largura: 138cm Profundidade: 188cm Peso: 20,200kg Dimensões Cama Box: Altura com os pés: 37cm Largura: 138cm Profundidade: 188cm Peso: 21,350kg Observações Importantes: Produto não acompanha acessórios decorativos. Imagens meramente ilustrativas. As cores do produto podem sofrer pequenas variações conforme o monitor ou tela de visualização. Em caso de devolução, o item deve ser devolvido na embalagem e sem sinais de uso. Não será feita a entrega em áreas consideradas de risco ou zonas rurais. A entrega é realizada por transportadora. Não realizamos subida por escadas ou elevadores. Não inclui serviço de montagem.', 2309.9, 1319.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-8260n-mlqqv7jego3m33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1087752745%2F23997588105', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12348558354', 'Fita Kinésio Muscle Fix 5x500cm Rolo Azul Multi Saúde - HC042', 'Fita Kinésio Muscle Fix 5x500cm Rolo Azul Multi Saúde - HC042 A fita Kinésio Muscle Fix da linha Multi Saúde melhora a sua circulação durante a prática das atividades físicas, garantindo suporte aos músculos, articulações, tendões e ligamentos, e promovendo estabilidade e amplitude aos movimentos! A Muscle Fix proporciona conforto e flexibilidade, ajuda a evitar lesões, minimiza a fadiga muscular e pode ser usada em diversas regiões como ombros, coxas, joelhos, pernas, pulsos e em outras áreas do corpo. Hipoalergênica: não causa irritações na pele; Resistente à água e suor, e não descola com facilidade da pele; Rolo de 5cm x 500cm; Cor: Azul Resistente à água e não descola devido ao suor; Composição: 93% algodão e 7% elastano. 12 meses de garantia *Imagens Meramente Ilustrativas.', 30.69, 30.69, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Mouthguards & Sport Tapes', 'https://cf.shopee.com.br/file/ca9abc3144e4ca589d29f6de3f41ddb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F12348558354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
