INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897269749', 'Caixa Organizadora São Bernardo Container em Plástico Preto 70L', 'A Caixa Organizadora São Bernardo Container em Plástico Preto 70L é um item prático e funcional que pode ajudar a manter sua casa ou escritório organizado. Com capacidade para 70 litros, ela é ideal para guardar diversos objetos, desde roupas e acessórios, até materiais de escritório, brinquedos e muito mais. Feita em plástico resistente, a caixa organizadora possui um design moderno e elegante e tampa com detalhes em alto relevo que dão um toque elegante. Além disso, a sua cor preta combina com qualquer decoração. A tampa da caixa possui travas nas laterais, o que garante que o conteúdo armazenado fique protegido da poeira e da umidade. Ela possui alças laterais que facilitam o transporte da caixa, permitindo que você a leve para onde precisar com facilidade.Uma das vantagens da Caixa Organizadora São Bernardo Rattan em Plástico Preta 70L é a sua versatilidade. Ela pode ser usada em diversos ambientes, como quartos, closets e escritórios. Além disso, ela pode ser empilhada com outras caixas organizadas da mesma linha, economizando espaço e otimizando o armazenamento.', 83.99, 83.99, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-825b6-mqyxqfmtedcce9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23897269749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
