INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497467616', 'Filtro Combustível Fiat Uno 1984 a 1993 - 161695 - FCC225', 'Filtro Combustível Fiat Uno 1984 a 1993 161695 FCC225 MOTOR 1.0/1.3/1.5/1.6 ÁLC/GAS (GRANDE BICO 6/8mm) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 18.7, 18.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822xw-mo9r8x93liioc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22497467616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199896072', 'Kit Sintra Fast Limpador + Intense Renovador De Plásticos Vonixx Com Pano e Aplicador', '🚗 Kit Sintra Fast Vonixx 500ml + Intense 240ml + Aplicador Zacs Roxo + Pano Microfibra 28x28cm 🧴 Sintra Fast Vonixx 500ml 🔹 Multilimpador flotador universal. 🦠 Ação bactericida e fungicida, eliminando microrganismos. ⚖️ pH balanceado, seguro para várias superfícies internas. 💺 Indicado para painéis, portas, couro sintético, carpetes, tecidos e plásticos. ✨ Alto poder de remoção de gordura e sujeira difícil. 🌬️ Diminui maus odores e torna o interior mais saudável. 🧴 Intense Vonixx 240ml 🔹 Renovador de plásticos internos com proteção UV. 🎨 Recupera a cor original e renova o aspecto. 🌟 Acabamento acetinado natural e toque seco (não pegajoso). 🛡️ Proteção contra ressecamento e desbotamento por até 6 meses. 🟣 Aplicador de Espuma Zacs Roxo 🖐️ Formato ergonômico, fácil de usar. 🧽 Ideal para espalhar líquidos ou pastosos uniformemente. ✔️ Macio, não risca nem danifica superfícies. 🧼 Pano de Microfibra 28x28cm – 220gsm (cor sortida) 💧 Alta capacidade de absorção. 🧹 Remove resíduos e garante acabamento perfeito. 🪶 Macio, não solta fiapos e não risca. 📌 Aplicações do Kit ✅ Sintra Fast: Painéis (frontal e laterais) Cantos de portas e consoles Carpetes, tecidos, couro e estofados Emborrachados, vinil e plásticos internos ✅ Intense: Painéis ressecados ou desbotados Acabamentos de portas Molduras e colunas plásticas Plásticos lisos ou texturizados ⚙️ Modo de Uso 🔹 Sintra Fast Pulverize diretamente na superfície. Esfregue com pincel, escova macia ou aplicador. Remova o excesso com pano úmido e finalize com pano seco. 🔹 Intense Certifique-se que a superfície esteja limpa e seca. Aplique pequena quantidade com aplicador. Espalhe de forma uniforme até preencher a peça. Se houver excesso, remova com toalha de microfibra limpa. 📦 Informações Técnicas Marca: Vonixx Condição: Novo Sintra Fast: 500ml – líquido verde – densidade 1,00 a 1,02 g/cm³ Intense: 240ml – pronto uso – proteção até 6 meses Aplicador de Espuma: Roxo, formato ergonômico Pano de Microfibra: 28x28cm – 220gsm – cor sortida 🛒 Onde Comprar Adquira agora o Kit Sintra Fast Vonixx em uma de nossas Lojas Oficiais: 👉 Camillo Parts | Genuine Automotive | Edumac Parts E tenha a certeza de comprar um produto original, de alta qualidade, com garantia e suporte especializado. ⚠️ Aviso Legal O uso, cópia ou alteração de fotos, imagens e conteúdo deste anúncio é proibido. Lei 9.610/98 – Direitos Autorais.', 85.7, 75.42, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-7rdyd-mdm2w5tuinvu8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349667948%2F18199896072', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198025080', 'Bobina Ignição Vw Gol 1988 a 1995 - 106739 - 40077', 'Bobina Ignição Vw Gol 1988 a 1995 106739 40077 GTI TODOS (IGNIÇÃO ELETRÔNICA - COM PINO - VERMELHA) (Cilíndrica) A função da bobina de ignição é transformar a tensão do sistema de alimentação do veículo, que normalmente varia de 12 a 14V em alta tensão. Esta alta tensão pode chegar a 45.000V. A alta tensão da bobina é conduzida pelos cabos de ignição até as velas, onde é convertida em uma centelha que dará início à reação de queima de combustível. NUNCA toque na Bobina de Ignição durante o funcionamento do veículo, pois há risco de choque. (CONFIRMAR O CODIGO ORIGINAL DA BOBINA ANTES DE COMPRAR)', 176.53, 176.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbl2-lmtebreftqdsc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22198025080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492532961', 'Válvula Solenóide Nissan March 2011 a 2015 - 510008 - 2011', 'Válvula Solenóide Nissan March 2011 a 2015 510008 2011 Motor 1.0 16v Flex - (2 Vias) Problemas mais comuns no sistema de partida a frio Estão relacionados ao combustível ruim. A utilização de um combustível de baixa qualidade faz com que as vias de passagem da solenoide venham a entupir e não permitir a passagem do combustível. Outro problema no sistema pode ser a falta do uso. O combustível resseca os locais de passagem, fazendo com que a falta de lubrificação venha a tornar o material mais frágil, pois algumas partes do sistema são feitas de plástico.', 76.59, 76.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbn3-lmt6f2i3vwls12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492532961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993011170', 'Reparo Molas Sapata Vw Parati 1986 a 1994 - 203187 - 1008', 'Reparo Molas Sapata Vw Parati 1986 a 1994 203187 1008 1.3/1.6 - (1 RODA - TRASEIRA) (PARCIAL) Função: É responsável pelo retorno das sapatas após a frenagem._x000D_ Aplicação: Normalmente nas rodas traseiras. Mas pode ser aplicado nas rodas dianteiras em modelos com freio a tambor dianteiro._x000D_ Funcionamento: Trabalha exercendo força contrária ao cilindro de roda. Também é responsável pela fixação e alinhamento das sapatas no espelho._x000D_ Características: Molas fabricadas em aço com alto teor de carbono (SAE 1070)', 17.13, 17.13, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd62-lur4rh94yzoxc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23993011170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997463341', 'Guarnição Bomba Gm Corsa 2009 a 2012 - 512401 - 1456', 'Guarnição Bomba Gm Corsa 2009 a 2012 512401 1456 Motor 1.4 8v Flex - (Ø Interno - 143 mm) (Altura - 16,5 mm) A guarnição da flange é uma espécie de borracha de vedação que é responsável por fazer o selamento na montagem do módulo de combustível no tanque. Essa guarnição impede que o combustível vaze do tanque e também não permite a entrada de impurezas', 27.22, 27.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rd58-lufizjtb3mh9f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22997463341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
