INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598079633', 'Reparo Pinça Fiat Tipo 1993 a 1995 - 115150 - C1537', 'Reparo Pinça Fiat Tipo 1993 a 1995 115150 C1537 TRASEIRA 34mm O cilindro da pinça é protegido por uma capa de borracha chamada coifa, ou contra-pó, que impede a entrada de partículas para dentro do cilindro, o que acarretaria no seu riscamento, podendo até perder parte da pressão de frenagem.', 66.86, 66.86, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-lwgcwnmm53scc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23598079633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593006955', 'O AMULETO PERDIDO E OUTRAS LENDAS AFRICANAS', 'O AMULETO PERDIDO E OUTRAS LENDAS AFRICANAS Saiba como a sabedoria se espalhou pelo mundo e como a lebre ficou com o lábio partido. Emocione se com a história de Ntagi, que perdeu seu precioso amuleto no fundo do mar, com o caso do jovem que queria se casar com a filha do Senhor da Chuva e com as proezas da encantadora Ten para conquistar o reino de Samanyana Basi.Esta inédita coletânea apresenta 39 contos populares de diversas tradições africanas, desde as planícies agrestes do Sudão até uma pequena aldeia em Camarões. Histórias que retratam a cultura e a sabedoria desses povos.. Informações Adicionais Autor: SACRANIE, MAGDALENE Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: O AMULETO PERDIDO E OUTRAS LENDAS AFRICANAS Idioma: INDEFINIDO Páginas: 96 Edição: 2 ISBN-13: 9786556971551 ISBN-10: 6556971553', 65.9, 65.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd58-luv6otoa4yrqd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23593006955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
