INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997627458', 'Cooktop de Indução 4 Bocas Dako Supreme Preto 220v', 'Cooktop de Indução 4 Bocas Preto com Trava de Segurança Dako Supreme 220V: cozinha segura e sem segredo. O Cooktop de Indução Supreme foi desenvolvido para os apaixonados por modernidade e tecnologia que não abrem mão de segurança e praticidade quando o assunto é cozinhar. Seu design minimalista impressiona! Com o seu indicador de calor residual, o detector de panela e a trava de segurança no painel touch você tem a combinação perfeita de segurança, garantindo que o produto não seja acionado incorretamente ou alterado, assegurando também o cuidado com as crianças. Mais rápido que cozinhar com a função turbo na nona potência, será a sua limpeza. Sem que seja necessário esfregar, a mesa ultra resistente ficará sempre brilhante. Não basta qualquer Cooktop. Tem que ser Cooktop Supreme! A versão possui 4 zonas de cocção com 1,5 kW e até 9 níveis de potência por zona, sendo turbo nas zonas dianteira esquerda e na traseira direta, chegando até 2 kW. Características Marca: Dako Linha: Supreme Ref.: 400000350 Voltagem: 220V Cor: Preto Potência total: 7000W Quantidade de Bocas: 4 bocas Tipo de Acendimento: Indução Acabamento da Mesa: Vitrocerâmico Funcionamento: Indução Trempes: Não possui Botões Removíveis: Não Comprimento do Cabo de Energia: 96 cm Fabricação: Importado Eficiência Energética: A Conversão de Gás: Não se aplica a esse produto Serviço de Instalação: Não realizamos. Potência dos Queimadores: 4 zonas de 1,5 kW, sendo 2 zonas com turbo para 2 kW Dimensões Aproximadas do Produto (LxAxP): 59 cm x 6 cm x 52 cm Dimensões Aproximadas do Nicho (LxAxP): 56 cm x 20 cm x 49 cm Peso Aproximado: 11kg Importante: Imprescindível à conferência no ato da entrega. Em caso de anormalidade, recuse o recebimento. Imagens meramente ilustrativas. Todas as informações divulgadas são de responsabilidade do fabricante, podendo sofrer alterações sem nenhum aviso prévio. Garantia de 12 meses contra defeitos de fabricação, de acordo com as normas do fabricante.', 2082.9, 1469.9, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7rdxw-lzfd9o3g4l52a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F554629856%2F23997627458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097418537', 'Camara de Ar para Carrinho de Mão/carga/transporte 3.00X08 Metalosa', 'CAMARA DE AR PARA CARRINHO DE MÃO/CARGA/TRANSPORTE 3.00X08 METALOSA Câmara de Ar para Carrinho de Mão METALOSA Indicado para carrinhos de mão, carrinhos de carga, de transporte, entre outros. Submeter a pressão máxima recomendada, somente após instalado com o pneu no aro. Especificações: - Material: Borracha - Cor: Preto - Dimensões: 34x34x10 cm - Marca: Metalosa - Peso: 300 g Conteúdo da embalagem: 01 Câmara de Ar para Carrinho de Mão *Garantia: 03 meses contra defeitos de fabricação. *Imagens Meramente Ilustrativas. *Objetos de decoração das fotos não estão inclusos. *As cores podem variar conforme monitor/smartphone utilizado para a visualização do anúncio.', 22.25, 22.25, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rceb-lt0zbrmkkxfya9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984366979%2F22097418537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097281853', 'Correia Poly V Ar Condicionado PAJERO TR4 2001 a 2014 - 15954 - 5PK1345', 'Correia Poly V Ar Condicionado PAJERO TR4 2001 a 2014 Produto novo, com garantia e Nota Fiscal!_x000D_ _x000D_ Correia Poly V - 5PK1345_x000D_ PAJERO TR4 - 2.0 16V_x000D_ Anos: 01 02 03 04 05 06 07 08 09 10 11 12 13 14 _x000D_ Utilização: Direção Hidráulica / Ar Condicionado As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 104.12, 104.12, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl9-lmxjtox8v0rt65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22097281853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899446811', 'Fralda Luxo Cremer Estampa Patrulha Canina Com 05 Unidades', 'Fralda Luxo Cremer Estampa Patrulha Canina Com 05 Unidades Fralda Cremer linha Luxo Patrulha Canina mini com 05 peças, confeccionado em algodão com toque macio. Modelo com bainha e estampa. Informações Adicionais:Tamanho: Único Cores: Colorido Composição: Algodão Referência: 646016 12 Dimensão: 70cm x 68cm Detalhes Adicionais: Com bainha Marca: Cremer Dica de Estilo: Ótima absorção e conforto são peças fundamentais na hora de limpar o pequeno.', 91.99, 91.99, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-m0d4il3pg804c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F20899446811', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798394560', 'Lixeira Monte Líbano Rattan Bebê E Mamãe 6 Litros Rosa', 'Lixeira Monte Libano Rattan 6 Litros A Lixeira Monte Líbano, com capacidade de 6 litros, é uma opção elegante e funcional para o descarte de resíduos no ambiente doméstico. O design em rattan adiciona um toque de sofisticação à lixeira, tornando-a uma peça que se integra bem à decoração. Equipada com tampa e pedal, essa lixeira proporciona praticidade e higiene, permitindo que o descarte seja feito de forma fácil e sem a necessidade de tocar na tampa. A capacidade de 6 litros é ideal para o uso em ambientes menores, como banheiros, escritórios ou quartos. Informações Adicionais:Tamanho: Único Cores: Rosa Referência: BM2064 Medidas aproximadas: 22cm x 20cm x 27cm Marca: Monte Líbano', 34.9, 34.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-7renx-m8l0uv8uc3oice', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23798394560', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993967168', 'Kit Cueiro Papi Karinho Flanelado Liso Azul – 3 Peças 80cm x 50cm', 'Kit Cueiro Papi Karinho Flanelado Liso Azul – 3 Peças 80cm x 50cm O Kit Cueiro Papi Karinho é um item essencial no enxoval do bebê, oferecendo conforto, praticidade e proteção nos momentos do dia a dia. Confeccionado em flanela 100% algodão, possui toque macio e delicado, ideal para a pele sensível do recém-nascido. Com tamanho de 80cm x 50cm, os cueiros são perfeitos para forrar superfícies, proteger no colo, carrinho, bebê conforto ou para cobrir o bebê com leveza. Um produto prático, fácil de lavar e indispensável para a rotina de cuidados com o bebê. O kit contém: 03 cueiros flanelados lisos na cor azul Tamanho individual: 80cm x 50cm Tecido: Flanela 100% algodão Características do Produto: Toque suave e agradável Alta absorção e respirabilidade Fácil de dobrar e transportar Pode ser usado como forro, manta leve ou protetor Produto com a qualidade da marca Papi Baby Ideal para: Recém-nascidos e bebês nos primeiros meses Montar o enxoval com conforto e estilo Presentear em chás de bebê ou maternidade Palavras-chave para facilitar sua busca: cueiro azul bebê, kit cueiro papi karinho, cueiro flanelado algodão 80x50, cueiro 3 peças azul, cueiro pequeno recém-nascido', 22.99, 22.99, NULL, 'Mom & Baby > Nursery > Mattresses & Bedding', 'https://cf.shopee.com.br/file/sg-11134201-7rffp-m9g3e4jn2a6t9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22993967168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397467562', 'Filtro Gasolina MAVERICK 1974/1977 - 43610 - FCC225', 'Filtro Gasolina MAVERICK 1974/1977 MOTOR 4/6/8 CILINDROS ÁLC/GAS (GRANDE BICO 6/8mm) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 18.7, 18.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-822xy-mo9r0udjf8jr2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22397467562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397979379', 'Kit Bico Injetor PALIO 1997/2000 - 36815 - 1204', 'Kit Bico Injetor PALIO 1997/2000 (Weekend) - Motor 1.5 8v - (Sistema Magneti Marelli - Multipoint) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 37.99, 37.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7repe-m2f1d2flp0np09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21397979379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297751562', 'Kit Protetor Solar Sundown Praia e Piscina FPS50 200ml Gratis 120ml', 'O Protetor Solar SUNDOWN® Praia e Piscina FPS 50possui tripla proteção, ajuda a proteger a pele de elementos agressores como o sol, o cloro e a água salgada do mar. Oferece proteção imediata UVA + UVB, protegendo a pele de queimaduras solares dentro e fora d’água. É 3x mais resistente à água e ao suor e seguro para uso em toda a família. A linha Praia e Piscina está com nova embalagem com duplo dosador — para o corpo e para o rosto. Indicado para proteger o rosto e o corpo da família na exposição ao sol, até mesmo em condições extremas, como o uso na praia e na piscina ou na prática de esportes ao ar livre.', 72.79, 72.79, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdx2-lzfnas3c7fqsb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22297751562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18297681364', 'Tintura Creme Koleston 77 Marrom Dourado', 'Koleston Creme é a coloração permanente da Wella que te dá cor intensa e duradoura, graças a sua tecnologia resistente à água. Oferece perfeita cobertura dos fios brancos, além de hidratar tão intensamente quanto colore. Seu exclusivo Tratamento Gloss Intenso Ultra deixa seu cabelo com mais brilho e maciez e ajuda a manter a intensidade da cor. O kit Koleston também vem com o Reativador de cor que deposita mais pigmentos no seu cabelo para ajudar a reativar a cor depois de 15 dias. É Uma coloração fácil de aplicar em casa, até mesmo para aquelas que não possuem muita habilidade na hora de colorir os fios sozinha. O kit Koleston contém: • 1 bisnaga Wella Koleston Coloração Creme 55 g • 1 frasco aplicador Wella Koleston Emulsão Reveladora/Água Oxigenada 30 vol. 55 ml • 1 sachê Wella Koleston Reativador de Cor Tratamento com pigmentos 22 ml • 1 tubo Wella Koleston Tratamento Gloss Intenso Ultra que contém 4 aplicações 40 ml • 2 pares de luvas • 1 folheto explicativo Benefícios: -Cor intensa e duradoura - Cobertura perfeita dos fios brancos - Fácil de aplicar- Promove hidratação e nutrição - Garante brilho, maciez e um toque suave - Cria camada de proteção que impede que a água penetre no fio, para que não desbote.', 30.23, 30.23, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rd5e-lvdlpzkhfjjlff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F18297681364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41764459171', 'Kit 6 Em 1 Musculação 15kg Halteres Anilhas Barras Kettlebell Ajustáveis Academia Treino em Casa', 'Com o Conjunto de halteres multifuncional 6 em 1Com ele, você pode obter um par de halteres, também barras, kettlebells e suportes de flexão, que ajudam você a fazer muitos exercícios, incluindo supino, agachamento sumô, etc. -Materiais duráveis: O exterior das peças dos halteres é feito de materiais PE de alta qualidade, o que evita efetivamente o desgaste do piso. -Barra de halteres antiderrapante: A superfície da barra de halteres é feita de material ABS e fixada em uma textura antiderrapante, que fortalece o atrito da mão e ajuda a controlar melhor o halter durante o exercício. -Porcas de segurança: Os conjuntos contêm porcas de segurança. O espessamento da rosca da porca mantém efetivamente a peça no lugar, para evitar tremores de movimento e a queda do peso. Garantia de segurança. -O pacote contém: 4 anilhas de 2kg cada; 4 anilhas de 1,5kg cada; 2 Barras Rosqueáveis; 1 Barra Rosqueável com Proteção de EVA; 1 Base para Kettlebell; 2 Puxadores para Kettlebell (com função dupla de apoios para flexão) 5 Roscas para as Barras Rosqueáveis; Multifuncional e prático, permite que a placa seja removível, podendo assim tornar o peso ajustável sua necessidade. A melhor opção para quem busca treinos perfeitos e ajudam a melhorar a saúde cardiovascular, queimar calorias, perder peso, ganhar músculos ou aumentar a resistência muscular. - Tenha seu equipamento profissional em casa; - Super versátil, ajustável para que você consiga treinar vários tipos de movimentos; - Com este equipamento você poderá treinar vários grupos musculares. Braços, pernas, costas, bíceps, tríceps, ombro e muito mais; - Super Fácil de Utilizar; - Você consegue ajustar o peso nas barras, de acordo com a sua necessidade; - As barras rosqueáveis são super fáceis de montar e desmontar; - Cuide do seu corpo e da sua saúde com um equipamento de qualidade superior; - A sua melhor opção para levar os seus treinos para um outro nível, queimar calorias, ganhar e fortalecer seus músculos;', 500.0, 219.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-820ld-mmb91abb5v5w28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1379077822%2F41764459171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19925941459', 'Kit Com 06 Canetas Hidrográficas Finemarker 1,0mm Vários Modelos - BRW', 'ESTOJO DE CANETAS FINELINER SEXTAVADA 0,4mm NEON SOUL - BRW/ PAPELARIA Pedidos feitos até às 12:00 (MEIO DIA) são despachados no mesmo dia!!! DESCRIÇÃO • Modelos: Neon, Pastel, Básico e Vintage • Cores Neon: roxo, rosa, laranja, amarelo, verde e azul • Cores Pastel: roxo, rosa, laranja, amarelo, verde e azul. • Cores Vintage: vermelho, marrom, turquesa, cinza, verde e azul • Cores Básicas: azul, preto, vermelho, verde, rosa e amarelo • Ponta Média: 1,0mm • Corpo: sextavado • Quantidade: blister com 6 canetas As Canetas Hidrográficas tem um modelo super moderno e ergonômico, possuem formato anatômico dando mais conforto e firmeza no uso. Sua ponta média proporciona a capacidade de fazer traços macios e com mais precisão. Personalize suas anotações do dia a dia, é ideal para estudar, organizar e decorar!', 18.0, 14.96, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-7qvdc-lhgrjafflw6h35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F721033344%2F19925941459', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4886347521', 'Borracha De Porta Tipo Original Duster 2013 2014 2015 2016', 'Detalhes do Produto: Borracha De Porta Tipo Original Logan e Sandero 2007 Até 2014 e Duster 2011 Até 2016 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Duster 2011 2012 2013 2014 2015 2016 Logan 2007 2008 2009 2010 2011 2012 2013 2014 Sandero 2007 2008 2009 2010 2011 2012 2013 2014 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor unitário (serve para todas portas) Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 01 Borracha de porta (02 anos de garantia)', 81.9, 81.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/0410d1d43002a71dd009e961e7e7297f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F4886347521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
