INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51711950653', 'Cavalete Central CG 160 Titan Fan Start 160 2016 a 2026 Kit Completo Com Mola Pino e Trava', 'KIT CAVALETE CENTRAL COMPATÍVEL COM HONDA CG 160 TITAN / FAN / START 2016 A 2026 Mais estabilidade, praticidade e segurança para o dia a dia da sua motocicleta. O Cavalete Central é fabricado em aço reforçado e desenvolvido para proporcionar apoio firme e seguro ao estacionar. Além disso, facilita a limpeza da moto, manutenção preventiva e lubrificação da corrente, tornando o uso diário muito mais prático. BENEFÍCIOS ✔ Mais estabilidade ao estacionar ✔ Facilita a limpeza e manutenção ✔ Auxilia na lubrificação da corrente ✔ Estrutura reforçada de alta resistência ✔ Pintura resistente à corrosão ✔ Excelente acabamento ✔ Encaixe sob medida ✔ Instalação simples CARACTERÍSTICAS • Material: Aço reforçado • Cor: Preto • Acabamento: Pintura eletrostática • Produto novo • Alta resistência e durabilidade CONTEÚDO DA EMBALAGEM • 01 Cavalete Central • 01 Mola • 01 Meia Lua • 01 Pino • 01 Eixo COMPATIBILIDADE Honda CG Titan 160 (2016 a 2026) Honda CG Fan 160 (2016 a 2026) Honda CG Start 160 (2016 a 2026) Produto ideal para motociclistas que buscam mais praticidade, segurança e facilidade na manutenção da moto. cavalete central cg 160, cavalete titan 160, cavalete fan 160, cavalete start 160, descanso central cg 160, kit cavalete central, cavalete completo, cavalete com mola, cavalete com pino, cavalete reforçado, suporte central moto, apoio central moto, cavalete para manutenção, cavalete para lubrificação da corrente, cavalete honda cg 160, cavalete titan fan start 160, cavalete central 2016 a 2026.', 134.99, 134.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-820mg-mp9mrd2s3lkw75', 'https://s