INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206106185', 'Pincel marca texto Boss Nature Colors Wildflower Grey Violet 70/162 Stabilo', 'O marcador de texto STABILO BOSS ORIGINAL NatureCOLORS Wildflower é uma ferramenta de escrita versátil que pode ser usada para destacar textos ou para qualquer projeto criativo. Para quem deseja trazer as cores populares do design de interiores e da moda para o mundo das canetas, o STABILO BOSS ORIGINAL NatureCOLORS Wildflower é a escolha certa. Os tons são inspirados na natureza e adicionam uma vibração sutil a qualquer tarefa, seja profissional ou criativa. Detalhes: Design clássico incomparável desde 1971 Tecnologia Anti-Dry-Out: 4 horas protegido sem secar, mesmo destampado Disponível em 30 cores diferentes (9 cores neon, 14 cores pastel, 6 NatureCOLORS e 1 marcador preto). Duas espessuras de traçado 2 a 5 mm. Ideal para grifar textos de diferentes tamanhos e desenhar linhas de diferentes espessuras Tinta com base d&#39;água Qualidade robusta. Feito para durar muito tempo Tecnologia Anti-Secagem Graças a Tecnologia Anti-Secagem da STABILO, o marcador de texto pode ficar destampado por até quatro horas sem secar a ponta Duas espessuras de linha A ponta chanfrado do STABILO BOSS ORIGINAL permite criar traços de 5 mm, ideais para marcação de texto, e traços de 2 mm, ideais para sublinhar textos. Perfeito para projetos criativos A STABILO BOSS ORIGINAL é perfeita para realizar detalhes especiais e destaques coloridos nos seus desenhos, marcações e letterings.', 25.36, 25.36, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-820n1-mnkiijf2spvq87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F58206106185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
