INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297505409', 'Grip Pro Performance - Wilson', 'O Pro Performance Replacement Grip da Wilson oferece uma superfície macia e aderente para uma sensação de toque excepcional. A Easy Wrap Technology torna a aplicação deste grip de substituição super fácil e simples ? um início mais longo permite que o grip se ajuste perfeitamente ao "butt cap", enquanto a borda superior sombreada serve como guia para uma aplicação consistente. Todos esses recursos criam uma aparência e sensação profissionais para qualquer jogador de tênis. Características Um pouco mais macio para aumentar o conforto geral Fino e pegajoso para uma ótima sensação ao toque Easy Wrap Technology: início mais longo, borda superior sombreada, linhas de corte em relevo e sub-grip inovador, facilitando uma instalação fácil e com aparência profissional Disponível nas cores marrom e preto', 79.0, 79.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Tennis', 'https://cf.shopee.com.br/file/sg-11134201-7rd4c-lvaick7mlofk3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F23297505409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
