INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12483320758', 'Baquetas Liverpool Classic Series 5A Marfim Ponta Nylon LL-5AN Par', 'Olá, seja bem-vindo à HGZ Music Store! Baquetas Liverpool Classic Series 5A Marfim Ponta Nylon LL-5AN. A Liverpool Classic Series 5A é um par de baquetas desenvolvido para bateria e instrumentos de percussão, produzido em madeira Marfim e equipado com ponta de nylon. O padrão 5A oferece uma proposta versátil para estudos, ensaios e performances. A ponta de nylon proporciona uma resposta definida, especialmente em pratos, enquanto o corpo em Marfim oferece uma pegada tradicional para o baterista. O modelo comercializado corresponde à referência LL-5AN e acompanha 1 par de baquetas. Características: Marca Liverpool Linha Classic Series Padrão 5A Madeira Marfim Ponta de nylon Acabamento natural Par de baquetas Ficha Técnica Marca: Liverpool Modelo: LL-5AN / 5A Categoria: Baquetas Aplicação: Bateria e instrumentos de percussão Conteúdo da Embalagem: 1 par de Baquetas Liverpool Classic Series 5A com ponta de nylon. Antes da compra, confira as imagens do anúncio e confirme se o modelo atende às suas necessidades. Somos a HGZ Music Store, especialistas em Instrumentos Musicais e Áudio Profissional, oferecendo produtos selecionados, compra segura, entrega rápida e atendimento especializado. Caso tenha alguma dúvida, nossa equipe estará pronta para ajudar. HGZ Music Store.', 59.9, 39.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Percussion Instruments', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mr20h90ttfd1e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340675874%2F12483320758', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698129038', 'MEU ENORME LIVRO DOS NÚMEROS', 'MEU ENORME LIVRO DOS NÚMEROS Este enorme livro introduz os números para as crianças, com ilustrações muito fofas e divertidas! Além de treinar a memória e a lógica, é uma ótima oportunidade de desenvolvimento de vocabulário. Há muitos relógios, animais, objetos e comidas nestas páginas, quantos de cada um será que você consegue contar? Um livro perfeito para trabalhar contagem com os pequenos!. Informações Adicionais Autor: REALLY DECENT BOOKS LTD. Data Publicação: 01/01/1900 Tipo de capa: CAPA DURA Condição do Item: Novo Subtitulo: MEU ENORME LIVRO DOS NÚMEROS Idioma: INDEFINIDO Páginas: 16 Edição: 1 ISBN-13: 9786555308082 ISBN-10: 6555308087', 80.92, 70.0, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rfi7-m3m2qsklm5nr32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F20698129038', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
