INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13231950727', 'Kit Whey Protein Foods 2kg + Premium Creatina 100g + BCAA Fit 100g + Coqueteleira - BRN FOODS', 'WHEY PROTEIN FOODS: ➡️SUGESTÃO DE CONSUMO: ⚡Adicionar 40g (4 colheres de sopa rasas) em 300ml de água/leite. bater no liquidificador ou coqueteleira por 20 segundos e consumir imediatamente após o preparo! PREMIUM CREATINA(🍊SABOR TANGERINA🍊): ➡️SUGESTÃO DE CONSUMO: ⚡Dissolver 3g (1 colher de café) em 100ml (1/2 copo) de água, uma porção ao dia! BCAA FIT FOODS (🍊SABOR TANGERINA🍊): ➡️SUGESTÃO DE CONSUMO: ⚡Sugere-se 1 porção de 5g (1 colher de chá) diluída em 200ml (1 copo) de água! COQUETELEIRA BRN FOODS 600ml (⚡Cor/estampa pode variar de acordo com a disponibilidade de estoque!⚡) -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- ➡️NOTA: ⚡Consulte sempre um profissional de saúde antes de iniciar qualquer novo regime de suplementação. Este kit não substitui uma dieta equilibrada e um programa de treinamento adequado!', 149.9, 134.91, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5wvkdhex0ud46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F555509944%2F13231950727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
