INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797078310', 'Guarda Sol Scoat 1.8 Metros Articulado Cores Variadas MOR', 'Guarda Sol Scoat 1,8M Cores Variada MOR - CORES VARIADAS - Cabo articulado Descrição O Guarda-Sol 1,80m Mor é leve, fácil de montar e indispensável para que gosta de aproveitar as delícias da praia, piscina ou camping sem descuidar da saúde. Com FPS 70 é produzido em poliéster com revestimento em silvercoating, uma camada de aplicação prateada que ajuda a proteger contra os raios solares. Seu tubo é estruturado em aço carbono com pintura epóxi à pó e rebites em aço, que o tornam resistente e durável. O Guarda-Sol acompanha ainda uma sacola que facilita o transporte e possui gomos brancos que são intercalados com quatro opções de cores: azul, verde, vermelho e laranja. Especificações: Proteção FPS Até 70 FPS Material Poliéster cores variadas DIMENSÕES: Altura 2,00 Metros Largura 1,80 Metros Comprimento 1,80 Metros Peso 942,00 Gramas Disponivel nas *cores: Vermelho, Laranja, Azul e Verde. *** ATENCÃO: NÃO É POSSÍVEL ESCOLHER A COR. O PRODUTO SERÁ ENVIADO NA COR DISPONÍVEL EM ESTOQUE. * Imagens meramente ilustrativas.', 61.01, 52.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Umbrellas', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk8brrkutcsgbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F20797078310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
