INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29191321604', 'One Piece Egghead 2025 - Contém 10 Envelopes (50 Figurinhas) - Novo', 'One Piece Egghead 2025 - Contém 10 Envelopes (50 Figurinhas)Este Kit contém:10 envelopes - cada envelope contém 5 figurinhas.Os envelopes são lacrados e as figurinhas são aleatórias e sortidasEmbarque com a tripulação do Chapéu de Palha na Coleção One Piece Road To Egghead e reviva os momentos inesquecíveis da Aliança Ninja-Pirata-Mink-Samurai, enquanto rumam à Terra de Wano para desafiar um dos lendários Imperadores do Mar. Cromos exclusivos, fotos épicas e cenas marcantes da saga vão acompanhar você nessa jornada. Não fique de fora - complete sua coleção e viva essa aventura!Segmentos: Colecionáveis, Colecionáveis - Entretenimento Marcas: Panini Editora: Panini Idioma: Português Condição: Novo/Lacrado', 47.0, 39.95, NULL, 'Hobbies & Collections > Collectible Items > Sports Collectibles', 'https://cf.shopee.com.br/file/sg-11134201-824is-meftfg2omarn6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F29191321604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
