INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999303216', 'Ventilador de Teto 3 Pás 130W Branco/Mogno VENTUS VENTI-DELTA', 'Ventilador de Teto 3 Pás 130W Branco/Mogno VENTUS 110V VENTI-DELTA O Ventilador de Teto 3 Pás 130W Branco/Mogno VENTI-DELTA oferece uma combinação perfeita de elegância e desempenho. Com seu design sofisticado em branco e mogno, ele adiciona um toque de estilo a qualquer ambiente. Equipado com três pás que garantem uma distribuição eficiente do ar, este ventilador proporciona uma ventilação poderosa e silenciosa, ideal para manter o ambiente fresco e agradável. Com 130W de potência, é uma escolha eficiente e econômica para qualquer espaço. Dados Técnicos Potência: 130 W Rotação Máxima: 180 a 460 rpm Pás: 3 pás (MDF) mogno Lustre: Vidro fosco com detalhes em marrom Área de Ventilação: 20m² Voltagem: 110 V Controle de Velocidade: c3v (exaustão e ventilação com controle de velocidade mínimo, médio e máximo) Cores: Branco/Mogno Dimensão do Produto Montado (Altura / Diâmetro): 42 x 100 cm Peso: 4,4 kg Garantia: 12 meses Referência: 42-3100 Marca: Venti-Delta * Imagens meramente ilustrativas.', 503.9, 465.99, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-lxcobtisd2sm0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F18999303216', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097454530', 'Míni Relé Auxiliar 24V - DNI 0226', 'Míni Relé Auxiliar 24V - DNI 0226Descrição do ProdutoO Míni Relé Auxiliar é um componente essencial para o funcionamento adequado de diversos sistemas automotivos. Com 5 terminais e tensão de 24V, este relé suporta correntes de até 40/30A. Ideal para aplicações como bloqueio do diferencial, controle de farol alto/baixo e acionamento de faróis auxiliares. Compatível com uma variedade de veículos, este relé é a escolha perfeita para garantir o funcionamento correto dos sistemas elétricos do seu veículo. Atributos do ProdutoMarca: DNI Modelo: DNI0226 Códigos EquivalentesEste Míni Relé Auxiliar é compatível com uma ampla gama de veículos, incluindo modelos das seguintes marcas: MERCEDES-BENZ: 3845427119 - Atego / Axor / O-500 / OF / OH SCANIA: 25422719, 25423019, 1320483, 3093031, 7375181000 FORD: 6C4514B192-AA VOLVO: 1078690 - Ônibus e Caminhões DAF: 1448174, 1301879 IVECO: 98444017, 02991715 RENAULT TRUCKS: 5010589427, 5010645017 Adquira Agora o Míni Relé Auxiliar DNI 0226 e Garanta a Eficiência dos Sistemas do seu Veículo!', 25.0, 25.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-8262d-mjo9s3r75tkz8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F23097454530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799183290', 'Terminal Bateria Double Ring Positivo 2 Parafusos 6mm Cabo 10-20mm MTA', 'Terminal de Bateria Double Ring Polo Positivo MTA 1416003 – Conexão Segura e Alta Condutividade Garanta conexão elétrica segura, eficiente e durável para o sistema elétrico do seu veículo. O Terminal de Bateria Double Ring Polo Positivo MTA 1416003 foi desenvolvido para proporcionar conexão firme entre o cabo elétrico e o polo positivo da bateria, garantindo excelente condução elétrica e maior segurança no funcionamento do sistema elétrico do veículo. Seu modelo Double Ring (duplo anel) permite a conexão de mais de um cabo no mesmo terminal, facilitando instalações elétricas adicionais ou reposição em sistemas automotivos, caminhões, embarcações e equipamentos elétricos. Fabricado com materiais de alta qualidade e padrão original, o terminal oferece excelente resistência mecânica, durabilidade e ótima fixação no polo da bateria. Aplicação Indicado para sistemas elétricos de: Automóveis Caminhões Utilitários Máquinas e equipamentos elétricos Sistemas automotivos auxiliares Aplicação no polo positivo da bateria. Características do Produto Modelo: Double Ring (Duplo Anel) Tipo: Terminal de bateria Polo: Positivo Fixação: 2 parafusos Rosca dos parafusos: M6 Modelo original de reposição. Principais Benefícios Conexão elétrica firme e segura Alta condutividade elétrica Permite ligação de dois cabos simultaneamente Instalação simples e rápida Excelente fixação no polo da bateria Produto com padrão original de qualidade Conteúdo da Embalagem 1 Terminal de bateria polo positivo 2 Parafusos rosca M6 para fixação Marca MTA – Código 1416003 A MTA é referência mundial em componentes elétricos automotivos, oferecendo produtos confiáveis e duráveis utilizados por montadoras e no mercado de reposição. Garanta segurança e eficiência no sistema elétrico do seu veículo com o Terminal de Bateria Double Ring Polo Positivo MTA 1416003. Ideal para quem busca qualidade, resistência e instalação profissional.', 89.04, 89.04, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbl3-lq3rsrw0kti85b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F552700125%2F20799183290', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43559698242', 'Sandália Vizzano Feminina Salto Alto Conforto 6292-200 Bege Verniz', '✨ Sandália Vizzano Feminina Salto Alto Conforto – Elegância e Versatilidade para Qualquer Ocasião ✨ A Sandália Vizzano salto alto conforto combina sofisticação, modernidade e estabilidade, perfeita para quem quer estar bem vestida em festas, casamentos, formaturas, mas também para momentos casuais e do dia a dia. Seu design minimalista com tira frontal e fechamento por fivela 🪝 garante um visual elegante, enquanto o salto grosso proporciona segurança e conforto ao caminhar. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/19699678613/ 🌟 Destaques 👠 Design clean e elegante que combina com diversos looks 💪 Salto grosso que oferece mais firmeza e equilíbrio 🪝 Fechamento por fivela lateral ajustável ☁️ Palmilha macia e anatômica para conforto prolongado 🛡️ Solado antiderrapante para maior segurança 📌 Ficha Técnica Marca: Vizzano Material externo: Sintético Material interno: Forro têxtil Solado: Borracha antiderrapante Fechamento: Fivela lateral ajustável Numeração: 33 ao 40 Altura do salto: 10 cm Indicação: Festa, casamento, formatura, balada, casual e dia a dia 📏 Tabela de Tamanhos 33 - 21,5 cm 34 - 22,0 cm 35 - 23,0 cm 36 - 23,5 cm 37 - 24,5 cm 38 - 25,0 cm 39 - 26,0 cm 40 - 26,5 cm 🛒 Garanta já a sua Sandália Vizzano salto alto conforto e arrase em qualquer ocasião!', 159.9, 129.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcjdj9zofprm38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F43559698242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211366227', 'Kit Bioré Make Up Remover Cleansing Oil Refil (2 Unidades)', 'O Kit Bioré Make Up Remover Cleansing Oil Refil é uma solução para remoção eficiente de maquiagem, desenvolvido para quem busca praticidade e limpeza profunda da pele. Com tecnologia avançada, este óleo demaquilante promove uma limpeza delicada e eficaz, removendo até as maquiagens mais resistentes, como base à prova d''água, máscara de cílios e delineador. Sua tecnologia exclusiva forma camadas laminares que garantem uma dissolução eficaz dos produtos cosméticos, deixando sua pele incrivelmente limpa sem resíduos indesejados. Contém: Bioré Make Up Remover Cleansing Oil Refil - Óleo Demaquilante 2x210ml Como usar: Aplique o cleansing oil nas mãos e, em seguida, massageie delicadamente o rosto para remover a maquiagem, inclusive máscara à prova d`água. Para finalizar, enxágue abundantemente com água. Não é necessário uso de sabonete facial após a aplicação. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 111.8, 111.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-823op-mooijg2biby97a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58211366227', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997891600', 'Bóia Tanque Sensor Nível Vw T-cross 2020 a 2024 - 1350144 - 23270', 'Bóia Tanque Sensor Nível Vw T-cross 2020 a 2024 1350144 23270 1.0 3Cil 12v TSI Flex O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 166.95, 166.95, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-823px-mp17ug1tvthead', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23997891600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897462654', 'Sensor Temperatura Gm Celta 2009 a 2015 - 518052 - 4051', 'Sensor Temperatura Gm Celta 2009 a 2015 518052 4051 1.0 8v - 2 Pinos - Azul - Água Cebolinha de temperatura ou Sensor Temperatura - Informa com precisão para o painel do veículo, como para o computador da injeção eletrônica o valor exato dessa temperatura, para evitar imprevistos e grandes prejuízos. Veículos mais novos aciona a ventoinha no lugar do Interruptor Térmico e a partida a frio nos veículos Flex. É possível encontrar o sensor de temperatura no cabeçote, ou seja, a parte mais quente do motor e onde a temperatura pode ser medida com uma precisão mais assertiva.', 57.26, 57.26, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd70-luf0sgrc1mp5e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23897462654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
