INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43261293690', 'Melissa Free Platform Thong Chinelo Original Casual 36088 Bege', '🩴✨ Melissa Free Platform Thong – Estilo, Conforto e Modernidade em um Só Chinelo O Chinelo Melissa Free Platform Thong é a escolha perfeita para quem ama unir moda e praticidade. Com design moderno, plataforma estilosa e o conforto característico da Melissa, esse chinelo feminino é ideal para looks urbanos, despojados e fashionistas, garantindo autenticidade em qualquer ocasião. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/40453880570/ 🌟 Benefícios Exclusivos: 👡 Plataforma moderna: Altura que traz estilo sem perder o conforto. 🌿 Material Melflex: PVC exclusivo da Melissa, flexível e durável. ✨ Design fashion: Combina com roupas casuais e urbanas. 🛡️ Conforto garantido: Palmilha anatômica que absorve impacto. 💨 Leve e prático: Ideal para usar no dia a dia ou em momentos de lazer. 🎀 Originalidade Melissa: Qualidade e autenticidade da marca que é ícone de moda. 🧼 Dicas de Limpeza e Conservação: Lave com água e sabão neutro. Utilize pano úmido para manter o brilho. Deixe secar naturalmente, longe do sol. Guarde em local seco para preservar o material Melflex. 📌 Ficha Técnica: Marca: Melissa Modelo: Free Platform Thong Tipo: Chinelo Feminino Plataforma Material: Melflex (PVC exclusivo Melissa) Palmilha: Anatômica e confortável Ocasião: Uso diário, lazer, passeios, moda urbana 📏 Tabela de Medidas (cm): 33 – 22,0 cm 34 – 22,7 cm 35 – 23,3 cm 36 – 23,9 cm 37 – 24,5 cm 38 – 25,1 cm 39 – 25,7 cm 40 – 26,3 cm 💎 Diferenciais: Chinelo feminino com plataforma estilosa, produzido em Melflex, confortável, durável e versátil. O Melissa Free Platform Thong é perfeito para quem busca autenticidade e moda em um só calçado.', 289.9, 259.9, NULL, 'Women Shoes > Wedges', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcxl39gjby2a4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F43261293690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098255790', 'Almofada Body Pillow Cinza Mescla - Loja Fom', 'A Almofada Body Pillow Cinza Mescla é uma novidade para coleção de Natal! Ela chegou para complementar a linha Durma Bem da FOM. Por ter seu formato alongado, é uma ótima opção de travesseiro corporal, trazendo apoio e sustentação enquanto você dorme. A Almofada Body Pillow também pode ser usada como almofada de encosto para cama e apoio para pernas e lombar, sendo um produto multifuncional. Feito com tecido elástico e enchimento de micropérolas, tecnologia exclusiva da FOM, ela é ergonômica e promove seu bem-estar.', 488.0, 488.0, NULL, 'Home & Living > Furniture > Cushions', 'https://cf.shopee.com.br/file/sg-11134201-7rd6o-m6rd0e7xgp4902', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1366041969%2F22098255790', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397034347', 'Filtro Óleo Peugeot 106 1997 a 2001 - 166540 - WUNI0004', 'Filtro Óleo Peugeot 106 1997 a 2001 166540 WUNI0004 (Passion / Quiksilver / Selection / Soleil) - 1.0 8V - Gasolina - Mecânico - (Blindado) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 23.29, 23.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mq7orgqwre2q16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23397034347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497426663', 'Polia ar condicionado FOCUS 2000/2005 - 36504 - 4221', 'Polia ar condicionado FOCUS 2000/2005 1.8/2.0 16V ZETEC - COM ACD (ESTRIADA - 69mm) É o componente que está montado no eixo do rotor do alternador, e por meio de uma correia de distribuição, o alternador gira conforme a velocidade do rotação do motor(Rpm). Esta correia pode ser do tipo trapezoidal ou do tipo poly-V.', 43.81, 43.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbm8-lmru30zm5mjd5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20497426663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
