INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998358556', 'Cilindro Roda Fiat Argo 2017 a 2025 - 1356151 - CCR92283', 'Cilindro Roda Fiat Argo 2017 a 2025 1356151 CCR92283 1.0 (6V) | 1.3 (8V) | 1.8 (16V) (Sistema ATE) - (Traseiro) (Lado Direito/Esquerdo) (7/8" -22,22 mm) (Alumínio)O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 98.92, 98.92, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-m7ui7f8vnhotdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22998358556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
