INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293574938', 'Caixa de Inspeção Aterramento 14 x 18cm Dual', 'Caixa Aterramento DUAL em PEAD para Instalações Elétricas Externas é um elemento essencial para garantir a segurança e eficiência das instalações elétricas. Fabricada em Polietileno de Alta Densidade (PEAD), esta caixa oferece uma resistência excepcional contra impactos e produtos químicos, tornando-se a escolha ideal para ambientes adversos. Com um design compacto e funcional, suas dimensões de 14 cm de diâmetro por 17,5 cm de altura permitem uma instalação discreta e eficaz. Projetada especificamente para suportar condições climáticas desafiadoras, a Caixa Aterramento DUAL é perfeita para aplicações externas. Sua cor preta não só ajuda na camuflagem em diversos cenários como também contribui para minimizar a exposição visual, mantendo a estética do ambiente. Vantagens: Material Resistente: Confeccionada em PEAD, que assegura durabilidade e resistência química. Montagem Simples: Sistema de pressão que facilita o acesso e garante vedação eficaz. Design Compacto: Medidas ideais para diversas aplicações sem comprometer o espaço. Cor Discreta: Preto, perfeito para ambientes externos onde a discrição é necessária. Proteção Avançada: Resiste a intempéries, protegendo conexões de aterramento. Fácil Manutenção: Superfície lisa que simplifica a limpeza e conservação. Especificações técnicas: Marca: Dual Material: Polietileno de Alta Densidade (PEAD) Sistema de Montagem: Pressão Dimensões: 14 cm x 17,5 cm Cor: Preto Uso: Interno e Externo Resistência a Intempéries: Sim Conteúdo da embalagem: 1 Caixa Aterramento DUAL em PEAD 1 Tampa de vedação Garantia: 1 ano de garantia pelo fabricante', 31.9, 21.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7reoe-m84qp2w337ah44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23293574938', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392572273', 'Capa Proteção Correia Dentada Vw Gol 1997 a 2001 - 843035 - 106136', 'Capa Proteção Correia Dentada Vw Gol 1997 a 2001 843035 106136 1.0 16v - Externa Inferior O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 89.78, 89.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmp-ln0a4e945f050e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23392572273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41154250045', 'Jogo Parafuso Cabeçote TUCSON 2.0 16V GAS. 2004/2012 - 107920 - PCB853010', 'Jogo Parafuso Cabeçote TUCSON 2.0 16V GAS. 2004/2012 2.0 16V GAS. - Kit c/ 10Pcs (M10 x 1,25 x 100mm/151mm) Função: Garantir a união entre o cabeçote, junta do cabeçote e o bloco do motor, sem permitir uma perda de torque que cause vazamentos pela junta de cabeçote. Características: Suportar condições criticas de esforços intermitentes, altas temperaturas e fadiga, garantindo que a junta de cabeçote permaneça apertada.', 172.06, 172.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ravk-maweneucykmrb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F41154250045', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498037875', 'Cilindro Mestre de Freio Chevrolet Chevy 500 - 83 84 85 86 - 10594 - C2001', 'Cilindro Mestre de Freio Chevrolet Chevy 500 - 83 84 85 86 * 12 MESES DE GARANTIA *_x000D_ _x000D_ C2001 - CILINDRO MESTRE FREIO CHEVROLET CHEVY 500 (DUPLO) SEM RESERVATÓRIO - USE COM RESERVATÓRIO C0100_x000D_ ANOS : 1983 / 1984 / 1985 / 1986_x000D_ MEDIDA : 13/16" = 20,63mm Inicia Hidráulica do Freio, introduzindo e controlando o processo de frenagem. Injetando e comprimindo o óleo (fluído), gerando a pressão p/todo o sistema de freios. Cilindro Mestre Simples - A tampa do reservatório possui um respiro responsável por igualar as pressões internas, evita a formação de vácuo no caso do fluído de freio baixar. Cilindro Mestre Duplo - É a união de dois cilindros simples, esse conj. foi dirigido para dois circuitos de freio, podendo ser montado em paralelo ou diagonal.', 282.88, 282.88, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbky-ln1y3efyadkle9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22498037875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099007678', 'Filtro Gasolina SANTANA 1994/1997 - 43845 - FCI1620', 'Filtro Gasolina SANTANA 1994/1997 (CL / CLI / C / CS / CD / CG / GLS) - Motor 1.8 8v AP CFI Álcool - (Mecânico) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 27.91, 27.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822yq-mofrijcjdmv402', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18099007678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197381148', 'Óleo De Motor Motul Semi-sintético 10w-30 Para Motos E Quadriciclos X 1l', 'O óleo é uma parte essencial para o bom funcionamento do motor do seu veículo, pois tem a função de limpar e lubrificar, buscando protegê-lo do desgaste e da corrosão. A Motul mostra uma forte dedicação à excelência, através da inovação e conexão com sua comunidade. A marca busca criar óleos que proporcionem uma eficiência duradoura.', 106.26, 95.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-lz0ir2xb8jg414', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F19197381148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592971488', 'Válvula Equalizadora Gm Monza 1987 a 1996 - 120941 - 21631', 'Válvula Equalizadora Gm Monza 1987 a 1996 120941 21631 (25 Bar) Limitar a pressão dos freios nas rodas traseiras._x000D_ Aplicação: Normalmente é instalada no cilindro mestre, mas pode estar na linha do freio traseiro._x000D_ Funcionamento: É acionada sempre que recebe uma pressão de óleo maior que sua pressão de corte, evitando assim o travamento das rodas traseiras._x000D_ Características: Fabricadas em alumínio com tratamento superficial por anodização e componentes em aço inox.', 78.82, 78.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd60-lufhm9tl4fyj48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23592971488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198922371', 'Suporte sensor estacionamento traseiro GM 52051671', 'APLICAÇÕES: ---------------------------------------- Spin 2014/2016 Suporte do sensor do alarme de estacionamento traseiro (Sensor de estacionamento traseiro) Spin 2014/2018 Suporte do sensor do alarme de estacionamento traseiro LE (Para-choque dianteiro/traseiro, cor do veículo / Sensor de estacionamento traseiro) ---------------------------------------- Para sua segurança e para o correto funcionamento do produto, recomendamos que a instalação seja sempre feita por profissionais especializados e qualificados em uma de nossas concessionárias autorizadas Chevrolet. Lembramos que a instalação inadequada poderá gerar a perda da garantia. Em caso de dúvidas sobre a compatibilidade dessa peça com seu veículo, envie-nos o chassis do seu veículo via chat antes de efetuar a compra.', 17.38, 17.38, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/sg-11134201-8262y-mlw1ydk5t4ao60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593086956%2F22198922371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48406314320', 'Tênis Anacapri Luli Off White Cinza e Preto - Feminino', 'Um clássico urbano que combina com todos os seus momentos! Tênis Anacapri Luli Off White Cinza e Preto - Feminino Ficha Técnica: Marca: Anacapri Modelo: Luli Gênero: Feminino Cor: Off White, cinza e preto Indicação: Uso casual, dia a dia e passeios Material: Tecido com recortes em camurça e napa Fechamento: Cadarço Solado: Baixo emborrachado na cor bege Palmilha: Comfy com assinatura Anacapri Forro: Interno forrado para maior conforto Design: Costura pesponto nos contornos e recortes modernos no cabedal Detalhes: Recortes em camurça cinza na biqueira, lingueta e parte traseira. Aplicação lateral personalizada em napa preta com design em “A” e tag lateral marrom Anacapri Com visual atemporal e detalhes modernos, o Tênis Anacapri Luli é aquele modelo indispensável no guarda-roupa feminino. Porque investir: Extremamente confortável e fácil de combinar, ele traz recortes sofisticados e mix de materiais que elevam o visual. A palmilha comfy e o solado baixo garantem leveza no uso diário, enquanto o design imponente acompanha looks despojados ou mais estruturados com muito estilo. Conteúdo da embalagem: 1 par de Tênis Anacapri Luli Off White Cinza e Preto - Feminino Parte superior do formulário Parte superior do formulário Parte superior do formulário', 199.99, 164.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8261r-mky8yjagb0n582', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F48406314320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
