INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44856208860', 'Tênis Asics Gel Shinobi 2 Lilás - Feminino', 'O equilíbrio ideal entre amortecimento e estilo para o seu dia a dia! Tênis Asics Gel Shinobi 2 Lilás - Feminino Ficha Técnica: Marca: Asics Cor: Lilás Gênero: Feminino Indicado: Academia, corridas leves e caminhadas Cabedal: Poliéster - Jacquard mesh respirável, leve e macio Palmilha: Poliéster - Macia e anatômica Sola: Borracha resistente para maior tração e durabilidade Fechamento: Cadarço Amortecimento: Tecnologia GEL com nova geometria para melhor absorção de impacto Estabilidade: Entressola em EVA para conforto e equilíbrio Entressola: EVA macia Detalhes: Design moderno com ventilação aprimorada Com visual moderno e tecnologia avançada, o Asics Gel Shinobi 2 foi remodelado para proporcionar máximo conforto em treinos leves e caminhadas. Seu cabedal em Jacquard mesh mantém os pés sempre arejados, enquanto a entressola em EVA garante pisadas suaves e equilibradas. Porque investir: A combinação do amortecimento em GEL com solado emborrachado resistente oferece durabilidade, conforto e proteção contra impactos. Perfeito para mulheres que buscam performance e estilo em um só calçado. Conteúdo da embalagem: 1 par de Tênis Asics Gel Shinobi 2 Lilás - Feminino', 399.99, 367.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-825zl-mkoa5a2v65fo02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F44856208860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
