INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41467194434', 'Cereal Choco Corn 60g - Alca Foods', '🥣 Cereal Choco Corn 60g – AlcaFoods Crocância e sabor de chocolate em cada colherada! O Cereal Choco Corn AlcaFoods é feito com milho crocante coberto com sabor irresistível de chocolate, ideal para começar o dia com energia ou para aquele lanche rápido e gostoso. 📦 Detalhes do Produto Marca: AlcaFoods Produto: Cereal Choco Corn Peso líquido: 60g Apresentação: Pacote individual, pronto para consumo Textura: Crocante, com sabor de chocolate 🌟 Benefícios Sabor delicioso de chocolate que agrada crianças e adultos. Pacote prático no tamanho ideal para lancheiras, viagens ou consumo diário. Pode ser consumido puro como snack ou com leite para um café da manhã nutritivo. Produzido pela AlcaFoods, referência em cereais matinais no Brasil. 🎉 Indicação de Uso Perfeito para café da manhã, lanches rápidos, sobremesas e até receitas criativas. Ótimo também para compor kits festa, cestas de café da manhã ou lembrancinhas escolares. ⚠️ Avisos Contém glúten. Pode conter leite e derivados de soja. Produto perecível: Nossos produtos têm um prazo de validade superior a 5 meses. Se tiver mais alguma dúvida ou precisar de mais informações, estou à disposição! Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002. 👉 Garanta já seu Cereal Choco Corn AlcaFoods 60g e aproveite todo o sabor crocante com chocolate em qualquer momento do dia!', 8.99, 8.99, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Cereal, Granola & Oats', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me5wq1h0j1tuaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F41467194434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
