INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397464888', 'Fralda Pampers Premium Care Pants XG com 26un', 'A fralda calça Pamper Pants Premium Care possui cintura elástica 360 é fácil de colocar até quando o bebê está em movimento, dando um ajuste perfeito e mantendo a pele seca e protegida. A fralda Pampers Premium Care Pants possui canais de ar que permitem que o ar circule livremente pela fralda, para que o bumbum fique menos abafado e a pele fique arejada e sequinha durante a noite. Pampers Pants Premium Care também possui proteção Pampers Premium Care, a proteção mais suave para a pele do bebê, ultra respirável para manter a pele do bebê fresca e loção hipoalergênica que ajuda a prevenir irritações. A fralda calça Pampers Pants Premium Care é muito fácil de pôr e tirar basta seguir o modo de uso: 1. Coloque a mão dentro da fralda; 2. Suba a fralda como um shortinho através dos elásticos adaptáveis; 3. Para retirar a fralda rasgue suas laterais e retire-a normalmente; 4. Enrole e feche a fralda com a fita adesiva da parte de trás.', 76.79, 70.75, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rd3q-lu990edk7ci999', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1062557396%2F22397464888', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
