INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097491706', 'Colar Feminino Duplo de Prata 925 Coração e Chave pendente', 'Colar Feminino Duplo de Prata 925 Coração e Chave pendente O Colar Feminino Duplo de Prata 925 Coração e Chave pendente é uma peça romântica e delicada. Com um design duplo, combinando pendentes de coração e chave, este colar é perfeito para quem busca um toque de romantismo e sofisticação. Fabricado em Prata 925, oferece durabilidade e qualidade. Especificações: Tamanho do Colar com Coração: 44cm Tamanho do Colar com Chave: 38cm Tamanho do Ponto de Luz: 5cm Tamanho da Chave: 12mm Tamanho do Coração: 6mm Tamanho do Ponto de Luz: 3mm Largura: 1mm Extensor: 5cm Modelo: Cartier Fecho: Mosquetão Peso: 4g Material: Prata 925 O Colar Feminino Duplo de Prata 925 Coração e Chave pendente é uma peça versátil que pode ser usada em diversas ocasiões. Com seu modelo duplo e fecho seguro, ele é perfeito para adicionar um toque de elegância e romantismo ao seu visual. Principais Características: ✔ Design duplo com pendentes de coração e chave ✔ Modelo Cartier para um toque sofisticado ✔ Material de alta qualidade: Prata 925 ✔ Tamanho ajustável com extensor ✔ Fecho seguro: Mosquetão Adquira agora o Colar Feminino Duplo de Prata 925 Coração e Chave pendente e adicione um toque de romantismo ao seu estilo. Para mais informações ou assistência, entre em contato conosco. © Aqua Joias. Todos os direitos reservados 2024', 277.8, 187.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-7rdwn-lyo3rk0b74zrb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23097491706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
