INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699072911', 'Fantasia Palhaço Pennywise It a Coisa Adulto de Luxo Halloween', 'Itens inclusos: 01 Camisa Manga Longa 01 Calça Obs: Máscara vendida separadamente/ Botas e balão não acompanha! Tamanhos: PP - Numeração de roupa 32 a 34. P - Numeração de roupa 36 a 38. M - Numeração de roupa 40 a 42. G - Numeração de roupa 44 a 46. gg - Numeração de roupa 46 a 48. Ficou na dúvida de qual tamanho escolher? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. Especificações Técnicas Material: Poliéster Produto: Produto novo, na embalagem. Cor: Cinza Produto a pronta entrega! Produto Original Em busca de uma fantasia assustadora para o dia mais sombrio do ano? Que tal essa clássica fantasia de palhaço assasino? A fantasia de luxo do palhaço Penywise, é composta por uma camisa manga longa cheia de babados e elásticos nas mangas, com gola dupla e aplique de pompons na frente, com fechamento por zíper nas costas. A calça com elástico na cintura e babados no tornozelo, deixam a fantasia ainda mais realista e parecida com o personagem de terror Palhaço It a Coisa. Fantasia fabricada com tecido de altíssima qualidade, com acabamentos impecáveis. Confira os detalhes e garanta já o seu! Linha Luxo Temática Halloween Não Esquenta Não Pinica Máscara vendida separadamente Não acompanha botas e balão!', 309.47, 309.47, NULL, 'Men Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-8261p-mks6huhpio7b80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F20699072911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201043204', 'Lâmpada Farol Super Led Moto 6000k Thork - Tipo Cavalinho H4 Preto Branco-frio', 'Lâmpada Super LED Moto H4 Thork 12V AC DC 6000K Branca Farol Alto Baixo IP67 Universal Conteúdo da embalagem: 1 Lâmpada Super LED Thork H4 Principais características técnicas: Encaixe: H4 Tensão: 12V DC e AC Faixa de operação: 12V a 15,5V Temperatura de cor: 6000K (branco) Função farol alto e baixo na mesma lâmpada Compatível com sistemas elétricos DC e AC Certificação IP67 resistente à água Design compacto Excelente intensidade luminosa Baixo consumo de energia Maior vida útil Estrutura resistente em liga metálica Composição: liga metálica, nylon, silicone, cobre, estanho e polímero Compatibilidade: Compatível com todas as motocicletas nacionais e importadas que utilizam lâmpada H4, em sistemas elétricos 12V DC (corrente contínua) e 12V AC (corrente alternada). Indicado para motos Honda, Yamaha, Suzuki, Kawasaki, BMW, Triumph, Dafra, Haojue, Shineray e demais modelos equipados originalmente com encaixe H4. Informações adicionais: O Super LED Thork proporciona iluminação branca de 6000K, oferecendo maior visibilidade, segurança e um visual moderno para a motocicleta. Seu formato ultracompacto facilita a instalação no alojamento original do farol, mantendo excelente dissipação térmica, alta durabilidade e baixo consumo de energia. É um dos menores LEDs do mercado, desenvolvido para oferecer máxima eficiência luminosa sem comprometer o espaço interno do conjunto óptico. Em motocicletas com sistema AC podem ocorrer pequenas oscilações de funcionamento, característica própria do sistema elétrico. Em alguns modelos poderá ser necessária a utilização de canceller (não incluso). Instalação: A instalação deve ser realizada por um profissional capacitado. Antes da instalação, verifique a compatibilidade do encaixe H4 e a legislação vigente para utilização de lâmpadas LED. A modificação das características originais do produto acarreta a perda da garantia. A marca não se responsabiliza pelo mau uso do produto. Agradecemos sua preferência! Se necessário, conte com nosso suporte para um pós-venda ágil e de qualidade.', 49.9, 47.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-8227f-mhi9abesy32dcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1468645233%2F58201043204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27326969916', 'Estojo Grande Nécessaire Estojo Escolar Colorido Neon Tecido Resistente Estiloso', 'Um estojo em tecido colorido neon uma peça vibrante e moderna, feita de material têxtil com cores intensas e fluorescentes, como verde neon, rosa, laranja ou amarelo. O tecido é leve, mas resistente, e o estojo tem uma estrutura compacta, ideal para guardar itens pequenos como canetas, lápis, maquiagem ou outros acessórios. O design pode ser simples ou ter detalhes como zíperes, bolsos adicionais e costuras decorativas, conferindo um toque de estilo arrojado e contemporâneo. Ele é perfeito para quem gosta de se destacar com um toque de cor e personalidade! Medidas: 20cm x 6,5cm x 4,5cm Material: Tecido Poliester Cores: Pink, Laranja, Amarelo e Verde', 49.9, 14.16, NULL, 'Stationery > School & Office Equipment > Pencil Cases', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8kj9lwg2odtcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F27326969916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
