INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893716229', 'Assento Privada Vaso Sanitário Tupan Modelo Universal Soft Close PP Branco Compatível Várias Marcas', 'Assento universal para todas as bacias ovais, em polipropileno Higiênico e de fácil limpeza, Confortável e resistente. Com tampa envolvente, superfície brilhante e com fechamento Soft Close . O Assento Sanitário Convencional Solution Branco da Tupan é fabricado em polipropileno, possui 45,5 cm de comprimento, 38,2 cm de largura e a distância entre os furos é de 15 cm. Esse assento sanitário branco é bastante higiênico, pois dispõe de uma superfície lisa brilhante que promove mais facilidade na limpeza e inibe a proliferação de germes. Além disso, conta com fixadores ajustáveis e deslizantes que simplificam a instalação em diversos modelos de louças sanitárias e também traz uma tampa envolvente que cobre todo o assento. Vale destacar que o assento sanitário oval universal pode ser utilizado em qualquer bacia convencional, ou seja, louças com o formato redondo. PESO: 1,2kg COMPRIMENTO: 0,39cm LARGURA: 0,‎48cm ALTURA: ‎0,6cm MODELO: ‎AUSPP00SC FABRICANTE: ‎TUPAN INDUSTRIA E COMERCIO LTDA assento sanitario, tampa de vaso, asento de vaso, assento de vazo, acento de vaso, acento de vaso, assento d vaso, vaso sanitário, assento de bacia sanitária, assento de bacia, assento de bacia deka', 299.9, 189.9, NULL, 'Home & Living > Bathrooms > Toilet Bowls, Seats & Covers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdx7vic7ibyaa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1384728500%2F23893716229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
