INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098003154', 'Deo Colônia Feminino Summer Flowers 15ml - Amakha Paris', 'O Summer Flowers parece ser uma verdadeira obra de arte em forma de perfume! Com suas notas florais ambaradas, ele promete proporcionar uma experiência olfativa fascinante, envolvendo quem o utiliza em sensações inebriantes. As fragrâncias florais costumam evocar sentimentos de frescor, delicadeza e elegância, enquanto as notas ambaradas adicionam uma profundidade e calor irresistíveis. Portanto, ao usar o Summer Flowers, você não apenas exala um aroma encantador, mas também transmite uma aura de sofisticação e sedução. Seja para uma ocasião especial ou para o dia a dia, esse perfume certamente deixará uma impressão duradoura por onde quer que você vá. Permita-se ser envolvido por essa fragrância hipnotizante e deixe o Summer Flowers conquistar você com toda a sua magia floral ambarada. Família Olfativa: Floral Ambarado Notas Olfativas: • Notas de Topo: Rosa Búlgara, Espinheiro branco, Groselha Preta e Mandarina. • Notas de Corpo: Violeta de Parma, Rosa, Opoponax e Jasmim Baunilha, Almíscar. • Notas de Fundo: Branco e Incenso. Indicações: Para usar: Noite Ocasião: Romance Perfil: Sedutora Inspiração - Flower by Kenzo', 50.0, 32.5, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rd72-m7jq40deqk1i4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454161052%2F21098003154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21932387146', 'Mangá - Dragon Ball - 21 - Edição Definitiva (Capa Dura)', 'Dragon Ball - 21 Edição Definitiva (Capa Dura) Gohan, Kulilin, Vegeta e o recém-chegado Piccolo unem forças para enfrentar Freeza, que está se tornando cada vez mais poderoso. Goku se recupera dos ferimentos, porém não consegue impedir que Vegeta seja morto por Freeza, que atingiu o patamar de supermonstro após duas transformações. É o início da desesperadora luta de Goku contra um inimigo com um poder nunca antes visto...! Periodicidade: BimestralFormato: 14.8X21 cmTipo de Distribuição: Nacional Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Akira Toriyama ISBN: 9786525902463 Check-List: Julho/2022 Classificação Etária: 12 anos Gênero: Ação, Aventura, Comédia Demografia: Shonen Editora: Editora Panini Número de páginas: 232 Lombada/Encadernação: QUADRADA Tipo de capa: Dura Data de Lançamento: 29/07/2022 Idioma: Português Condição: Novo/Lacrado', 112.9, 112.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/2290d66b73c33f96ac7938f747a35310', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F21932387146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4686348050', 'Kit 4 Borracha De Porta Tipo Original Gol G6 2013 Até 2016', 'Detalhes do Produto: Kit 04 Borracha De Porta Tipo Original Fox, Crossfox e Spacefox 2003 Até 2016, Gol G5 e Voyage G5 2008 Até 2012 e Gol G6 e Voyage G6 2013 Até 2016 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Fox 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 Crossfox 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 Spacefox 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 Gol G5 2008 2009 2010 2011 2012 Voyage G5 2008 2009 2010 2011 2012 Gol G6 2013 2014 2015 2016 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor de 4 borrachas (serve para todas portas) Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 04 Borrachas de porta (02 anos de garantia)', 339.58, 339.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/fda2b4fc357f5bf30286ea6fd3fde082', 'https://shope.ee/an_redir?origin_link=https%3A%2F