INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594404049', 'VODKA ABSOLUT VANILLA 750ML', 'Em 2003, o lançamento de Absolut Vanilia foi inspirado em um dos sabores mais populares e apreciados ao redor do mundo: a baunilha. Com notas de caramelo e chocolate amargo, ela se destaca com um sabor marcante, ideal para a preparação de drinks mais doces e que possuem também um toque amargo, como o Vanilia Espresso Martini. Assim como os demais produtos da família Absolut, a Absolut Vanilia é produzida sem a adição de açúcar e com ingredientes naturais. A vodka Absolut Vanilia de 750 ml possui uma graduação alcoólica de 38%. É proibida a venda e o consumo de bebidas alcoólicas para menores de 18 anos. Se beber não dirija.', 108.99, 88.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meg8eyos3dogf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22594404049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
