INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56704492158', '[Renewed] DR.FORHAIR Folligen Thickening Sea Salt Exfoliator 250g, Conditioning Mask 200ml', 'DR.FORHAIR Folligen Thickening Scalp Care (2 Types) [Product Options] 1️⃣ Folligen Thickening Sea Salt Scalp Exfoliator 250g 2️⃣ Folligen Thickening Scalp Conditioning Mask 200ml [Product Description] 🧴 Professional scalp care line designed to improve scalp condition and support fuller-looking hair 🌊 Focuses on deep cleansing, sebum control, and scalp nourishment 🌿 Helps create a balanced scalp environment for healthier hair 💧 Provides refreshing, cooling care without heavy residue 📦 Net content: 250g / 200ml [Variant Description] 🌊 Folligen Thickening Sea Salt Scalp Exfoliator ✨ Focus: Scalp exfoliation + deep cleansing + sebum removal 🧂 Contains sea salt granules to remove buildup and dead skin ❄️ Provides cooling sensation and refreshes scalp 🌿 Helps unclog pores and improve scalp cleanliness ✔️ Ideal for oily scalp, dandruff, buildup concerns 🧴 Folligen Thickening Scalp Conditioning Mask ✨ Focus: Scalp nourishment + hydration + soothing care 💧 Lightweight conditioning formula hydrates without weighing hair down 🌿 Helps calm sensitive scalp and improve moisture balance ✨ Leaves hair soft while maintaining scalp freshness ✔️ Ideal for dry, sensitive, or unbalanced scalp [Key Features] ✅ Scalp-focused care (not just hair surface) ✅ Helps balance oil and moisture levels ✅ Improves scalp cleanliness and comfort ✅ Cooling and refreshing effect ✅ Supports healthier-looking hair environment ✅ Suitable for all scalp types (variant-based use) [Key Ingredients] 🧂 Sea Salt — exfoliates and removes buildup 🌿 Tea Tree / Menthol — cooling and soothing scalp care 🧬 Folligen Complex — supports scalp vitality 💧 Panthenol — hydration and soothing 🛡️ Niacinamide — scalp balance and care [How to Use] 🧂 Exfoliator 1️⃣ Apply to wet scalp before shampoo 2️⃣ Gently massage 3️⃣ Rinse thoroughly 4️⃣ Follow with shampoo 🧴 Conditioning Mask 1️⃣ After shampoo, apply to scalp and hair 2️⃣ Leave for 3–5 minutes 3️⃣ Rinse thoroughly [Safety / Store Notice] ⚠️ For external use only ⚠️ Avoid contact with eyes ⚠️ Stop use if irritation occurs 📌 Store away from direct sunlight and high temperatures', 193.5, 182.99, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134207-820n2-mndlj3v127lwfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F56704492158', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
