INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50306245765', 'Calça Legging Lupo Sem Costura Canelada Feminina - Rosa Claro', 'A Calça Legging Lupo Sem Costura Canelada Feminina é ideal para quem busca conforto e praticidade na hora de se exercitar. Feita com 96% poliamida e 4% elastano, a legging possui tecnologia Seamless, que evita costuras incômodas e proporciona maior liberdade de movimento. Aposte na marca que visa qualidade e autenticidade nas suas combinações, vai de Lupo!', 219.9, 199.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-82616-mks859f15lad50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F50306245765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
