INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997732451', 'Lampada LED Mini Dicroica MR11 4W Luz Branca 6500K Base GU10 Bivolt Avant', 'A lâmpada LED Dicróica é indicada para iluminação de destaque ou decorativa. Pode ser usada para substituir lâmpadas dicróicas halógenas de 35W. SOBRE A FABRICANTE A AVANT é uma empresa genuinamente brasileira, especializada em produtos para iluminação e posicionada entre as maiores empresas do segmento. É reconhecida pela excelência e qualidade de seus produtos e por manter uma grande e sólida parceria de longo prazo com seus clientes. Está presente em todos os estados brasileiros, com uma estrutura de profissionais aptos e experientes, prontos para atender as diversas necessidades de seus clientes, com eficiência e comprometimento. Prestigiada por profissionais e consumidores, é considerada pioneira no lançamento de produtos modernos e inovadores, presente na diversidade e qualificação de seu portfólio.', 16.9, 16.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdwd-ly0vdf1go1uud4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F21997732451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207435965', 'Camiseta Lost Joker Quadrinhos Collab', 'Camiseta Lost Joker Quadrinhos Collab Olha só quem conseguiu a collab com a Lost... Eu! Não é o morcegão, oh não! Parece que o Sr. Perfeição ficou de fora dessa! Batman? Sem collab, sem graça. Mas comigo e a Lost... Bom, o show tá só começando, HAHAHAHA!" Especificações do produto: · Collab especial Joker & Lost. · Modelagem Boxfit. · Reforço de gola. · Estampa localizada no peito e lateral da frente. · Estampa grande localizada nas costas. · Etiqueta Sanduíche localizada na barra costas. Composição: 100% Algodão. Sobre a marca Lost A marca de surf Lost foi fundada em 1987 pelo shaper Matt Biolos, conhecido como Mayhem, que começou a fazer suas próprias pranchas em uma loja em San Clemente, na Califórnia. Biolos se inspirava no ambiente de surf da região, onde convivia com shapers e surfistas talentosos, e também expressava sua criatividade nos desenhos das pranchas. O nome Lost surgiu de uma brincadeira com o fato de Biolos e seus amigos se sentirem deslocados da cena do surf mainstream, que se baseava apenas no uso de roupas de surf. Eles queriam criar um conceito mais moderno e irreverente para o surf, que fosse além das aparências. Em 1993, a marca lançou seus primeiros vídeos de surf, que mostravam um estilo de vida mais livre e divertido. Hoje, a Lost continua com o mesmo espírito, não seguindo tendências ou padrões, mas transmitindo sua identidade através de uma linha completa de roupas, acessórios e pranchas. A marca se define como a "ovelha negra" do surf, valorizando a liberdade, a inovação e a irreverência. Produto Original.', 189.99, 152.0, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-825zn-mm69q4j4505kfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490043415%2F58207435965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
