INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12736152697', 'Impermeabilizante Vidro Janela Parabrisa Repelente Dagua', 'Cristalizador de Vidros Visão na Chuva 105ml Visão na chuva é um impermeabilizante que forma uma película invisível no vidro do seu carro por um período máximo de até 30 dias, permitindo assim o fácil escorrimento da água dando uma visão excelente nos dias de Chuva Forte. Especificações: - Rende até 12 aplicações; - Conteúdo: 1 unidade Visão na Chuva 105ml; - Fabricante: NF Modo de Usar: 1. No vidro seco pelo lado externo aplique o produto em abundância; 2. Espalhe o produto com uma flanela em movimentos circulares deixando toda a superfície molhada; 3. Espere secar por aproximadamente 2 a 3 minutos e com uma flanela seca, lustre até dar brilho; 4. Reaplique quando necessário.', 31.99, 30.4, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-824i8-mekbp4gbwruu35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F521372664%2F12736152697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
