INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997473249', 'Kit 10 Telhas Colonial PVC 2,30x0,86cm 5 Ondas Permatti Vermelho/Ceramica Ceramica', 'O kit contém 10 unidades do produto. As Telhas de PVC Permatti são leves, resistentes, bonitas, econômicas e rápidas de instalar. Cheias de inovação, elas agregam inúmeros benefícios para a sua obra. Além de serem 80% mais leves, elas oferecem excelente isolamento térmico e acústico. Não propagam chamas, aliás são auto extinguíveis, possuem aditivos contra os raios UV e garantem à sua obra até 60% de economia de madeira para instalação e 50% de economia para mão de obra. Garantia: 5 Anos Inclinação: 15 Galvanizada: Não Comprimento (cm): 230 Modelo da Telha: Colonial Origem do Produto: Nacional Recursos Especiais: Termoacustica Material Principal Construção e Acabamento: PVC Marca: Permatti Cor: Ceramica Cor do Produto: Ceramica Cor Predominante: Vermelho Linha ou Coleção: Modelo Colonial Quantidade do Produto: 10', 1524.73, 1524.73, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqpdtxdttpn322', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23997473249', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
