INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097674221', 'Boneca Metoo Angela Malu', 'A Boneca Metoo Angela Malu está empolgada para aproveitar o calor. Desenvolvida exclusivamente para o Brasil, é indicada para crianças de todas as idades. Feita inteiramente em pelúcia, vem com maiô manga longa azul quadriculado e uma sandália de dedo super fofa! Os laços no cabelo com a mesma estampa do maiô dão todo um charme para a nossa Angela! Uma excelente opção para decorar ambientes infantis e presentear crianças e bebês. Perfeita para dormir abraçadinha, os bebês adoram. E o melhor: são colecionáveis. Não deixe de conferir os outros designs. ATENÇÃO: Este produto é original Metoo. Possui etiqueta em português, selo antifraude e toda a segurança comprovada pelo INMETRO. ESPECIFICAÇÕES: - Recomendado para crianças de todas as idades a partir de 0 meses; - Este brinquedo não tem restrição de idade; - Toque aveludado e cores vivas. COMPOSIÇÃO: - 100% poliéster e enchimento 100% fibra de poliéster. MEDIDAS APROXIMADAS: Boneca 33 cm: - Cabeça até pé: 33 cm. LIMPEZA E MANUTENÇÃO: - Aconselhamos lavar à mão. Caso use a máquina de lavar, indicamos rotação leve e temperatura máxima de 30º; - Não limpar a seco; - Não usar a secadora. SOBRE A MARCA: A Metoo é uma marca chinesa, criada em 2004, com o intuito de adicionar um toque de felicidade à nossa vida. Combinando os designs mais fofos e os materiais mais confortáveis, a Metoo projeta, desenvolve, fábrica e comercializa brinquedos de pelúcia e acessórios para a casa de alta qualidade. A filial brasileira da Metoo desenvolve produtos exclusivos com todo o toque de sofisticação, primando pela qualidade e segurança dos nossos pequenos. As bonecas de pano são colecionáveis, indicadas desde RN, perfeitas para decorar ambientes infantis e presentear crianças e bebês. Uma mais linda que a outra, a marca possui também diversos acessórios, pelúcias e modelos de bonecos para meninos. Conheça a coleção completa! Código Inmetro:003702/2019', 189.9, 189.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7reoc-m2jqb7pm8e68c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1240688238%2F20097674221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57962498354', 'Bíblia Sagrada | ARC | Capa Clássica', 'Tenha as Escrituras sempre à mão com a Bíblia Sagrada na tradução Almeida Revista e Corrigida (ARC), uma das versões mais tradicionais e amadas pelos leitores da Palavra de Deus. Nesta edição de bolso, você encontra praticidade para levar sua Bíblia a cultos, estudos, viagens e momentos de devoção diária. Com linguagem clássica e fiel ao texto bíblico, a ARC é amplamente utilizada por cristãos que apreciam a riqueza e a profundidade da tradução de João Ferreira de Almeida. Seu formato compacto facilita o transporte, permitindo que você mantenha a Palavra de Deus por perto em qualquer lugar. Destaques do produto:✔ Tradução Almeida Revista e Corrigida (ARC)✔ Formato de bolso, compacto e leve✔ Fácil de transportar no dia a dia✔ Linguagem clássica e tradicional✔ Ideal para cultos, estudos e devocionais✔ Ótima opção para presentear Uma edição prática para quem deseja carregar consigo a beleza e a tradição das Escrituras Sagradas. Título: Bíblia Sagrada | ARC | Capa Clássica Autor: Publicações Cordeiro Páginas: 900 Formato: 10 x 14 cm Peso: 0,360 kg ISBN: 9786583094797 Editora: Publicações Cordeiro Capa: Brochura Índice: Não Linguagem: Nova Versão Internacional Letra: Normal Palavras de Jesus em Vermelho: Não Fitilho: Não Edição: 2026', 12.9, 12.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824ic-mpnst0tcrlzh54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F57962498354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
