INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393205172', 'Jogo 2 Pneus Speedmax Aro 16 Controlmax SUV SP10 235/70R16 106H', 'Marca: SPEEDMAX Modelo: CONTROLMAX SUV SP10 Medida: 235/70R16 Largura: 235 Perfil: 70 Tamanho de Aro: 16 Índice de peso: 106 - 950 kg, 106 Índice de velocidade: H - 210 km/h, H Tipo de Veiculo: SUV Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: ASSIMÉTRICO UTGQ: N/A Adesão à àgua: C Eficiência energética: E Ruído externo: 72 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a SpeedMax A SpeedMax produz pneus para todos os tipos de veículo, com qualidade e custo que ao encontro com a sua busca por um pneu com ótima dirigibilidade, desempenho e economia para ter o máximo em qualquer situação - do campo ao asfalto. Pensados em Centros de Pesquisa e Desenvolvimento em países como China, Vietnã, Índia e Paquistão, a SpeedMax também tem produção feita no México e é homologada nos principais mercados, como Brasil e Estados Unidos.', 1447.96, 1332.13, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdxp-lygnmr3oqeiu93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22393205172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693186309', 'Jogo 2 Pneus Kumho Aro 14 ES31 185/65R14 86T', 'Marca: KUMHO Modelo: ES31 Medida: 185/65R14 Largura: 185 Perfil: 65 Tamanho de Aro: 14 Índice de peso: 86 - 530 kg Índice de velocidade: T - 190 km/h Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: ASSIMÉTRICO UTGQ: N/A Adesão à àgua: B Eficiência energética: C Ruído externo: 70 O pneu Kumho Ecowing ES31 é um modelo moderno, de ótimo desempenho e economia. Trata-se de um pneu com baixa resistência ao rolamento, que utiliza polímeros de alto desempenho, sílica de alta dispersão e resinas de alta aderência, garantindo ótimo desempenho em pista molhada, baixo desgaste da borracha e menor consumo de combustível. É ainda um pneu com baixo ruído e ótimo nível de conforto. A banda de rodagem é assimétrica, com ampla área de contato com a pista, que proporciona frenagens e curvas seguras, mudanças de direção precisas e mesmo em piso molhado, toda a segurança necessária para dirigir com confiança, já que os sulcos trabalham de forma eficiente na expulsão da água. Sobre a marca Kumho A marca Kumho foi fundada em 1960 em Gwangju na Coreia do Sul. Os pneus Kumho são mundialmente conhecidos pela alta qualidade e aderência, pois usam matéria prima e processos de produção de primeira categoria. São pneus duráveis e confiáveis, e um ótimo indicativo disso, é que são pneus originais de fábrica de marcas como Hyundai, Kia e Chevrolet, entre outras. Pneu Kumho tem garantia de 5 anos e oferece segurança, conforto e economia na manutenção do seu carro.', 834.3, 767.56, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-lyb36m2yu5b60c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22693186309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
