INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258188325', 'Cola Para Glitter Stay Fix - Hb580 - Ruby Rose', 'A Cola para Glitter é um fixador que quando aplicado deixa a região resistente à água, lágrima, suor, fricção. Potente para colar glitter, pigmento e sombra por sua capacidade de formar uma leve película sobre a pele, garante um alto poder de fixação e durabilidade da maquiagem sem agredir a pele. Modo de Uso: Aplique uma camada fina sobre a área desejada espalhando bem, também pode ser misturado à maquiagem antes da aplicação. Secagem rápida. Usar de preferência demaquilante bifásico para facilitar a remoção. Indicado: Para ser usado na área dos olhos Precauções: Uso externo. Evite o contato com os olhos. Em caso de contato com os olhos, enxágue bem com água. Suspenda o uso se surgirem sinais de irritação. Mantenha fora do alcance de crianças. Mantenha o produto ao abrigo de luz e do calor. Validade: 10/2026 Peso: 10ml', 22.1, 17.91, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-81ztq-mmm40c4wj3ew67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1784788471%2F58258188325', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53311688862', 'Zeblaze Btalk 3 Plus Relógio inteligente com chamada de voz, tela colorida grande HD de 1,39'''', rastreamento de', '【Tela de Alta Resolução de 1,39 polegadas】Com tela colorida HD de 1,39", o Zeblaze Btalk 3 Plus se destaca pelo tamanho ampliado, cores vibrantes e resolução melhorada. Curvada para parecer natural no seu pulso, a tela é feita de vidro temperado com revestimento anti-impressão digital. Aproveite uma tela maior e um estilo mais inteligente. 【Design Super Fino e Leve】Pense fora das linhas e celebre o que o torna excepcional com o elegante Zeblaze Btalk 3 Plus. Com apenas 12,1 mm de espessura e incrivelmente leve, pesando apenas 22,7 g, o Btalk 3 Plus parece compacto e muito confortável de usar graças à pulseira de silicone líquido amiga da pele. 【Gestão de Saúde 24/7 Fácil】É o dispositivo definitivo para uma vida mais saudável e ativa, capaz de medir a saturação de oxigênio no sangue, monitorar a frequência cardíaca o dia todo e fornecer alertas para frequência cardíaca anormal, níveis de estresse e rastreamento do sono, além de registrar o ciclo menstrual feminino. 【Alcance Metas de Treino Maiores】O relógio fitness Zeblaze Btalk 3 Plus oferece mais de 100 modos esportivos, permitindo que você obtenha dados para todos os seus esportes favoritos, como caminhada, corrida e ciclismo, bem como treinos mais livres como musculação, ioga e muito mais. 【O Assistente Pessoal Perfeito】Assistente de Voz Integrado e Compatível com Assistente de Voz Offline. Conectado via Bluetooth ao seu telefone, o relógio pode ser usado para receber e atender chamadas. 【Mostradores de Relógio que Pintam um Retrato de Estilo】Combine com seu humor, roupa e ocasião, com uma ampla seleção de mais de 300 mostradores estilosos. 【Seu Parceiro Inteligente】Sincronize com seu telefone para receber notificações de SMS/chamadas/aplicativos e controle a reprodução de música e a câmera do seu telefone diretamente no seu pulso. O smartwatch também oferece lembretes de inatividade, modo "não perturbe", listas de tarefas e funções de previsão do tempo, além de permitir o ajuste de alarmes e cronômetros. 【Observação Importante】 Os dados de oxigênio no sangue, frequência cardíaca e outros medidos neste produto são apenas para referência de saúde e uso recreativo, não têm valor diagnóstico médico e não podem ser usados como base para diagnóstico. Os resultados são apenas para referência.', 117.0, 70.92, NULL, 'Mobile & Gadgets > Wearable Devices > Smartwatches & Fitness Trackers', 'https://cf.shopee.com.br/file/sg-11134201-823r4-mp7wxchbr01u82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F53311688862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42207197411', 'Cobertor Casal\Queen\Solteiro Manta Toronto Flannel 280g/m² Super Grossa Inverno Coberta Coberdrom', 'Cobertor Manta Toronto Flannel 280g/m² – Inverno Ultra Macio e Aconchegante Descubra o conforto incomparável da Manta Toronto, desenvolvida para proporcionar máximo aquecimento nos dias frios. Com flannel de 280g/m² e acabamento em alto relevo, esse cobertor une suavidade, beleza e qualidade em um único produto. Características: • Tecido Flannel Ultra Soft • Gramatura alta: 280g/m² • Toque macio e aconchegante • Acabamento refinado com bainha • Estampa com textura em alto relevo • Secagem rápida e fácil manutenção • 100% Poliéster Tamanhos disponíveis: • Solteiro – 1,50m x 2,20m • Casal – 1,80m x 2,20m • Queen – 2,20m x 2,40m Composição: Tecido 100% Poliéster – Flannel 280g/m² Fabricado por: Andreza Enxovais Vendido por: LaTu Magazine Ideal para quem busca um cobertor elegante, térmico e resistente para o inverno.', 134.99, 106.99, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/br-11134207-820lw-mqvzp89821hi88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443294432%2F42207197411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
