INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494794968', 'Quem Disse, Berenice? POP Batom Semi Mate Vermelho Icônico 3,6g', 'Quem Disse, Berenice? POP Batom Semi Mate Vermelho Icônico é um item essencial para sua make do dia a dia. Ele entrega cor intensa e uniforme aos lábios. Possui alta cobertura e um acabamento semi mate incrível. O Batom Vermelho Icônico POP proporciona um deslizamento confortável. Faz parte da linha QDB POP, unindo praticidade em produtos essenciais. Lábios coloridos e confortáveis para qualquer ocasião. Nenhum produto O Quem Disse, Berenice? é Testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 18.9, 18.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-8262a-mjhh51eoar5t08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1671118112%2F22494794968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397544854', 'Formula Infantil Nanlac Supreme 1 a 3 800g', 'Nanlac® Supreme é uma fórmula infantil destinada a crianças de 1 a 3 anos de idade. Com uma composição desenvolvida para suportá-las nessa fase. A melhor fórmula infantil para a 1ª infância, desenvolvido com proteína exclusiva e teor adequado de ômega 3 (DHA + EPA). O Ministério da Saúde informa: o aleitamento materno evita infecções e alergias e é recomendado até os 2 (dois) anos de idade ou mais. O Ministério da Saúde informa: após os 6 (seis) meses de idade continue amamentando seu filho e ofereça novos alimentos.', 128.25, 128.25, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-lvj7z5r9cmrcaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22397544854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393009153', 'Desodorante Aerosol Rexona Men Clinical Sport 150ml', 'O Desodorante Masculino Rexona Men Clinical é o produto ideal para te deixar seguro contra a transpiração e o mau odor. Ele proporciona proteção avançada que dura até 96 horas, graças a sua tecnologia avançada que forma um micro escudo protetor sobre a pele. É 3 vezes mais potente contra o suor e traz em sua fórmula a tecnologia MotionSense, que se ativa com o movimento. Basta apenas uma aplicação para se sentir protegido durante todo o dia, com sensação de refrescância prolongada.', 25.19, 25.19, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rd48-lvavig3vjspka4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22393009153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
