INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47464668881', 'Lakerain 30ml Autocobertura Corporal e para Pernas – À Prova d’Água, Cobre Tatuagens, Acabamento Uniforme da Pele', '✨ **Pernas Perfeitas Instantaneamente com Lakerain MAQUIAGEM PARA PERNAS** ✨ 🔑 **Características principais:** - **Disfarça imperfeições** (cicatrizes, veias, manchas) para uma pele uniforme e natural - **Hidratação** que mantém as pernas hidratadas - **À prova d''água e resistente à transferência** para uso o dia todo - **Cobertura duradoura** - **Fácil de esfumar** para um acabamento uniforme 📝 **Informações do produto:** - Marca: Lakerain - Peso líquido: 30 ml - Validade: 3 anos 📋 **Como usar (passo a passo):** 1. **Aplicar:** Esprema o creme uniformemente nas pernas; deixe secar por 5–10 minutos. 2. **Esfumar e fixar:** Dê batidinhas leves com papel toalha ou esponja de maquiagem para absorver o excesso e aperfeiçoar o acabamento. Desfrute de uma pele naturalmente bonita e impecável o dia todo! 💡 **Dica:** Ideal para usar com saias, shorts e looks de pé aberto – sem manchas, só confiança!', 27.3, 21.0, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134253-8258s-mqxslb5hpkau73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F47464668881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
