INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297500957', 'Caminhão de Bombeiro Kendy Kraft', 'O incrível Caminhão de Bombeiro Kendy Kraft é muito mais do que apenas um brinquedo - é uma janela para um mundo cheio de coragem, ação e resgate heroico. Possui escada articulável, que acrescenta uma dose extra de realismo e emoção à brincadeira. Você pode estender a escada, girá-la e imaginar-se subindo corajosamente até alturas impressionantes para resgatar pessoas em perigo. Essa característica única permite que você recrie cenas emocionantes de resgates audaciosos, dando asas à sua imaginação e inspirando histórias empolgantes.Não há nada como a sensação de ser um herói do Corpo de Bombeiros, e com o Caminhão de Bombeiro Kendy Kraft, as crianças poderão mergulhar de cabeça nesse papel empolgante. Sinta a adrenalina enquanto você dirige o caminhão em alta velocidade, sirenes uivando, em direção a um incêndio fictício para salvar o dia. Cada detalhe foi cuidadosamente projetado para proporcionar a você a experiência mais autêntica e envolvente possível.Além da sua funcionalidade incrível, o Caminhão de Bombeiro Kendy Kraft é um espetáculo para os olhos. Seu design super elegante e bonito vai conquistar os pequenos. Com dimensões aproximadas de 39cm de comprimento, 22cm de altura e 21cm de largura, ele possui o tamanho ideal para se destacar em sua brincadeira e impressionar a todos com seu realismo e detalhes. As crianças poderão vivenciar momentos empolgantes e inspiradores, enquanto se tornam mestres das operações de resgate.', 39.99, 39.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-825a1-mqytlwrd4lqk39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23297500957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
